INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('013915fe-91dd-11f0-a6c6-a233a240566f', '𝐏𝐫𝐞𝐬𝐞𝐧𝐭𝐚𝐭𝐢𝐨𝐧 𝐨𝐟 𝐭𝐡𝐞 𝐑𝐞𝐯𝐢𝐬𝐞𝐝 𝐏𝐫𝐨𝐠𝐫𝐚𝐦 𝐨𝐟 𝐑𝐞𝐜𝐞𝐢𝐩𝐭𝐬 & 𝐄𝐱𝐩𝐞𝐧𝐝𝐢𝐭𝐮𝐫𝐞𝐬 (𝐏𝐑𝐄) 𝐚𝐭 𝐍𝐄𝐌𝐒𝐔 𝐓𝐚𝐧𝐝𝐚𝐠 𝐂𝐚𝐦𝐩𝐮𝐬', '𝐑𝐞𝐯𝐢𝐬𝐞𝐝-𝐏𝐫𝐨𝐠𝐫𝐚𝐦-𝐨𝐟-PRE', 'The presentation of the Revised Program of Receipts & Expenditures (PRE) is currently taking place at the University Board Room, 2nd Floor, Administration Building, NEMSU Tandag Campus. T', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐯𝐢𝐬𝐞𝐝-𝐏𝐫𝐨𝐠𝐫𝐚𝐦-𝐨𝐟-PRE 1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐯𝐢𝐬𝐞𝐝-𝐏𝐫𝐨𝐠𝐫𝐚𝐦-𝐨𝐟-PRE 2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐯𝐢𝐬𝐞𝐝-𝐏𝐫𝐨𝐠𝐫𝐚𝐦-𝐨𝐟-PRE 3.jpg\" /></div>\r\n</div>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe presentation of the Revised Program of Receipts & Expenditures (PRE) is currently taking place at the University Board Room, 2nd Floor, Administration Building, NEMSU Tandag Campus. The activity commenced at 10:00 AM today, August 29, 2025, and is still ongoing.\r\n<br/><br/>\r\nThe University President delivered the opening message, underscoring the importance of sound fiscal planning and collaborative efforts in sustaining institutional growth. This initiative is aligned with NEMSU’s Vision of becoming a Research University advancing technology and innovation for sustainable development and supports the INNOVATE Agenda in ensuring transparent, efficient, and responsive financial management practices.\r\n<br/><br/>\r\nIn attendance are the Vice President for Administration and Finance (VPAF), Vice President for Academic Affairs (VPAA), Vice President for Planning and Strategic Initiatives (VPPSI), Budget Officer III, Administrative Officer V of the Procurement Office, Campus Directors of Tandag, San Miguel, and Cagwait, as well as the Campus Budget Officers and Campus Procurement Officers of the seven campuses of NEMSU.\r\n<br/><br/>', '𝐑𝐞𝐯𝐢𝐬𝐞𝐝-𝐏𝐫𝐨𝐠𝐫𝐚𝐦-𝐨𝐟-PRE.jpg', 'Public Information Office', 0, 'news', 1, '2025-08-29 10:34:03', NULL, NULL),
('01fe4074-d11c-11ee-aa14-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐫𝐞𝐜𝐚𝐥𝐢𝐛𝐫𝐚𝐭𝐞𝐬 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜 𝐃𝐞𝐯𝐞𝐥𝐨𝐩𝐦𝐞𝐧𝐭', 'Recalibrates-2024', 'With the goal of advancing NEMSU on the map of premier academic excellence, officials, academic and administrative individuals of the system convened for the writeshop on the realignment of and recalibration of the strategic development plan of NEMSU in Cagwait, Surigao del Sur, at February 21, 2024.', '<div class=\"row\">\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-01.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-02.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-03.jpg\" /></div>\n</div>\n<br>\n<div class=\"row\">\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-04.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-05.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-06.jpg\" /></div>\n</div>\n<br>\n<div class=\"row\">\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-07.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-08.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reca-09.jpg\" /></div>\n</div>\n<br>\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\nWith the goal of advancing NEMSU on the map of premier academic excellence, officials, academic and administrative individuals of the system convened for the writeshop on the realignment of and recalibration of the strategic development plan of NEMSU in Cagwait, Surigao del Sur, at February 21, 2024. <br>\nThe three-day writeshop aimed that the 8-point priority agenda of the current administration align with the existing goals and objectives of major functions and key areas.\n<br/>', 'reca-11.jpg', 'Public Information Office', 0, 'news', 1, '2024-02-21 17:50:11', '2024-02-21 17:50:11', '2024-02-21 17:50:11'),
('02df94af-6dec-11f0-ae5d-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐒𝐔𝐏𝐏𝐎𝐑𝐓𝐒 𝐍𝐀𝐓𝐈𝐎𝐍𝐀𝐋 𝐃𝐈𝐒𝐀𝐒𝐓𝐄𝐑 𝐑𝐄𝐒𝐈𝐋𝐈𝐄𝐍𝐂𝐄 𝐌𝐎𝐍𝐓𝐇 𝟐𝟎𝟐𝟓', '𝐍𝐄𝐌𝐒𝐔-𝐒𝐔𝐏𝐏𝐎𝐑𝐓𝐒-𝐍𝐀𝐓𝐈𝐎𝐍𝐀𝐋-𝐃𝐈𝐒𝐀𝐒𝐓𝐄𝐑-𝐑𝐄𝐒𝐈𝐋𝐈𝐄𝐍𝐂𝐄-𝐌𝐎𝐍𝐓𝐇-𝟐𝟎𝟐𝟓', 'North Eastern Mindanao State University joins the nation in observing National Disaster Resilience Month (NDRM) this July 2025', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University joins the nation in observing National Disaster Resilience Month (NDRM) this July 2025, fully supporting the initiative of the City of Tandag—KUMIKILOS (Kayang Umaksyon ng Mamamayan na Isabuhay ang Kahandaan ng Bawat Isa Para Maging Ligtas sa Oras ng Sakuna).\r\n\r\n<br/><br/>\r\nThis year’s theme reinforces the importance of collective action, preparedness, and community awareness in building a safer and more resilient Philippines. Through campus-wide activities, awareness campaigns, and inter-agency cooperation, NEMSU remains committed to empowering communities and fostering a culture of safety and resilience.\r\n<br/><br/>\r\n#NDRM2025 #KUMIKILOS #NEMSUCares #ResilienceInAction', '𝐍𝐄𝐌𝐒𝐔 𝐒𝐔𝐏𝐏𝐎𝐑𝐓𝐒 𝐍𝐀𝐓𝐈𝐎𝐍𝐀𝐋 𝐃𝐈𝐒𝐀𝐒𝐓𝐄𝐑 𝐑𝐄𝐒𝐈𝐋𝐈𝐄𝐍𝐂𝐄 𝐌𝐎𝐍𝐓𝐇 𝟐𝟎𝟐𝟓.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-02 16:52:40', NULL, NULL),
('03c814fb-8351-11ee-bea4-a233a240566f', 'DICT on Cyber Security and PNPKI Training and Awareness hosted by the Main Campus thru the ICT Department.', 'DICT-PNPKI', 'DICT on Cyber Security and PNPKI Training and Awareness hosted by the Main Campus thru the ICT Department.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pnpk-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n', 'pnpki-00.jpg', 'Office of the Campus Director - Tandag', 1, 'news', 1, '2023-11-06 11:50:11', '2023-11-06 11:50:11', '2023-11-06 11:50:11'),
('0467646d-ea67-11ee-987e-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐌𝐚𝐢𝐧 𝐂𝐚𝐦𝐩𝐮𝐬 𝐰𝐫𝐚𝐩𝐬 𝐮𝐩 𝐍𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐖𝐨𝐦𝐞𝐧’𝐬 𝐌𝐨𝐧𝐭𝐡 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐢𝐨𝐧', 'National-Women\'s-Month-2024', 'NEMSU Main workforce concluded its celebration of National Women\'s Month with a culmination program, highlighting the different talks on achievements, wellness, and stories of women in history.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Womens-Month/PCW-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU Main workforce concluded its celebration of National Women\'s Month with a culmination program, highlighting the different talks on achievements, wellness, and stories of women in history. Held at the Prospero Pichay Sr. Gymnasium on March 20, 2024, the event brought together key officials, faculty, staff, and resource persons to honor the progress made in advancing gender equality and women\'s empowerment.\r\n<br><br>\r\nThe event celebrated the theme, “Lipunang Patas sa Bagong Pilipinas, Kakayahan ng Kababaehan, Patutunayan” with talks on financial literacy, mindfulness, emotional regulation techniques, and women\'s empowerment.\r\nMs. Marecris E. Monteklaro, AFT, resource person on financial literacy, provided practical insights into budgeting, saving, investing, and debt management, empowering participants to make informed decisions and secure their financial futures.\r\n<br><br>\r\nIn the afternoon, Dr. Gina R. Lamzon, a Clinical EFT Certified Practitioner, emphasized on mindfulness and gender equality. With expertise in emotional wellness, Dr. Lamzon shared insights into emotional regulatory techniques and self-awareness.\r\n<br><br>\r\nMeanwhile, Ms. Jana Jean G. Dacobor, IO Development Trainer, addressed subjects of women empowerment and history. With her expertise in organizational development and a deep appreciation for women\'s roles in shaping society, Ms. Dacobor reminded the audience of women’s resiliency throughout the ages.\r\n<br><br>\r\nIn essence, NEMSU\'s culmination program served as a resounding tribute to the resilience, strength, and accomplishments of women globally, reaffirming the institution\'s unwavering resolve to champion their rights and aspirations.\r\n<br/>', 'PCW-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-03-23 13:15:14', '2024-03-23 13:15:14', '2024-02-21 17:50:11'),
('04e51514-4c4f-11ee-b55e-a233a240566f', 'Promising Partnership:NEMSU Inks Historic MOA Signing with Stakeholders', 'MOA-Signing-2023', 'In a groundbreaking move that promises to reshape the landscape of education and community engagement, North Eastern Mindanao State University - NEMSU and LGU San Miguel,', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-2023-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a groundbreaking move that promises to reshape the landscape of education and community engagement, North Eastern Mindanao State University - NEMSU and LGU San Miguel, Magroyong Farmers Multipurpose Cooperative (MAFAMUCO), Hugpong Tribal Council San Miguel Farmers Association, Philippine Fiber Development Authority (PhilFIDA), and Provincial Govt Unit of Surigao del Sur have officially inked a historic Memorandum of Agreement (MOA). <br><br>\r\n1. MOA between LGU San Miguel, Magroyong Farmers Multipurpose Cooperative (MAFAMUCO) and NEMSU for establishment, development and sustenance of San Miguel Farmers Enterprise.<br><br>\r\n2. MOA between LGU San Miguel, Hugpong Tribal Council San Miguel Farmers Association and NEMSU for the establishment, development and sustenance of a Manobo Cultural Farming Heritage Complex.<br><br>\r\n3. MOA between NEMSU and Philippine Fiber Development Authority (PhilFIDA) for the establishment, development and sustenance of Regional Integrated Fiber Crops Resource Center.<br><br>\r\n4. MOA between Provincial Govt Unit of Surigao del Sur and NEMSU for the establishment, development and sustenance of Provincial Integrated Plant and Animal Resource.<br><br>\r\nThis MOA signifies a commitment to collaboration, innovation, and mutual growth. Our shared vision of enhancing education, research, and community engagement aligns perfectly with this partnership. Together, we will create opportunities for our students, faculty, and the community at large.\r\n\r\n', 'Moa-signing-2023.jpg', 'Public Information Office', NULL, 'news', 1, '2023-09-05 10:33:11', '2023-09-05 10:33:11', '2023-09-05 10:33:11'),
('077d0066-2213-11ee-816f-a233a240566f', 'NEMSU LIBRARIANS ATTENDED THE PLAI NATIONAL CONGRESS', 'Plai-Congress', '', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>The Philippine Librarians Association, Inc. (PLAI), in partnership with the National Commission for Culture and the Arts (NCCA) through the National Committee on Library and Information Services (NCLIS), and the National   Library of the        Philippines (NLP),   conducted its Annual National Congress last        November   22-25, 2022 at the Iloilo     Convention Center,    Iloilo City.\r\n<br><br>\r\n\r\nThis year’s Congress has the theme: “Working Together: Sustainability, Opportunity, Adaptability, Resiliency (SOAR)” NEMSU Librarians from Tandag,   Cantilan, Lianga and San Miguel   attended the said Congress.\r\n\r\n<br><br>\r\n\r\nThere were plenary sessions and   parallel sessions sponsored by sectoral    library associations to discuss topics     relevant to the different type of libraries (i.e.,  academic, public, school, and     special). \r\n<br><br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md6 col-sm-6 col-lg-6\">\r\n  <img alt=\"\" class=\"img img-responsive large\" src=\"/public_files/images/library/plai.jpg\" />\r\n</div>\r\n\r\n</div>\r\n</span></p>', 'plai01.jpg', 'University Library', 10, 'news', 1, '2022-11-25 08:09:53', '2022-11-25 08:09:53', '2022-11-25 08:09:53'),
('07bac443-df43-11ee-987e-a233a240566f', '𝐂𝐎𝐌 𝐂𝐨𝐦𝐦𝐢𝐭𝐭𝐞𝐞 𝐑𝐞𝐜𝐚𝐩𝐬', 'COm-Committee-Recaps-2024', 'The committee on the Application for the College of Medicine (COM) convened in the NEMSU New Board Room for the recapitulation and progress-tracking of the documentary requirements relevant to the unified CHED TPME-PRCTOOL for the application for government permit for the Doctor of Medicine program. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medi-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medi-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medi-03.jpg\" /></div>\r\n</div>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe committee on the Application for the College of Medicine (COM) convened in the NEMSU New Board Room for the recapitulation and progress-tracking of the documentary requirements relevant to the unified CHED TPME-PRCTOOL for the application for government permit for the Doctor of Medicine program. Led by the Vice President for Academic Affairs, Dr. Maria Lady Sol A. Suazo, the committee discussed the improvements made from the previous writeshop, which was Phase 1 of the application endeavor, including the new College of Medicine logo, and the enhancement of the feasibility study. The rest of the committees expressed their commitment to comply with the requirements and fast-track the compliance before the presentation with the consultants on March 18, 2024.\r\n<br/>', 'medi-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-03-07 17:27:01', '2024-03-07 17:27:01', '2024-03-07 17:27:01'),
('07dbdc0d-f416-11ef-b8b6-a233a240566f', '𝗣𝗥𝗖 𝗿𝗲𝗰𝗼𝗴𝗻𝗶𝘇𝗲𝘀 𝗡𝗘𝗠𝗦𝗨 𝗧𝗮𝗴𝗯𝗶𝗻𝗮 𝗮𝘀 𝘁𝗼𝗽 𝘀𝗰𝗵𝗼𝗼𝗹 𝗶𝗻 𝘁𝗵𝗲 𝗣𝗵𝗶𝗹𝗶𝗽𝗽𝗶𝗻𝗲𝘀', '𝗣𝗥𝗖-𝗿𝗲𝗰𝗼𝗴𝗻𝗶𝘇𝗲𝘀-𝗡𝗘𝗠𝗦𝗨-𝗧𝗮𝗴𝗯𝗶𝗻𝗮-𝗮𝘀-𝘁𝗼𝗽-𝘀𝗰𝗵𝗼𝗼𝗹-𝗶𝗻-𝘁𝗵𝗲-𝗣𝗵𝗶𝗹𝗶𝗽𝗽𝗶𝗻𝗲𝘀', 'BUTUAN CITY – The Professional Regulation Commission (PRC) awarded North Eastern Mindanao State University (NEMSU) Tagbina Campus a Certificate of Recognition for its outstanding performance in the September 2024 Licensure Examination for Teachers (LET) during the oath-taking ceremony of newly licensed professional teachers today at the FSUU Gymnasium, Butuan City.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nBUTUAN CITY – The Professional Regulation Commission (PRC) awarded North Eastern Mindanao State University (NEMSU) Tagbina Campus a Certificate of Recognition for its outstanding performance in the September 2024 Licensure Examination for Teachers (LET) during the oath-taking ceremony of newly licensed professional teachers today at the FSUU Gymnasium, Butuan City.\r\n\r\n<br/><br/>\r\nNEMSU Tagbina ranked Top 2 in the BEED Licensure Examination and Top 5 in the BSED Licensure Examination nationwide, affirming its excellence in teacher education.\r\n<br/><br/>\r\nCampus Director Dr. Ariston O. Ronquillo and Department Chair Dr. Lyoid C. Hunahunan received the certificate on behalf of the university.\r\n<br/><br/>\r\nPhoto Courtesy of Dr. Lyoid C. Hunahunan', '𝗣𝗥𝗖-𝗿𝗲𝗰𝗼𝗴𝗻𝗶𝘇𝗲𝘀-𝗡𝗘𝗠𝗦𝗨-𝗧𝗮𝗴𝗯𝗶𝗻𝗮-𝗮𝘀-𝘁𝗼𝗽-𝘀𝗰𝗵𝗼𝗼𝗹-𝗶𝗻-𝘁𝗵𝗲-𝗣𝗵𝗶𝗹𝗶𝗽𝗽𝗶𝗻𝗲𝘀.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-14 15:44:52', NULL, NULL),
('07f1bd16-6e2d-11ee-a3fc-a233a240566f', 'USAPANG GSIS: In an effort to safeguard and update the remittances of NEMSU employees the GSIS personnel meet with the NEMSU', 'Usapang GSIS', 'In an effort to safeguard and update the remittances of NEMSU employees the GSIS personnel meet with the NEMSU management spearheaded by the Human Resource and the Admin and Finance Units.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nUSAPANG GSIS: In an effort to safeguard and update the remittances of NEMSU employees the GSIS personnel meet with the NEMSU management spearheaded by the Human Resource and the Admin and Finance Units. Both parties propose orientation for newly hired and retirement coaching as a way forward.<br><br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gsis-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n', 'gsis-00.jpg', 'Office of the Campus Director - Tandag', NULL, 'news', 1, '2023-10-18 19:50:21', '2023-10-18 19:50:21', '2023-10-18 19:50:21'),
('08304332-f865-11ed-affb-a600064b4626', 'Congratulations! Elvinjan Jabagat Acuṅa', 'NEMSU-LEPT-top8', '', '<p align=\"justify\"><b>Elvinjan Jabagat Acuṅa</b> of NEMSU Lianga Campus formerly Surigao del Sur State University for being TOP 8 in the Licensure Examination for Teachers (LET) 2023 Secondary Level.</p>', 'LET-TOP8.jpg', 'Public Information Office', NULL, 'news', 0, '2023-05-19 16:10:07', '2023-05-19 16:10:07', '2023-05-19 16:10:07'),
('0b8148f2-86f2-11f0-a6c6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐇𝐨𝐥𝐝𝐬 𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧 𝐒𝐞𝐬𝐬𝐢𝐨𝐧 𝐚𝐧𝐝 𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩 𝐟𝐨𝐫 𝟐𝟎𝟐𝟓 𝐓𝐇𝐄 𝐈𝐦𝐩𝐚𝐜𝐭 𝐑𝐚𝐧𝐤𝐢𝐧𝐠𝐬 𝐀𝐩𝐩𝐥𝐢𝐜𝐚𝐭𝐢𝐨𝐧', '𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩', 'North Eastern Mindanao State University (NEMSU) officially commenced its Validation Session and Writeshop for the University’s application to the 2025 Times Higher Education (THE) Impact Rankings, today, August 7, 2025, at the University Boardroom, Administration Building, NEMSU Tandag Campus.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩-3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩-4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩-5.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) officially commenced its Validation Session and Writeshop for the University’s application to the 2025 Times Higher Education (THE) Impact Rankings, today, August 7, 2025, at the University Boardroom, Administration Building, NEMSU Tandag Campus.\r\n<br/><br/>\r\nThe two-day activity, running until August 8, is spearheaded by the Office of the Vice President for Research and Extension under the leadership of Dr. Rolly G. Salvaleon, VPRE. It aims to ensure that NEMSU’s data submissions align with global standards in support of the United Nations Sustainable Development Goals (SDGs).\r\nUniversity President Dr. Nemesio G. Loayon delivered an inspiring message during the opening program, affirming the administration\'s full support for the University\'s commitment to sustainability, global engagement, and evidence-based impact reporting.\r\n<br/><br/>\r\nServing as the resource person, Dr. Arnold C. Alguno shared his valuable insights and technical guidance in navigating the requirements of the THE Impact Rankings. His expertise contributes significantly to enhancing the quality and credibility of NEMSU’s institutional data and SDG-driven initiatives.\r\nThis initiative underscores NEMSU’s continuous pursuit of excellence and global visibility through sustainable development and transformative education.\r\nPadayon sa Pag-ALPAS NEMSU!\r\n<br/><br/>\r\nPhoto Courtesy of NEMSU Information Unit and OVPRE', '𝐍𝐄𝐌𝐒𝐔-𝐇𝐨𝐥𝐝𝐬-𝐕𝐚𝐥𝐢𝐝𝐚𝐭𝐢𝐨𝐧-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-𝐚𝐧𝐝-𝐖𝐫𝐢𝐭𝐞𝐬𝐡𝐨𝐩-1.jpg', 'Public Information Office', 0, 'news', 1, '2025-08-15 04:42:55', NULL, NULL),
('0c4d221f-3cbf-11ee-a66e-a233a240566f', 'Cantilan Campus - Class Opening for A.Y. 2023-2024', 'Class-Can-2023', 'WELCOME to NEMSU Cantilan Campus our - 8,015 New,Old,Returnees and Transferees Students for the 1st Semester AY 2023 - 2024.', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cantilan-open-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nWELCOME to NEMSU Cantilan Campus our - 8,015 New,Old,Returnees and Transferees Students for the 1st Semester AY 2023 - 2024.\r\n<br/>\r\n', 'cantilan-open-00.jpg', 'NEMSU Cantilan Campus', 32, 'news', 1, '2023-08-16 19:41:52', '2023-08-16 19:41:52', '2023-08-16 19:41:52'),
('0d9aaeb8-c3b8-11ee-aa14-a233a240566f', '𝐍𝐨𝐫𝐭𝐡 𝐄𝐚𝐬𝐭𝐞𝐫𝐧 𝐌𝐢𝐧𝐝𝐚𝐧𝐚𝐨 𝐒𝐭𝐚𝐭𝐞 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐲 𝐂𝐚𝐦𝐩𝐮𝐬 𝐃𝐢𝐫𝐞𝐜𝐭𝐨𝐫𝐬 𝐒𝐡𝐨𝐰𝐜𝐚𝐬𝐞 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭𝐬 𝐚𝐧𝐝 𝐔𝐧𝐯𝐞𝐢𝐥 𝐕𝐢𝐬𝐢𝐨𝐧 𝐟𝐨𝐫 𝟐𝟎𝟐𝟒', '𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭𝐬-𝟐𝟎𝟐𝟒', 'In a significant event held on January 29, 2024, the campus directors of various North Eastern Mindanao State University (NEMSU) campuses gathered in the new boardroom to share their accomplishment reports and lay out their Annual Implementation Plan 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-0.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/achiev-6.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a significant event held on January 29, 2024, the campus directors of various North Eastern Mindanao State University (NEMSU) campuses gathered in the new boardroom to share their accomplishment reports and lay out their Annual Implementation Plan 2024.\r\n<br>\r\nThe boardroom was graced by the presence of three Vice Presidents, namely Dr. Ma. Lady Sol A. Suazo, Vice President for Academic Affairs; Ms. Catherine F. Salomon, Vice President for Administration and Finance; and Dr. Rolly G. Salvaleon, VPREIRGAS. The esteemed Campus Directors attending the meeting on-site included Dr. Abundio C. Miralles of NEMSU Tandag, Dr. Juancho A. Intano of NEMSU Cantilan, Dr. Ariston O. Ronquillo of NEMSU Tagbina, and Dr. Noelito B. Salcedo of NEMSU Cagwait, while Dr. Celmencia L. Sumagaysay of NEMSU San Miguel attended the meeting via Zoom.\r\n<br>\r\nOffering a comprehensive overview of the progress made across NEMSU\'s diverse campuses, each campus director presented their accomplishment reports. These reports delved into various facets, covering academic achievements, administrative milestones, and contributions to research and extension. Key highlights included improvements in student outcomes, innovative administrative processes, and notable research and extension initiatives.\r\n<br>\r\nFollowing the presentation, Dr. Suazo also engaged each campus director in a question-and-answer portion about the challenges they faced in their roles during these trying times. Each campus director, with eloquence and grace, shared insights into their qualifications, leadership styles, and the strategies they employed to persevere in their positions.\r\n<br>\r\nThe event underscored the paramount importance of strategic collaboration among the campus directors and vice presidents, with a collective vision aimed at moving NEMSU toward greater heights. These collaborative efforts set the stage for a transformative year marked by academic advancements, administrative efficiency, and innovative research and extension services.\r\n<br/>', 'achiev-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-30 11:18:23', '2024-01-30 11:18:23', '2024-01-30 11:18:23'),
('0f2db905-f419-11ef-b8b6-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀 𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹 𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁 𝗧𝗵𝗿𝗼𝘂𝗴𝗵 𝗠𝗢𝗔 𝗦𝗶𝗴𝗻𝗶𝗻𝗴 𝗳𝗼𝗿 𝗦𝗮𝗻 𝗠𝗶𝗴𝘂𝗲𝗹 𝗔𝗿𝗯𝗼𝗿𝗲𝘁𝘂𝗺', '𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴', 'February 21, 2025 — The Caraga Region’s commitment to sustainable environmental management took a significant step forward with the Ceremonial Memorandum of Agreement (MOA) Signing for the Management of San Miguel Arboretum / Reforestation Area for Dipterocarp Species, held at NEMSU San Miguel Campus.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-07.jpg\" /></div>\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-08.jpg\" /></div>\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nFebruary 21, 2025 — The Caraga Region’s commitment to sustainable environmental management took a significant step forward with the Ceremonial Memorandum of Agreement (MOA) Signing for the Management of San Miguel Arboretum / Reforestation Area for Dipterocarp Species, held at NEMSU San Miguel Campus.\r\n\r\n<br/><br/>\r\nThe event gathered key stakeholders from various government agencies, the academe, and the local community. Present during the MOA signing were DENR OIC Regional Director Ms. Maritess M. Ocampo, CENR Officer Mr. Joseph E. Langanlangan, OIC PENR Officer Mr. Adelfo R. Luengas, Jr., along with LGU and BLGU Officials, Tribal Leaders, Campus Director Dr.  Florife Urbiztundo, and NEMSU University President Dr. Nemesio G. Loayon. The event was also attended by faculty members, staff, and students of NEMSU San Miguel Campus, further emphasizing the university community’s active involvement in environmental initiatives.\r\n<br/><br/>\r\nIn his speech, Dr. Loayon expressed his gratitude and joy for the strong partnership between DENR, the National and Local Government Units, and NEMSU, particularly the San Miguel Campus, in advancing environmental conservation efforts. He emphasized that this collaboration marks a milestone in sustainable development, aligning with NEMSU’s vision of fostering ecological stewardship and research-driven initiatives.\r\n<br/><br/>\r\n“NEMSU is a research university, providing an avenue for both teachers and students to explore biodiversity, including various plant and animal species,” Dr. Loayon stated. He highlighted that the San Miguel Arboretum will serve as a living laboratory for scientific exploration and conservation efforts, benefiting students, researchers, and the broader community.\r\n<br/><br/>\r\nFurthermore, Dr. Loayon encouraged parents to continue supporting their children’s education, underscoring that investing in their future will contribute to the nation’s economic growth.\r\nThe MOA signing formalizes a long-term commitment to preserving the Dipterocarp species, a vital component of the region’s forest ecosystem. With the involvement of the DENR, local government units, and indigenous communities, this initiative is expected to create significant environmental, educational, and socio-economic impact.\r\n<br/><br/>\r\nThe event concluded with a renewed pledge from all parties to work together in ensuring the sustainability and protection of San Miguel Arboretum, reinforcing NEMSU’s role as a key player in environmental conservation and research in the Caraga Region.\r\n', '𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗘𝗻𝘃𝗶𝗿𝗼𝗻𝗺𝗲𝗻𝘁𝗮𝗹-𝗖𝗼𝗺𝗺𝗶𝘁𝗺𝗲𝗻𝘁-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴.jpg\r\n', 'Public Information Office', 0, 'news', 1, '2025-02-21 16:03:43', NULL, NULL),
('0f702182-0b3a-11ee-affb-a600064b4626', 'The North Eastern Mindanao State University - NEMSU participated in the opening ceremony of the 63rd Araw ng Surigao del Sur.', '63rd-Araw-ng-Surigao-del-Sur', '', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw05.jpg\" /></div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw06.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/araw08.jpg\" /></div>\r\n</div>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The North Eastern Mindanao State University - NEMSU participated in the opening ceremony of the 63rd Araw ng Surigao del Sur. This celebration commemorates the beautiful history of the province celebrating the present and envisioning the future of a progressive and dynamic Surigao del Sur. The event also showcases different product displays representing all municipalities of the province in its 2023 Agri-Fishery & Tourism Trade Fair.</span></p>', 'araw01.jpg', 'Public Information Office', NULL, 'news', 1, '2023-06-15 12:20:02', '2023-06-15 12:20:02', '2023-06-15 12:20:02'),
('0fb4aaab-91e3-11f0-a6c6-a233a240566f', 'Training on Thesis/Dissertation Advising, Paneling, and Publication', 'Training-on-Thesis-Dissertation-Advising', 'The Research and Innovation Office, led by Director Dr. Erwin B. Berry, and the Graduate School under the leadership of Dean Dr. Jennifer Montero, successfully spearheaded a 2-day Training on Thesis/Dissertation Advising, Paneling, and Publication on September 5-6, 2025 at the NEMSU New Board Room. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Training-on-Thesis-Dissertation-Advising 1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Training-on-Thesis-Dissertation-Advising 2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Training-on-Thesis-Dissertation-Advising 3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Training-on-Thesis-Dissertation-Advising 4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe Research and Innovation Office, led by Director Dr. Erwin B. Berry, and the Graduate School under the leadership of Dean Dr. Jennifer Montero, successfully spearheaded a 2-day Training on Thesis/Dissertation Advising, Paneling, and Publication on September 5-6, 2025 at the NEMSU New Board Room. \r\n<br/><br/>\r\nWith the full support of the University Vice Presidents and the University President, Dr. Nemesio G. Loayon, this initiative gathered key officials, graduate school faculty, visiting professors, and staff in a collaborative academic endeavor. The activity highlighted the institution’s strong commitment to strengthening research capacity and elevating scholarly outputs across its programs.\r\n<br/><br/>\r\nGuided by the expertise of Dr. Arnold C. Alguno, Research Management Director of MSU-IIT, participants engaged in intensive discussions and hands-on learning designed to improve their skills in thesis and dissertation advising. The sessions also covered the intricacies of research paneling and the fundamentals of producing publishable scholarly works. \r\n<br/><br/>\r\nThis training emphasized both academic rigor and practical strategies, ensuring that faculty members are better equipped to mentor students and contribute to high-quality research.\r\n<br/><br/>', 'Training-on-Thesis-Dissertation-Advising.jpg', 'Public Information Office', 0, 'news', 1, '2025-09-06 11:16:40', NULL, NULL),
('114603d8-f877-11ee-904a-a233a240566f', '𝟐𝐧𝐝 𝐐𝐮𝐚𝐫𝐭𝐞𝐫 𝐒𝐩𝐞𝐜𝐢𝐚𝐥 𝐉𝐨𝐢𝐧𝐭 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 & 𝐀𝐝𝐦𝐢𝐧𝐢𝐬𝐭𝐫𝐚𝐭𝐢𝐯𝐞 𝐂𝐨𝐮𝐧𝐜𝐢𝐥𝐬 𝐌𝐞𝐞𝐭𝐢𝐧𝐠 𝐅𝐘𝟐𝟎𝟐𝟒', '2nd-Quarter-Cant-2024', ' The key officials of North Eastern Mindanao State University (NEMSU), along with members of the academic and administrative councils from its seven (7) campuses, convene for the 2nd Quarter Special Joint Administrative and Academic Councils Meeting F.Y. 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-13.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-14.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cant-aco-2024/cant-aco-15.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe key officials of North Eastern Mindanao State University (NEMSU), along with members of the academic and administrative councils from its seven (7) campuses, convene for the 2nd Quarter Special Joint Administrative and Academic Councils Meeting F.Y. 2024. The event is taking place today, April 12, 2024, at NEMSU Cantilan Center for Culture and the Arts Gymnasium.\r\n<br/>', 'cant-aco-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-04-12 10:45:16', '2024-04-12 10:45:16', '2024-04-12 10:45:16'),
('11531f53-47ae-11ee-b55e-a233a240566f', 'NEMSU-CC Aces Pickeball ', 'local-masts-pickeball', '<p><span style=\"font-size:11.0pt\">Cantilan Campus secured all categories in pickleball, a first-time sports event being played in NEMSU’s Local MASTS, after a dominant win over Tandag Campus.</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">The winning players easily seized the golds by winning straight 2 sets in all categories, namely single, men’s and women’s double, and mixed double. Ma’am Loureville Gilda Urquia served as their coach.\r\n<br><br>\r\nIn a snap interview, Guybear Gil Samontina, the captain ball of team NEMSU Cantilan, highlighted the integration of their knowledge and skills in lawn tennis and table tennis as their key strategy in acing the game.\r\n<br><br>\r\n“An amo mga nahibay-an sa lawn tennis tapos sa table tennis kay hapit-hapit ra man gud sila… Ugsa amo ra kibale tag combine-combine sanan practice-practice para makuha ini na kadaugan,” said Samontina.\r\n<br><br>\r\nNEMSU Cantilan already joined the national games last year in pickleball beating the first-time players from the main campus in this year’s Local MASTS.\r\n<br><br>\r\nReport by Pemuel Prado<br>\r\nPhotos by Roger Bagood & Jhoana Marie Cabadonga\r\n<br><br>\r\n\r\n#TheVanguardPublication\r\n#LocalMASTS2023\r\n</span></span></p>', 'van-pickeball.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-30 16:33:11', '2023-08-30 16:33:11', '2023-08-30 16:33:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('11c28491-f418-11ef-b8b6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭 𝐋𝐞𝐚𝐝𝐬 𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧 𝐒𝐞𝐭𝐭𝐢𝐧𝐠 𝐒𝐞𝐬𝐬𝐢𝐨𝐧, 𝐄𝐦𝐩𝐡𝐚𝐬𝐢𝐳𝐞𝐬 𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡, 𝐈𝐧𝐧𝐨𝐯𝐚𝐭𝐢𝐨𝐧, 𝐚𝐧𝐝 𝐂𝐨𝐫𝐞 𝐕𝐚𝐥𝐮𝐞𝐬', '𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧', 'Cagwait, Surigao del Sur – The North Eastern Mindanao State University (NEMSU) Cagwait Campus hosted a Direction Setting Session cum Designees (New and Redesignated) Meeting on February 21, 2025. The event was graced by NEMSU President Dr. Nemesio G. Loayon, who outlined the university’s Vision, Mission, Core Values, and the 8-Point Strategic Directional Agenda.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧-07.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nCagwait, Surigao del Sur – The North Eastern Mindanao State University (NEMSU) Cagwait Campus hosted a Direction Setting Session cum Designees (New and Redesignated) Meeting on February 21, 2025. The event was graced by NEMSU President Dr. Nemesio G. Loayon, who outlined the university’s Vision, Mission, Core Values, and the 8-Point Strategic Directional Agenda.\r\n\r\n<br/><br/>\r\nIn his address, Dr. Loayon emphasized the crucial role of research in fulfilling NEMSU’s vision as a Research University, particularly within the academic community. He encouraged the attendees to embrace research-driven approaches in their respective fields, reinforcing that knowledge and expertise must be continuously enhanced through research and scholarly activities.\r\nDr. Mick Mars P. Silvano articulated the significance of the event, emphasizing its role in setting clear directions for the university’s growth and development.\r\n<br/><br/>\r\nThe President also introduced the upcoming ICT Unit Programs, which are the result of efforts from the ICT Unit, aligning with technology, innovation, and sustainable development. These programs, once finalized, will be launched soon and are expected to contribute significantly to the university’s modernization efforts.\r\nHighlighting the university’s Core Values—Compassion, Accountability, Responsiveness, Excellence, and Service (CARES)—Dr. Loayon urged faculty members and administrative personnel to uphold these values in their roles. He also extended his congratulations to the newly designated and redesignated officials, encouraging them to actively support and contribute to NEMSU’s continuous growth and development.\r\n<br/><br/>\r\nAs a Message for Commitment, Dr. Rozette Mercado, Campus Director of NEMSU Cagwait, extended heartfelt thanks to the University President for his presence and support in this activity. Following her message, the distribution of designation orders was conducted for the attendees.\r\nThe session concluded with a renewed commitment from the attendees to align their efforts with NEMSU’s strategic goals, ensuring that the university remains a leading institution in research, education, and service.\r\n', '𝐍𝐄𝐌𝐒𝐔-𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭-𝐋𝐞𝐚𝐝𝐬-𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧-𝐒𝐞𝐭𝐭𝐢𝐧𝐠-𝐒𝐞𝐬𝐬𝐢𝐨𝐧.jpg\r\n', 'Public Information Office', 0, 'news', 1, '2025-02-21 15:56:56', NULL, NULL),
('1314d970-e77c-4b02-81c5-1fa109ae51b5', 'NEMSU President, Dr. Nemesio G. Loayon, highlighted the importance of forging partnerships with several Universities and administrators undercharged with Commissioner Mark Libre', 'nemsu-president-dr-nemesio-g-loayon-highlighted-the-importance-of-forging-partnerships-with-several-universities-and-administrators-undercharged-with-commissioner-mark-libre', '<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">NEMSU President, Dr. Nemesio G. Loayon, highlighted the importance of forging partnerships with several Universities and administrators undercharged with Commissioner Mark Libre during the&nbsp; Flag Raising Ceremony hosted by the College of Engineering Technology (CET) on February 20, 2023. </span></span></p>', '<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">NEMSU President, Dr. Nemesio G. Loayon, highlighted the importance of forging partnerships with several Universities and administrators undercharged with Commissioner Mark Libre during the&nbsp; Flag Raising Ceremony hosted by the College of Engineering Technology (CET) on February 20, 2023. </span></span></p>\r\n\r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Flag-20202301.png\" /></span></p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">In these collaborations, NEMSU can expand its resources, knowledge, and network, benefiting the academic community. He expressed an enthusiastic message to start the first day of the week.</span></span></p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">The President&rsquo;s travels provided a chance to share best practices and exchange ideas on cross-cultural experiences in internships, research, and extension projects.</span></span></p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\">&nbsp;</p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">Dr. Loayon also had the opportunity of discussing a possible partnership with the University of the Philippines through its President, Dr. Angelo Jimenez.</span></span></p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\">&nbsp;</p>\r\n            \r\n            <p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">The President is confident that the partnership will be a transformative force in NEMSU&rsquo;s academic pursuits.</span></span></p>\r\n            \r\n            <p><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Flag-20202304.png\" /></p>\r\n            \r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2(1).png\" /></span></p>', 'Flag-20202300.png', 'Public Information Office', NULL, 'news', 1, '2023-02-20 13:42:22', '2023-02-20 13:42:22', '2023-02-20 13:42:22'),
('148d64db-8edb-11ef-bdca-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐓𝐚𝐧𝐝𝐚𝐠 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝐅𝐚𝐦𝐢𝐥𝐲 𝐃𝐚𝐲 𝐚𝐭 𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐁𝐞𝐚𝐜𝐡 𝐑𝐞𝐬𝐨𝐫𝐭 𝐢𝐧 𝐇𝐨𝐧𝐨𝐫 𝐨𝐟 𝟏𝟐𝟒𝐭𝐡 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞 𝐂𝐢𝐯𝐢𝐥 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 𝐀𝐧𝐧𝐢𝐯𝐞𝐫𝐬𝐚𝐫𝐲', 'NEMSU-Tandag-Celebrates-Family-Dau-2024', 'Cagwait, Surigao del Sur — The North Eastern Mindanao State University (NEMSU) Tandag Campus held its Family Day at Cagwait Beach Resort on October 3-4, 2024, in celebration of the 124th Philippine Civil Service Anniversary. Themed “Transforming Public Service in the Next Decade: Honing Agile and Future-Ready Servant-Heroes,” the event aimed to strengthen camaraderie and foster a sense of community among the university\'s teaching and non-teaching personnel.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nCagwait, Surigao del Sur - August 5, 2024, North Eastern Mindanao State University (NEMSU) through Lianga Campus has reached a significant milestone in its internationalization journey with the signing of a tripartite Memorandum of Agreement (MOA) with Mindanao State University Iligan Institute of Technology (MSU-IIT) and Ghent University.\r\n<br><br>\r\nCagwait, Surigao del Sur — The North Eastern Mindanao State University (NEMSU) Tandag Campus held its Family Day at Cagwait Beach Resort on October 3-4, 2024, in celebration of the 124th Philippine Civil Service Anniversary. Themed “Transforming Public Service in the Next Decade: Honing Agile and Future-Ready Servant-Heroes,” the event aimed to strengthen camaraderie and foster a sense of community among the university\'s teaching and non-teaching personnel.\r\n<br><br>\r\nThe two-day activity brought together faculty and staff from the Tandag Campus for a variety of activities designed to promote both spiritual and recreational well-being.\r\n<br><br>\r\nThe event began with a Thanksgiving Mass and a Praise and Worship session, followed by a Spiritual Enhancement Seminar. These opening activities set a reflective tone, emphasizing the value of personal growth and connection, both with one another and with their faith.\r\n<br><br>\r\nAfter the spiritual sessions, the participants engaged in traditional Filipino games, known as Laro ng Lahi, adding an element of fun and nostalgia to the day. Teams competed in classic games, promoting teamwork and friendly competition.\r\nAs the festivities continued into the evening, participants eagerly anticipated a series of surprising contests, including the “Pageant with a Twist,” a Lip Sync Battle, and a Dance Showdown, all designed to entertain and showcase the hidden talents of the NEMSU community.\r\n<br><br>\r\nThe Family Day celebration will conclude tomorrow, October 4, 2024, as participants reflect on the values of agility, unity, and the spirit of service that define the modern public servant.', 'nemsu-psca-banner-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-10-03 20:01:32', '2024-10-03 20:01:32', '2024-10-03 20:01:32'),
('15f76f48-6e6c-11f0-ae5d-a233a240566f', '𝐀 𝐒𝐞𝐚𝐦𝐥𝐞𝐬𝐬 𝐓𝐫𝐚𝐧𝐬𝐢𝐭𝐢𝐨𝐧 𝐨𝐟 𝐋𝐞𝐚𝐝𝐞𝐫𝐬𝐡𝐢𝐩 𝐚𝐭 𝐍𝐄𝐌𝐒𝐔-𝐒𝐚𝐧 𝐌𝐢𝐠𝐮𝐞𝐥: 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐢𝐧𝐠 𝐃𝐫. 𝐔𝐫𝐛𝐢𝐳𝐭𝐨𝐧𝐝𝐨\'𝐬 𝐋𝐞𝐠𝐚𝐜𝐲 𝐚𝐧𝐝 𝐖𝐞𝐥𝐜𝐨𝐦𝐢𝐧𝐠 𝐃𝐫. 𝐆𝐨𝐧𝐳𝐚𝐠𝐚\'𝐬 𝐕𝐢𝐬𝐢𝐨𝐧', '𝐀-𝐒𝐞𝐚𝐦𝐥𝐞𝐬𝐬-𝐓𝐫𝐚𝐧𝐬𝐢𝐭𝐢𝐨𝐧-𝐨𝐟-𝐋𝐞𝐚𝐝𝐞𝐫𝐬𝐡𝐢𝐩-𝐚𝐭-𝐍𝐄𝐌𝐒𝐔-𝐒𝐚𝐧-𝐌𝐢𝐠𝐮𝐞𝐥', 'The North Eastern Mindanao State University - San Miguel campus recently held a turnover ceremony, marking the transition of leadership from Dr. Florife O. Urbiztondo, the outgoing Campus Director, to Dr. Marvie V. Gonzaga, the incoming OIC Campus Director. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀 𝐒𝐞𝐚𝐦𝐥𝐞𝐬𝐬 𝐓𝐫𝐚𝐧𝐬𝐢𝐭𝐢𝐨𝐧 𝐨𝐟 𝐋𝐞𝐚𝐝𝐞𝐫𝐬𝐡𝐢𝐩 𝐚𝐭 𝐍𝐄𝐌𝐒𝐔-𝐒𝐚𝐧 𝐌𝐢𝐠𝐮𝐞𝐥 𝐕𝐢𝐬𝐢𝐨𝐧-1.jpg\" /></div>\r\n</div>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University - San Miguel campus recently held a turnover ceremony, marking the transition of leadership from Dr. Florife O. Urbiztondo, the outgoing Campus Director, to Dr. Marvie V. Gonzaga, the incoming OIC Campus Director. Dr. Urbiztondo, a recognized pillar of Surigao del Sur State University (now NEMSU), leaves behind a legacy defined by her exceptional focus on forging and strengthening external collaborations. Her proactive approach resulted in significant partnerships with key national government agencies, including the Department of Agriculture (DA), the Philippine Fiber Industry Development Authority (PhilFIDA), the Department of Environment and Natural Resources (DENR), CENRO Lianga, LGU-San Miguel, and the San Miguel Tribal Community. These collaborations not only enriched the academic environment but also facilitated crucial resource acquisition and knowledge exchange, benefiting both the University campus and the wider community. A testament to her effective leadership is the completion of three major infrastructure projects: a state-of-the-art multipurpose building, a vital road concreting initiative, and a much-needed potable water system. These projects, undertaken in collaboration with the Congressional District Office, significantly enhanced the campus\'s facilities and overall learning environment.\r\n\r\n<br/><br/>\r\nDr. Marvie V. Gonzaga, with extensive experience spanning her long tenure at the campus since its days as Surigao del Sur Polytechnic College, now serves as Officer-in-Charge, bringing a wealth of institutional knowledge and a fresh perspective to the role of Campus Director. Her appointment signifies a continuation of NEMSU-San Miguel\'s commitment to academic excellence and community engagement. The successful turnover ceremony, which took place on June 30, 2025, underscores a smooth transition of leadership, ensuring the continued progress and development of the campus. The University campus looks forward to the innovative strategies and leadership Dr. Gonzaga will bring to further elevate NEMSU-San Miguel\'s standing within the academic landscape. The event served as a platform to acknowledge Dr. Urbiztondo\'s significant contributions while welcoming Dr. Gonzaga\'s leadership into this new chapter.\r\n', '𝐀 𝐒𝐞𝐚𝐦𝐥𝐞𝐬𝐬 𝐓𝐫𝐚𝐧𝐬𝐢𝐭𝐢𝐨𝐧 𝐨𝐟 𝐋𝐞𝐚𝐝𝐞𝐫𝐬𝐡𝐢𝐩 𝐚𝐭 𝐍𝐄𝐌𝐒𝐔-𝐒𝐚𝐧 𝐌𝐢𝐠𝐮𝐞𝐥 𝐕𝐢𝐬𝐢𝐨𝐧.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-06 08:07:12', NULL, NULL),
('162faa5b-4a41-4d19-a33a-5b8e1690faee', 'NEMSU-Main Campus hosts the KUMBIRA: The Student Leaders Regional Summit 2023', 'nemsu-main-campus-hosts-the-kumbira-the-student-leaders-regional-summit-2023', '<p>The North Eastern Mindanao State University-Main Campus Tandag City hosts the KUMBIRA: The Student Leaders Regional Summit 2023 on February 8-10, 2023.</p>', '<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">The North Eastern Mindanao State University-Main Campus Tandag City hosts the KUMBIRA: The Student Leaders Regional Summit 2023 on February 8-10, 2023. The event aims to uphold the rights and cooperation among institutions in Caraga Region in the post-pandemic. It aims to exchange knowledge and experiences on the importance of the effective delivery of services. It aligns with this year&rsquo;s Regional Summit theme: &ldquo;Forging Leadership Advancement and Opportunities in the New Normal.&rdquo; The event is jampacked with support from the University, Province, and City Officials. In attendance at the event are; Hon. Romeo S. Momo, 1st District Congressman of Surigao del Sur, Hon Kharin C. Momo, Tandag City Councilor representing the Office of the City Mayor Hon. Roxanne C. Pimentel, Mr. Ever Joy Rabadan representing the CHED Regional Director Dr. George M. Colorado, and Dr. Evelyn T. Bagood, Dean of the Graduate School representative of NEMSU President Dr. Nemesio G. Loayon, Dr. Abundio C. Miralles, NEMSU OSWD Director, Caraga Federation of Student Leaders Officials, Heads of Student Welfare and Development and student leaders across the region of Caraga.</span></p>\r\n\r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/7.png\" /></span></p>', 'NEMSU-Main-Campus-hosts-the-KUMBIRA-The-Student-Leaders-Regional-Summit-2023.png', 'Public Information Office', NULL, 'news', 1, '2023-02-11 11:24:17', '2023-02-11 05:34:35', '2023-02-11 05:34:35'),
('16efadbf-5c18-11ee-a632-a233a240566f', 'NEMSU inaugurates new personnel in an oath-taking ceremony', 'oath-2023-sept', 'To serve as a rite of passage for the newly appointed and promoted personnel of the institution, the North Eastern Mindanao State University, led by its key officials, conducted the oath-taking and orientation on CSC laws and university policies inside the Audio-Visual Center on September 25.', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OATH23-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nTo serve as a rite of passage for the newly appointed and promoted personnel of the institution, the North Eastern Mindanao State University, led by its key officials, conducted the oath-taking and orientation on CSC laws and university policies inside the Audio-Visual Center on September 25.<br><br>\r\nUniversity President Dr. Nemesio G. Loayon administered the oath-taking process, formally welcoming the new staff to their respective designations.\r\nMeanwhile, present at the event were the three university vice presidents: Dr. Maria Lady Sol A. Suazo, Dr. Rolly G. Salvaleon, and Ms. Catherine F. Salomon, along with Dr. Florife O. Urbiztondo, who all took part in the orientation proper.<br><br>\r\nMore topics were discussed during the program, such as accounting and budget matters, civil service laws, and many more.<br><br>\r\nWith the bulk of the event centered around orientation procedures, the new personnel of the institution are sure to deliver quality service in their own offices as they are guided by the experts.<br><br>\r\nWritten by: John Damort Guingguing<br>\r\nPhotos by: Mary Jane Espinoza\r\n', 'OATH23-00.jpg', 'The Vanguard Publication', NULL, 'news', 1, '2023-09-25 18:59:11', '2023-09-25 18:59:11', '2023-09-25 18:59:11'),
('173514c6-4618-11ee-a66e-a233a240566f', '2nd RESCOM, PA-WIDE Simultaneous Bloodletting isinagawa; AFPSAT Examination, Kasalukuyang ginaganap', 'AFP2023', 'Isinagawa ang bloodletting activity nitong umaga sa gusali ng College of Engineering and Technology, ground floor sa North Eastern Mindanao State University- Tandag kampus', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/afp-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIsinagawa ang bloodletting activity nitong umaga sa gusali ng College of Engineering and Technology, ground floor sa North Eastern Mindanao State University- Tandag kampus.<br><br>\r\nPinangunahan ito ng mga opisyales, faculty, miyembro ng Reserved Force, Adela Serra Ty Memorial Medical Center at gayundin ang isponsor ng Reserved Command Philippine Army. <br><br>\r\nSamantala, nakiisa rin ang freshmen mula sa iba‘t ibang kolehiyo upang makapagbahagi ng kanilang mga dugo. Ilan sa mga nakibahagi ay ang mga opisyales ng ROTC dahil sa malasakit at pagmamahal sa mamamayang Pilipino. <br><br>\r\nNagbigay naman ng panayam ang ROTC commandant na si Marcos M. Quico, PA Res,  \"I encourage you to donate your blood; please donate it. Imong dugo, kinabuhi sa imong igsuon. You can extend lives of our brothers and sisters.\"<br><br>\r\nSa kabilang balita, patuloy namang isinasagawa ang AFPSAT examination sa Prospero Pichay para sa mga estudyanteng nagsipagtapos at nagnanais makapasok sa hanay ng mga dakilang AFP. <br><br>\r\nSa huli, natapos ang aktibidad ng bloodletting at inaasahan ding matatapos ang AFPSAT examination ngayong hapon.\r\nUlat ni Charlene Comboy\r\nLarawan ni Mary Jane Espinoza <br><br> \r\n', 'afp-00.jpg', 'The Vanguard Publication', NULL, 'news', 1, '2023-08-26 16:40:11', '2023-08-26 16:40:11', '2023-08-26 16:40:11'),
('17ec2072-e659-11ee-987e-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐇𝐨𝐬𝐭𝐬 𝐎𝐫𝐢𝐞𝐧𝐭𝐚𝐭𝐢𝐨𝐧 𝐟𝐨𝐫 𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐚𝐧𝐝 𝐄𝐱𝐭𝐞𝐧𝐬𝐢𝐨𝐧 𝐀𝐬𝐬𝐢𝐬𝐭𝐚𝐧𝐭𝐬', 'Research-and-Extension-Assistant-2024', 'In pursuit of becoming a premier research university, various research and extension assistants of North Eastern Mindanao State University attended the Research and Extension Assistants Orientation held at the NEMSU Old Board Room on March 18, 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Fire-Drill/REA-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn pursuit of becoming a premier research university, various research and extension assistants of North Eastern Mindanao State University attended the Research and Extension Assistants Orientation held at the NEMSU Old Board Room on March 18, 2024.\r\n<br><br>\r\nThe orientation was arranged in a hybrid setup, allowing participants from various campuses to join remotely via Zoom. This session served as a platform to familiarize the assistants with their contracts of service, study guidelines and procedures, budgetary requirements, liquidation, travel procedure and other accounting concerns, procurement process, and their specific roles and responsibilities as research and extension assistants.\r\n<br><br>\r\nDuring the end of the session, Dr. Erwin B. Berry, the Director for Research and Development, emphasized a message, reminding the participants of their duty to serve with excellence and professionalism, and stressing the importance of prayer in their research and extension endeavors, whether within the school premises or out in the field.\r\n<br><br>\r\nThe orientation concluded with impressions from selected participants, who shared their reflections on the invaluable lessons gained during the event. These insights served as inspiration for them to redouble their efforts in their roles, aiming to contribute towards NEMSU\'s advancement in the fields of research and extension.\r\n<br/>', 'REA-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-03-18 17:25:16', '2024-03-18 17:25:16', '2024-03-18 17:25:16'),
('186d83aa-9e04-11ee-8f14-a233a240566f', 'A Bridge of Collaboration: Usufruct Agreement Forges Path of Partnership Between The Roman Catholic Bishop of Tandag, Inc. and NEMSU', 'Usufruct-Agreement-2023', 'In a significant stride towards fostering collaboration and unity, the Roman Catholic Bishop of Tandag, Inc. and Northeastern Mindanao State University (NEMSU) have officially entered into a Usufruct Agreement. The agreement was sealed with the generous grant from the Bishop, offering over a thousand square meters of land to NEMSU Cagwait Campus for the construction of a pathway along the road leading to the campus entrance.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a significant stride towards fostering collaboration and unity, the Roman Catholic Bishop of Tandag, Inc. and North Eastern Mindanao State University (NEMSU) have officially entered into a Usufruct Agreement. The agreement was sealed with the generous grant from the Bishop, offering over a thousand square meters of land to NEMSU Cagwait Campus for the construction of a pathway along the road leading to the campus entrance.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThis pivotal move is set to benefit not only the students and employees of NEMSU Cagwait Campus but also various stakeholders involved in the educational journey. The granted land will facilitate improved accessibility, creating a seamless and welcoming entrance to the campus.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nBishop Raul Dael, the visionary behind this collaborative effort, emphasized the importance of building bridges and roads rather than walls. In his statement, he encouraged continued collaboration, urging both institutions to explore more creative avenues for mutual cooperation. \"Let us build bridges and roads, not walls. We can continue to collaborate and find areas where we can creatively collaborate more. This is a very good experience of walking together,\" remarked Bishop Dael.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nPresident Nemesio Loayon of NEMSU expressed his deep gratitude for the support received during this milestone. He acknowledged the collective effort that played a crucial role in securing the grant, stating, \"I\'m so grateful for those who helped me in this milestone. Thank you so much for granting our request for the good of our constituents.\"\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThis Usufruct Agreement stands as a testament to the power of collaboration in advancing educational opportunities and community welfare. As the partnership between the Roman Catholic Bishop of Tandag, Inc. and NEMSU continues to flourish, it opens doors to a future marked by shared endeavors, progress, and mutual growth.\r\n<br>\r\n', 'Usufruct-banner-2023.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2023-12-07 20:33:11', '2023-12-07 20:33:11', '2023-12-07 20:33:11'),
('18efc10f-47a5-11ee-b55e-a233a240566f', 'Local Masts streamline', 'local-masts-streamline', '<p><span style=\"font-size:11.0pt\">To streamline the 3-day friendly games, coaches and committee members converge</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝐔𝐏𝐃𝐀𝐓𝐄 | To streamline the 3-day friendly games, coaches and committee members converge inside the Prospero B. Pichay Sr. Gymnasium for the Solidarity Meeting.\r\n<br><br>\r\n#TheVanguardPublication<br>\r\n#LocalMASTS2023\r\n\r\n</span></span></p>', 'oswd-masts-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-29 14:48:43', '2023-08-29 14:48:43', '2023-08-29 14:48:43'),
('18fbdef1-d11d-11ee-aa14-a233a240566f', '𝐏𝐀𝐒𝐔𝐂 𝐍𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐓𝐫𝐚𝐢𝐧𝐢𝐧𝐠 𝐖𝐨𝐫𝐤𝐬𝐡𝐨𝐩 𝐆𝐚𝐥𝐯𝐚𝐧𝐢𝐳𝐞𝐬 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬\' 𝐒𝐭𝐚𝐭𝐞 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐢𝐞𝐬 𝐟𝐨𝐫 𝐭𝐡𝐞 𝟐𝟎𝟐𝟒 𝐍𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐂𝐮𝐥𝐭𝐮𝐫𝐞 𝐚𝐧𝐝 𝐀𝐫𝐭𝐬 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥', 'PASUC-2024', 'With more than 400 participants, the Philippines’ state universities and colleges most talented representatives for culture and the arts flooded Batangas State University, the National Engineering University, during the PASUC National Training Workshop for Directors, Coaches, and Trainers on February 13, 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Pasuc-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nWith more than 400 participants, the Philippines’ state universities and colleges most talented representatives for culture and the arts flooded Batangas State University, the National Engineering University, during the PASUC National Training Workshop for Directors, Coaches, and Trainers on February 13, 2024.\r\n<br><br>\r\nThe three-day training, fronted by the Philippine Association of State Universities and Colleges, aimed to inform the public about its development and preparations. North Eastern Mindanao State University also graced the said training led by the University Director for Culture and Arts, Dr. Shyla O. Moreno, with the university’s winning coaches and trainers joining the march.\r\n<br><br>\r\nDuring the opening program, PASUC Pres. Tirso A. Ronquillo ensured that the National Culture and the Arts Festival will be pursued this year, which will commence on April 23–25, 2024, at the Philippine Normal University in Manila. In his speech, he highlighted the goal of this festival: to unfold the subconscious meaning and purpose of life, achieve the inner shell of culture and the arts, and give hope to the audience and performers through the delivery of various art forms.\r\n<br><br>\r\nIn the same vein, Dr. Lordinio A. Vergara laid down the salient points of the activity, emphasizing the support for the promulgation of the arts in the country. He also cited several existing laws and national mandates that align with the conduct of the NCAF 2024, complementing socio-cultural components in the curriculum.\r\n<br>\r\nDr. Baby Boy Benjamin Nebres III, in his talk, discussed the science of coaching, unveiling techniques and strategies to win and produce excellent performances. Also, he encouraged coaches and trainers to discover and select students with competitive talents and skills, as it is their responsibility to pick the cream of the crop while they represent their respective universities, becoming carriers of our national colors.\r\n<br><br>\r\nKeynote speaker Commissioner Arvin Manuel Villalon of the Commission of the National Culture and the Arts stimulated the crowd with his awe-inspiring speech. “Artists are near temptation, for they also do the first work of God,” said Prof. Villalon as he cited the challenges that artists faced. He also criticized the Filipino mantra that we become too competition-oriented, which is a current problem.\r\n<br><br>\r\nThe subsequent days were spent with several experts and connoisseurs of culture and the arts who disclosed the best practices applicable to their respective art forms with a drive to produce informed and rooted practitioners in the arts.\r\n<br/>', 'Pasuc-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-02-21 10:50:11', '2024-02-21 10:50:11', '2024-02-21 10:50:11'),
('19e1a18a-47b2-11ee-b55e-a233a240566f', '\"Mga Anak ng Bogac\"', 'local-masts-swimming', '<p><span style=\"font-size:11.0pt\">Mga Anak ng Bogac, a group of seasoned student-athletes, dominated the swimming competitions</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝗟𝗢𝗖𝗔𝗟 𝗠𝗔𝗦𝗧𝗦 𝗨𝗣𝗗𝗔𝗧𝗘: \"Mga Anak ng Bogac\", a group of seasoned student-athletes, dominated the swimming competitions, with NEMSU-Lianga snatching golds in the women\'s categories and NEMSU-Tagbina in the men\'s categories.<br><br>\r\nReport by Lee Van Cleff M. Labsan<br>\r\nPhoto by Manuel B. Allada<br>\r\n#2023LocalMASTS <br>\r\n#TheSeaStrivers <br>\r\n#SailingAndStrivingForTheTruth\r\n</span></span></p>', 'sea-swimming-00.jpg', 'The Sea Strivers Publication', 32, 'news', 1, '2023-08-31 12:33:11', '2023-08-31 12:33:11', '2023-08-31 12:33:11'),
('1b658164-1f8c-11ee-816f-a233a240566f', 'Talk/visit With the University of the Philippines-Manila School of Medicine about potential collaborations with NEMSU', 'Medicine', '', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-03.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-04.jpg\" /></div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-06.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/med-07.jpg\" /></div>\r\n</div>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Just had a fascinating exploratory talk/visit today with the University of the Philippines-Manila School of Medicine about potential collaborations with NEMSU. <br><br>\r\n\r\nChancellor CARMENCITA D. PADILLA, MD, MAHPS, and Vice Chancellor for Academic Affairs NYMIA PIMENTEL SIMBULAN, MPH, DR PH, greeted the team with warm accommodation, making sure that NEMSU could have the critical information it needed to pursue its School of Medicine for a community that is aimed with excellent public health service. <br><br>\r\n\r\nWith the full support of Atty. Ronnie Azura, Sen. Chiz Escudero\'s Oversight Focal Person for SUCs, coupled with the assistance of Congressman Romeo S. Momo Sr., representative of SDS 1st Congressional District, we felt that UP values opportunities of contributing milestones for the SUCs in the country. <br><br>\r\n\r\nOur VPAA, Prof. Maria Lady Sol A. Suazo, and EA Mick Mars P. Silvano are joining me in this effort. We were also with the CSU President, Dr Rolyn Daguil, with the same goals.<br><br>\r\n\r\nIt\'s incredible to see how much we can accomplish when we work together towards a common goal! Looking forward to seeing what the future holds for this partnership. Thanks, too, for the support of Comm. Jo Mark M. Libre.\r\nOnwards NEMSU!\r\n</span></p>\r\n\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\n#nemsuvision\r\n#nemsutouch\r\n#presidentofthegrassroots\r\n#VibrantLeadership\r\n\r\n</span></p>', 'med-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-06-22 19:20:11', '2023-06-22 19:20:11', '2023-06-22 19:20:11'),
('1eb53dd0-8a63-11ee-8f14-a233a240566f', 'With an Initial funding of 100 Million from the Office of Cong. Romeo S. Momo,', 'Medicine-2023', 'With an Initial funding of 100 Million from the Office of Cong. Romeo S. Momo, NEMSU finally engages with former Dean of the College of Medicine of Western Mindanao', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/medicine-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nWith an Initial funding of 100 Million from the Office of Cong. Romeo S. Momo, NEMSU finally engages with former Dean of the College of Medicine of Western Mindanao State University, Dr Ma Cecilia C. Cruz to discuss the opening of the NEMSU College of Medicine at the Main Campus\r\n<br>', 'medicine-00.jpg', 'Office of the Campus Director - Tandag', 0, 'news', 1, '2023-11-20 15:30:11', '2023-11-20 15:30:11', '2023-11-20 15:30:11'),
('1f0f7040-91dc-11f0-a6c6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐁𝐚𝐠𝐬 𝐌𝐮𝐥𝐭𝐢𝐩𝐥𝐞 𝐀𝐰𝐚𝐫𝐝𝐬 𝐢𝐧 𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓', '𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐀𝐒𝐄𝐀𝐍-𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬-𝟐𝟎𝟐𝟓', 'North Eastern Mindanao State University (NEMSU) made its mark in the recently concluded 2025 ASEAN Culmination Contests held on August 28, 2025, at Robinsons Place, Butuan City, bringing home multiple awards across different categories.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓 6.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) made its mark in the recently concluded 2025 ASEAN Culmination Contests held on August 28, 2025, at Robinsons Place, Butuan City, bringing home multiple awards across different categories.\r\n<br/><br/>\r\nFrom NEMSU Tandag Campus, the team of Johny E. Aporbo and Vaughn C. Chan, coached by Mr. Seberino H. Arriesgado Jr., secured 2nd Place in the ASEAN-inspired Fruit and Vegetable Carving Competition. \r\n<br/><br/>\r\nMeanwhile, NEMSU Cantilan Campus clinched two awards. Reinon D. Rivera and Charles Justine L. Febrero won 3rd Place in the Dessert Display Competition, while Jeann Luengas Amasan and Romy Huelma Rosil captured 3rd Place in the ASEAN Attire Competition. They were mentored by Ms. Blessy Antido and Ms. Mary-Ann G. Geli.\r\n<br/><br/>\r\nEqually commendable were the achievements of NEMSU Cagwait Campus, which also earned two distinctions. The duo of Rebicca C. Silvoza and Christine Mae B. Tagnipez, coached by Ms. Georgelyn G. Andrew, bagged 3rd Place in the Dessert Buffet Set-Up Competition. In addition, Alphon G. Ampilan and Cairel G. Omega, also trained by Ms. Andrew, secured 3rd Place in the Fruit and Vegetable Carving Competition.\r\n<br/><br/>\r\nThe ASEAN Culmination Contests served as a platform for students to display their talents while promoting ASEAN culture and identity. NEMSU’s consistent performance reflects its commitment to honing the skills of its students not only in academics but also in cultural and creative endeavors.\r\n<br/><br/>', '𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐀𝐒𝐄𝐀𝐍 𝐂𝐨𝐧𝐭𝐞𝐬𝐭𝐬 𝟐𝟎𝟐𝟓.jpg', 'Public Information Office', 0, 'news', 1, '2025-08-29 10:26:29', NULL, NULL),
('1fd49894-3a7a-11ee-a66e-a233a240566f', 'Tandag Campus - Class Opening for A.Y. 2023-2024', 'Class-2023', '𝙉𝙀𝙈𝙎𝙐𝙜𝙙𝙖𝙣 𝙩𝙖 𝙣𝙖 the new academic year! Convivial cheers surround the NEMSU gymnasium as freshies, sophies,', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/class-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝙉𝙀𝙈𝙎𝙐𝙜𝙙𝙖𝙣 𝙩𝙖 𝙣𝙖 the new academic year! Convivial cheers surround the NEMSU gymnasium as freshies, sophies, juniors, and seniors celebrate their embarkment to the road of brilliance.\r\n<br/>\r\n', 'class-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-14 12:20:11', '2023-08-14 12:20:11', '2023-08-14 12:20:11'),
('2012bb6f-f3fe-11ef-b8b6-a233a240566f', 'North Eastern Mindanao State University (NEMSU) reaffirms its commitment to innovation and sustainable development.', 'Reaffirmation-of-commitment-to-innovation-and-sustainable-development', 'North Eastern Mindanao State University (NEMSU) reaffirms its commitment to innovation and sustainable development.\r\nThe University envisions itself as a Research University advancing technology and innovation for sustainable development, driven by its mission to provide quality instruction, innovative research, community collaboration, and technological advancement.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/reaffirmation-commitment-to-innovation-and-sustainable-development-02.jpg\" /></div>\r\n</div>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe University envisions itself as a Research University advancing technology and innovation for sustainable development, driven by its mission to provide quality instruction, innovative research, community collaboration, and technological advancement.\r\n<br/><br/>\r\nGuided by the core values of 𝐂𝐨𝐦𝐩𝐚𝐬𝐬𝐢𝐨𝐧, 𝐀𝐜𝐜𝐨𝐮𝐧𝐭𝐚𝐛𝐢𝐥𝐢𝐭𝐲, 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐢𝐯𝐞𝐧𝐞𝐬𝐬, 𝐄𝐱𝐜𝐞𝐥𝐥𝐞𝐧𝐜𝐞, 𝐚𝐧𝐝 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 (𝐂.𝐀.𝐑.𝐄.𝐒.), NEMSU fosters a culture of integrity and service.\r\n<br/><br/>\r\nTo realize these aspirations, the University implements its 𝟖-𝐏𝐨𝐢𝐧𝐭 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜 𝐃𝐢𝐫𝐞𝐜𝐭𝐢𝐨𝐧𝐚𝐥 𝐀𝐠𝐞𝐧𝐝𝐚 (𝐈.𝐍.𝐍.𝐎.𝐕.𝐀.𝐓.𝐄.), emphasizing industry-driven research, transformative education, resilient infrastructure, and global partnerships.\r\n<br/><br/>', 'reaffirmation-commitment-to-innovation-and-sustainable-development-01.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-06 12:50:24', NULL, NULL);
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('20cfb08f-fbae-11ed-affb-a600064b4626', 'NEMSU conducts Oath-taking Ceremony; President Loayon welcomes Newly Appointed Personnel', 'Oath-may2023', 'To formally proclaim the newly appointed teaching, administrative, and medical personnel, the Oath-taking Ceremony and Orientation of Civil Service Law and Policies were conducted at the Audio Visual Center on May 25, 2023. ', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-3.jpg\" /></div></div><br />\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-7.jpg\" /></div>\r\n</div><br />\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-8.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-9.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-10.jpg\" /></div>\r\n</div>\r\n<br />\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">To formally proclaim the newly appointed teaching, administrative, and medical personnel, the Oath-taking Ceremony and Orientation of Civil Service Law and Policies were conducted at the Audio Visual Center on May 25, 2023.</span></p>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">Moreover, University President Dr. Nemesio G. Loayon challenged the newly installed staff to become leaders of economic progress and encouraged them to concentrate with work and collaborate with colleagues.</span></p>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">You are at NEMSU; we have high expectations to each and everyone of you to deliver quality and efficient services,\" the president emphasized.<br />\r\nMeanwhile, Vice President for Administration and Finance Dr. Catherine F. Salomon pointed out the importance of humility, faith, and compassion in the workplace.</span></p>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">It\'s not the university that will give you the reward, it\'s the Lord,\" VP Salomon articulated.<br />\r\nFurthermore, Vice President for Research and Development, Extension, Internalization, Resource Generation, and Auxiliary Services, Dr. Florife O. Urbiztondo explained the importance of familiarizing one\'s duty, while VP for Academic Affairs Dr. Maria Lady Sol Suazo shed light on the crucial role of communication in the workplace.</span></p>\r\n<br />\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">\"If you have concern, there\'s this communication line that will put everything in order,\" VP Suazo accentuated. <br />\r\nThrough the ceremony, the newly installed workforce is expected to emulate the ideals NEMSU has established as the epicenter of providing quality education and services in Caraga.</span></p>', 'oath-0.jpg', 'Report by Nerlanie Gopio | The Vanguard Publication\r\nPhotos by Information Unit', NULL, 'news', 1, '2023-05-25 11:49:11', '2023-05-25 11:49:11', '2023-05-25 11:49:11'),
('211a6565-6e5a-11ee-a3fc-a233a240566f', 'College of Information Technology Education launches Techno Fair', 'CITE-Techno-Fair-2023', 'College of Information Technology Education launches Techno Fair.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cite-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n', 'cite-00.jpg', 'Office of the Campus Director - Tandag', 32, 'news', 1, '2023-10-19 11:33:11', '2023-10-19 11:33:11', '2023-10-19 11:33:11'),
('22903e4d-ae71-4864-85ae-4670c3fc2089', 'NEMSU has successfully presented its Proposed Budget 2024 last March 7, 2023', 'nemsu-has-successfully-presented-its-proposed-budget-2024-last-march-7-2023', '<p>NEMSU has successfully presented its Proposed Budget 2024 last March 7, 2023.</p>', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2%20(2).png\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/4%20(2).png\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/5%20(1).png\" /></div>\r\n</div>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">NEMSU has successfully presented its Proposed Budget 2024 last March 7, 2023. The RDC-SDC has approved for endorsement the said budget proposal during its 2023 1st Quarter Meeting at NEDA Caraga Conference Hall.</span></p>', '1 (2).png', 'Public Information Office', NULL, 'news', 1, '2023-03-07 11:09:36', '2023-03-10 03:03:22', '2023-03-10 03:03:22'),
('245c657d-10f8-11ee-affb-a600064b4626', 'CHED Gawad Parangal 2023', 'Gawad-parangal-2023', '', '\n<div class=\"row\">\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award07.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award02.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award03.jpg\" /></div>\n</div>\n\n<div class=\"row\">\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award04.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award05.jpg\" /></div>\n\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/award06.jpg\" /></div>\n</div>\n<br />\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The North Eastern Mindanao State University - NEMSU garnered multiple recognitions during the CHED Gawad Parangal 2023 with its theme: “Ang May Mas Mataas na Pinag-aralan: Malakas, Matalino, at Mapagmahal sa Bayan” held at Surigao del Norte State University-Del Carmen Campus, Surigao del Norte. <br />\nThese recognitions sparks in the forefront of NEMSU’s continuing commitment to providing quality and excellent service to its clienteles. \nCongratulations to us, Mabuhay!</span></p>', 'award01.jpg', 'Public Information Office', NULL, 'news', 1, '2023-06-21 12:30:02', '2023-06-21 12:30:02', '2023-06-21 12:30:02'),
('25af6ed6-47de-11ee-b55e-a233a240566f', 'NEMSU-LC men\'s football', 'local-masts-football', '<p><span style=\"font-size:11.0pt\">The NEMSU-LC men\'s football team defended their title through Charles Lala and Rowell Sierra\'s consecutive goals.</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝗟𝗢𝗖𝗔𝗟 𝗠𝗔𝗦𝗧𝗦 𝗨𝗣𝗗𝗔𝗧𝗘: The NEMSU-LC men\'s football team defended their title through Charles Lala and Rowell Sierra\'s consecutive goals, 2-1, making the NEMSU-Main team drop out of the MASTS 2023 trip.<br><br>\r\nReport by Lee Van Cleff M. Labsan<br>\r\nPhoto by Kathy Angel Aquino<br>\r\n#2023LocalMASTS <br>\r\n#TheSeaStrivers <br>\r\n#SailingAndStrivingForTheTruth\r\n</span></span></p>', 'sea-football-00.jpg', 'The Sea Strivers Publication', 32, 'news', 1, '2023-08-30 16:40:13', '2023-08-30 16:40:13', '2023-08-30 16:40:13'),
('270908e3-3a7b-11ee-a66e-a233a240566f', '𝑪𝑯𝑬𝑫 𝑪𝒐𝒎𝒎𝒊𝒔𝒔𝒊𝒐𝒏𝒆𝒓 𝑳𝒊𝒃𝒓𝒆 𝒈𝒓𝒂𝒄𝒆𝒔 𝒕𝒉𝒆 𝑵𝑬𝑴𝑺𝑼 𝑴𝒂𝒊𝒏 𝑪𝒂𝒎𝒑𝒖𝒔 𝑪𝒍𝒂𝒔𝒔 𝑶𝒓𝒊𝒆𝒏𝒕𝒂𝒕𝒊𝒐𝒏', 'Class-2023-with-CHED', 'The CHED Comm. Jo Mark M. Libre virtually graced the NEMSU Main Campus Class Orientation for the SY 2023-2024. Commissioner Libre delivered an encouraging message to the freshmen, transferees, returnees and old students of the University.', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ched-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ched-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ched-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe CHED Comm. Jo Mark M. Libre virtually graced the NEMSU Main Campus Class Orientation for the SY 2023-2024. Commissioner Libre delivered an encouraging message to the freshmen, transferees, returnees and old students of the University. In his message, he highlighted the vital role of the University in shaping the future of the skolar ng bayan. The academic pursuit of the students in the new school year magnifies through the collaborative efforts of the University’s administration, faculty and staff. <br>\r\nThe whole academic community of NEMSU is grateful to Commissioner Libre for his virtual presence in this endeavor.  Mabuhay ka!\r\n<br/>\r\n', 'ched-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-08-14 15:20:11', '2023-08-14 15:20:11', '2023-08-14 15:20:11'),
('2bc33420-6e6d-11f0-ae5d-a233a240566f', 'MOA Signing | NEMSU × SEEMESOL  ', 'MOA-Signing-NEMSU-SEEMESOL  ', 'A shared vision for empowered futures.  \r\nHeld at the SMX Convention Center, NEMSU and SEEMESOL', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/MOA Signing NEMSU SEEMESOL-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/MOA Signing NEMSU SEEMESOL-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/MOA Signing NEMSU SEEMESOL-3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/MOA Signing NEMSU SEEMESOL-4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/MOA Signing NEMSU SEEMESOL-5.jpg\" /></div>\r\n\r\n</div>\r\n\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐒𝐭𝐫𝐞𝐧𝐠𝐭𝐡𝐞𝐧𝐬-𝐈𝐧𝐬𝐭𝐢𝐭𝐮𝐭𝐢𝐨𝐧𝐚𝐥-𝐕𝐢𝐬𝐢𝐨𝐧-07.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) concluded a successful Direction-Setting Session on February 25, 2025, at its Cantilan Campus, spearheaded by University President Dr. Nemesio G. Loayon. This event was attended by selected faculty and staff who were set to receive their office orders for their designated and re-designated positions.\r\n\r\n<br/><br/>\r\nA shared vision for empowered futures.  \r\nHeld at the SMX Convention Center, NEMSU and SEEMESOL formalized their partnership to strengthen the Career Center and champion innovative alumni engagement through a digitalized tracer study. This milestone marks a leap toward data-driven development, lifelong learning, and meaningful connections beyond graduation.\r\n<br/><br/>\r\n', 'MOA Signing NEMSU SEEMESOL-1.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-11 08:13:30', NULL, NULL),
('2f903d59-1fac-11ee-816f-a233a240566f', 'NEMSU - Lianga Campus 14th University Commencement Exercises', 'Lianga-Campus-14th-Commencement-Exercises', '14th UNIVERSITY COMMENCEMENT EXERCISE: NEMSU-LC grads end four-year acad journey, marks new beginning', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-03.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-06.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n<br><br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/comm-Lianga-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝟭𝟰𝘁𝗵 𝗨𝗡𝗜𝗩𝗘𝗥𝗦𝗜𝗧𝗬 𝗖𝗢𝗠𝗠𝗘𝗡𝗖𝗘𝗠𝗘𝗡𝗧 𝗘𝗫𝗘𝗥𝗖𝗜𝗦𝗘𝗦: 𝗡𝗘𝗠𝗦𝗨-𝗟𝗖 𝗴𝗿𝗮𝗱𝘀 𝗲𝗻𝗱 𝗳𝗼𝘂𝗿-𝘆𝗲𝗮𝗿 𝗮𝗰𝗮𝗱 𝗷𝗼𝘂𝗿𝗻𝗲𝘆, 𝗺𝗮𝗿𝗸𝘀 𝗻𝗲𝘄 𝗯𝗲𝗴𝗶𝗻𝗻𝗶𝗻𝗴 <br>\r\nClad in symbolic grad caps and gowns, the graduating students of North Eastern Mindanao State University-Lianga Campus marched triumphantly as they were acknowledged for the completion of their academic journey during the 14th Commencement Exercises today, July 4, at Prospero B. Pichay Sr., Sports and Cultural Center.\r\n<br><br>\r\n\r\nComm. Jo Mark M. Libre, CHED Commissioner and Chair of the NEMSU Board of Regents, sent his virtual inspirational message, which highlighted the importance of extending gratitude to the people behind the achievements of the graduating students, especially to their parents.\r\n<br><br>\r\n\r\n“Remember to thank your family, extend the kind of gratitude and love for the support and even the sacrifices that they made,” Libre accentuated.\r\nMoreover, Hon. Francis Escudero, Senator of the Philippines and Chairman of the Committee on Higher Technical Vocational Education, also delivered his message to the graduates and pointed out that students are not just hope for the nation but also drivers of societal change.\r\n<br><br>\r\n\r\n“Ang kabataan ay hindi lamang pag-asa ng bayan, ang kabataan ay dapat maaasahan na ng bayan,” he stressed.\r\n<br><br>\r\n\r\nFurther, Dr. Cynthia Pantaleon Sajot, Campus Director, presented the candidates for graduation of 59 students from the Bachelor of Science in Fisheries (BSFi) , 34 students from Bachelor of Science in Marine Biology (BSMB), 66 students from Bachelor of Science in Environmental Science (BSES), 82 from Bachelor of Elementary Education (BEEd), 36 from Bachelor of Secondary Education (BSEd), 80 students from Bachelor of Business Administration major in Financial Management (BSBA-FM) while 58 students from Business Economics (BSBA-BE), 74 students from Bachelor of Science in Hospitality Management, and 48 students from Bachelor of Science in Computer Science (BSCS), followed by conferring of degrees by Dr. Nemesio G. Loayon, the University President.\r\n<br><br>\r\n\r\nMeanwhile, Engr. Noel Ajoc, Regional Director of the Department of Science and Technology-Caraga Region, took the spot for the commencement address. In his talk, he stressed how dreams and success may be realized through dedication and perseverance.\r\n<br><br>\r\n\r\n“Dreams do come true with perseverance, commitment, and relentless hard work. Embrace the unwavering determination to succeed. Dapat \"no retreat, no surrender,” Ajoc said.\r\n“Have the determination to become a board topnotcher, and surely you will become one. Reading skill is very important. So, practice reading,” he added, emphasizing the goal of aiming higher and having an unending thirst for learning.\r\nFinally, the commencement exercise concluded with the acknowledgement of distinguished guests and university key officials, the singing of the university hymn, the recession of colors, and graduates tossing off their grad caps, denoting that a significant milestone had been accomplished.\r\n\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\nReport by Kaye Ann L. Quezada <br/>\r\nPhotos by Anna Carmela P. Cano, Jestony D. Padura, and Lizafern Mae Castillo \r\n</span></p>\r\n\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\n#CommencementExercises2023\r\n#TheSeaStrivers\r\n#SailingAndStrivingForTheTruth\r\n#NEMSULiangaCampus\r\n<br>\r\n#NEMSU2023 #GraduationDay #nemsucares #sculptingbetterlives\r\n\r\n</span></p>', 'comm-Lianga-000.jpg', 'The Sea Strivers Publication', 32, 'news', 1, '2023-07-04 17:10:11', '2023-07-04 17:10:11', '2023-07-04 17:10:11'),
('357ae2c9-1f98-11ee-816f-a233a240566f', 'NEMSU - Cagwait Campus 28th University Commencement Exercises', 'Cagwait-Campus-28th-Commencement-Exercises', '', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cag-02.png\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cag-03.png\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cag-04.png\" /></div>\r\n</div>\r\n<br><br>\r\n\r\n\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\n\r\n#NEMSU2023 #GraduationDay #nemsucares #sculptingbetterlives\r\n\r\n</span></p>', 'cag-00.png', 'Public Information Office', 32, 'news', 1, '2023-06-30 17:10:11', '2023-06-30 17:10:11', '2023-06-30 17:10:11'),
('367eea97-4729-11ee-b55e-a233a240566f', '3rd Quarter Regular Board Meeting', '3rdQuarter-BOR', 'Successful conduct of the 3rd Quarter Regular Board Meeting of North Eastern Mindanao State University at Caraga State University Learning Commons', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/3rdboard-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/3rdboard-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/3rdboard-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nSuccessful conduct of the 3rd Quarter Regular Board Meeting of North Eastern Mindanao State University at Caraga State University Learning Commons, fostering collaboration and progress.\r\n\r\n', '3rdboard-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-08-30 19:30:43', '2023-08-30 19:30:43', '2023-08-30 19:30:43'),
('3a35656f-b8c7-11ee-aa14-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐓𝐚𝐤𝐞𝐬 𝐁𝐨𝐥𝐝 𝐒𝐭𝐫𝐢𝐝𝐞𝐬 𝐓𝐨𝐰𝐚𝐫𝐝 𝐭𝐡𝐞 𝐋𝐚𝐮𝐧𝐜𝐡 𝐨𝐟 𝐂𝐨𝐥𝐥𝐞𝐠𝐞 𝐨𝐟 𝐌𝐞𝐝𝐢𝐜𝐢𝐧𝐞 𝐨𝐧 𝐓𝐚𝐧𝐝𝐚𝐠 𝐂𝐚𝐦𝐩𝐮𝐬', 'cm-2024', 'Tandag City, January 19, 2024 — Top executives of the Northern Eastern Mindanao State University (NEMSU) convened to discuss the crucial next steps for the eagerly anticipated launch of the College of Medicine at the Tandag Campus with its aim to expand its academic offerings and contribute to the healthcare sector.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-01.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nTandag City, January 19, 2024 — Top executives of the Northern Eastern Mindanao State University (NEMSU) convened to discuss the crucial next steps for the eagerly anticipated launch of the College of Medicine at the Tandag Campus with its aim to expand its academic offerings and contribute to the healthcare sector.\r\n<br>\r\nOne of the key highlights of the meeting was to prioritize the submission of necessary compliance documents and requirements. The discussions centered around aligning with the guidelines set by the Department of Budget and Management (DBM) and the Commission on Higher Education (CHED).<br>\r\nTo ensure a seamless and efficient compliance process, the executives formed two dedicated teams. Led by Ms. Catherine F. Salomon, the Vice President for Administration and Finance, Team A will spearhead the submission of compliance requirements to the DBM. Simultaneously, Team B, under the leadership of Dr. Maria Lady Sol A. Suazo, the Vice President for Academic Affairs, will handle the compliance requirements for CHED. This includes the submission of the academic framework, faculty manual, student manual, and the faculty development program.<br>\r\nFurther, both teams committed to providing progress updates during a follow-up meeting scheduled for March. The committees have set an ambitious yet achievable target to complete all necessary compliance requirements by June 2024.\r\n<br/>', 'cm-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-19 13:26:23', '2024-01-19 13:26:23', '2024-01-19 13:26:23'),
('3a71cfb1-6e70-11f0-ae5d-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀, 𝗜𝗻𝗱𝗶𝗮 𝗙𝗼𝗿𝗴𝗲 𝗣𝗮𝗿𝘁𝗻𝗲𝗿𝘀𝗵𝗶𝗽 𝗶𝗻 𝗛𝘆𝗯𝗿𝗶𝗱 𝗠𝗢𝗨 𝗦𝗶𝗴𝗻𝗶𝗻𝗴 𝗖𝗲𝗿𝗲𝗺𝗼𝗻𝘆', '𝗡𝗘𝗠𝗦𝗨-𝗮𝗻𝗱-𝗦𝗺𝗮𝗿𝘁-𝗕𝗿𝗶𝗱𝗴𝗲-𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹-𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀', 'In a significant stride toward internationalization and global academic collaboration, 𝙩𝙝𝙚 𝙉𝙤𝙧𝙩𝙝 𝙀𝙖𝙨𝙩𝙚𝙧𝙣 𝙈𝙞𝙣𝙙𝙖𝙣𝙖𝙤 𝙎𝙩𝙖𝙩𝙚 𝙐𝙣𝙞𝙫𝙚𝙧𝙨𝙞𝙩𝙮 (𝙉𝙀𝙈𝙎𝙐) 𝙨𝙪𝙘𝙘𝙚𝙨𝙨𝙛𝙪𝙡𝙡𝙮 𝙝𝙚𝙡𝙙 𝙖 𝙝𝙮𝙗𝙧𝙞𝙙 𝙈𝙚𝙢𝙤𝙧𝙖𝙣𝙙𝙪𝙢 𝙤𝙛 𝙐𝙣𝙙𝙚𝙧𝙨𝙩𝙖𝙣𝙙𝙞𝙣𝙜 (𝙈𝙊𝙐) 𝙎𝙞𝙜𝙣𝙞𝙣𝙜 𝘾𝙚𝙧𝙚𝙢𝙤𝙣𝙮 𝙬𝙞𝙩𝙝 𝙎𝙢𝙖𝙧𝙩 𝘽𝙧𝙞𝙙𝙜𝙚 𝙀𝙙𝙪𝙘𝙖𝙩𝙞𝙤𝙣𝙖𝙡 𝙎𝙚𝙧𝙫𝙞𝙘𝙚𝙨 𝙋𝙫𝙩. 𝙇𝙩𝙙., 𝙄𝙣𝙙𝙞𝙖, on July 23, 2025. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱𝗶1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱𝗶𝗮-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱a-2.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱𝗶𝗮-3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱𝗶a-4.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a significant stride toward internationalization and global academic collaboration, 𝙩𝙝𝙚 𝙉𝙤𝙧𝙩𝙝 𝙀𝙖𝙨𝙩𝙚𝙧𝙣 𝙈𝙞𝙣𝙙𝙖𝙣𝙖𝙤 𝙎𝙩𝙖𝙩𝙚 𝙐𝙣𝙞𝙫𝙚𝙧𝙨𝙞𝙩𝙮 (𝙉𝙀𝙈𝙎𝙐) 𝙨𝙪𝙘𝙘𝙚𝙨𝙨𝙛𝙪𝙡𝙡𝙮 𝙝𝙚𝙡𝙙 𝙖 𝙝𝙮𝙗𝙧𝙞𝙙 𝙈𝙚𝙢𝙤𝙧𝙖𝙣𝙙𝙪𝙢 𝙤𝙛 𝙐𝙣𝙙𝙚𝙧𝙨𝙩𝙖𝙣𝙙𝙞𝙣𝙜 (𝙈𝙊𝙐) 𝙎𝙞𝙜𝙣𝙞𝙣𝙜 𝘾𝙚𝙧𝙚𝙢𝙤𝙣𝙮 𝙬𝙞𝙩𝙝 𝙎𝙢𝙖𝙧𝙩 𝘽𝙧𝙞𝙙𝙜𝙚 𝙀𝙙𝙪𝙘𝙖𝙩𝙞𝙤𝙣𝙖𝙡 𝙎𝙚𝙧𝙫𝙞𝙘𝙚𝙨 𝙋𝙫𝙩. 𝙇𝙩𝙙., 𝙄𝙣𝙙𝙞𝙖, on July 23, 2025. \r\n\r\n<br/><br/>\r\nThe event, which took place virtually and was joined by key university officials onsite and online, marked a milestone in NEMSU’s efforts to build robust international linkages and foster collaborative academic initiatives. The partnership aims to promote academic exchange, technological cooperation, and shared research ventures between the two institutions.\r\n<br/><br/>\r\nPresent during the hybrid meeting were NEMSU’s top officials and representatives led by the University President Dr. Nemesio G. Loayon, including Vice Presidents, Campus Directors, the Director and Heads for International Affairs, the Director and Heads for Curriculum Development, the Deans of the College of Information Technology Education (CITE) and College of Engineering Technology (CET), department chairs and program coordinators from CITE and CET, and Legal Unit.\r\n<br/><br/>\r\nIn his remarks, representatives from both institutions highlighted the importance of forging international partnerships to enrich educational programs and provide global opportunities for students and faculty. The MOU signing reaffirms NEMSU’s commitment to expanding its global reach and enhancing academic standards through strategic collaborations.\r\n<br/><br/>\r\nThe university administration has expressed gratitude to all participants for their support and encouraged continued engagement as the partnership with Smart Bridge Educational Services takes its first steps into implementation.\r\nThis MOU is expected to open doors for student and faculty exchanges, joint training programs, and collaborative research initiatives, further strengthening NEMSU’s vision of becoming a globally engaged institution.\r\n', '𝗡𝗘𝗠𝗦𝗨 𝗮𝗻𝗱 𝗦𝗺𝗮𝗿𝘁 𝗕𝗿𝗶𝗱𝗴𝗲 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗦𝗲𝗿𝘃𝗶𝗰𝗲𝘀 𝗜𝗻𝗱𝗶𝗮.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-23 08:22:50', NULL, NULL),
('3c35ab63-1802-11ef-b18a-a233a240566f', '𝐆𝐫𝐨𝐮𝐧𝐝 𝐁𝐫𝐞𝐚𝐤𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲 𝐨𝐟 𝐍𝐄𝐌𝐒𝐔 𝐒𝐚𝐧 𝐌𝐢𝐠𝐮𝐞𝐥 𝐈𝐧𝐟𝐫𝐚𝐬𝐭𝐫𝐮𝐜𝐭𝐮𝐫𝐞 𝐏𝐫𝐨𝐣𝐞𝐜𝐭𝐬', 'Ground-Breaking-2024', 'The North Eastern Mindanao State University - San Miguel Campus, together with the Provincial DPWH spearheaded the Ground-breaking Ceremony for the Construction of a Multi-Purpose Building (24NH0074) and the Construction of Road Networks (24NH0070) at NEMSU San Miguel Campus, together with the distinguished guests,  Hon. Romeo S. Momo, Sr., Congressman of the 1st District of Surigao del Sur, Engr. Ruel B. Bantugan, MPA, is the district engineer of the DPWH Surigao del Sur 1st District Engineering Office, Hon. Michael T. Corilla, Municipal Mayor, Hon. Raquel R. Lobaton, Barangay Captain, and also Datu Jimmy Guinsod, Provincial IPMR.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University - San Miguel Campus, together with the Provincial DPWH spearheaded the Ground-breaking Ceremony for the Construction of a Multi-Purpose Building (24NH0074) and the Construction of Road Networks (24NH0070) at NEMSU San Miguel Campus, together with the distinguished guests,  Hon. Romeo S. Momo, Sr., Congressman of the 1st District of Surigao del Sur, Engr. Ruel B. Bantugan, MPA, is the district engineer of the DPWH Surigao del Sur 1st District Engineering Office, Hon. Michael T. Corilla, Municipal Mayor, Hon. Raquel R. Lobaton, Barangay Captain, and also Datu Jimmy Guinsod, Provincial IPMR.\r\n<br><br>\r\nThese projects are poised to significantly enhance the NEMSU San Miguel Campus, providing a state-of-the-art multi-purpose building and an improved road network, which will greatly benefit students and employees. The initiative reflects a strong commitment to advancing educational infrastructure and accessibility. Promoting a brighter future for the NEMSU San Miguel Campus by contributing to its overall development.\r\n<br>\r\n#sanmiguelcampus #nemsusm #NEMSU\r\n', 'ground-breaking.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-16 14:12:01', '2024-05-16 14:12:01', '2024-05-16 14:12:01'),
('3ceca579-dabe-11ee-987e-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐣𝐨𝐢𝐧𝐬 𝐭𝐡𝐞 𝐦𝐨𝐧𝐭𝐡-𝐥𝐨𝐧𝐠 𝐍𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐖𝐨𝐦𝐞𝐧\'𝐬 𝐌𝐨𝐧𝐭𝐡 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐢𝐨𝐧', 'PCW-2024', 'The Gender and Development Unit, together with the Human Resource Management Office of NEMSU Main Campus launched the campus celebration of National Women\'s Month, on March 4, 2024 at Prospero B. Pichay Sr. Gymnasium. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pcw-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe Gender and Development Unit, together with the Human Resource Management Office of NEMSU Main Campus launched the campus celebration of National Women\'s Month, on March 4, 2024 at Prospero B. Pichay Sr. Gymnasium.  Grounded on the objective of transforming culture toward a more equal and inclusive future, the 2024 NWMC bears the sub-theme, “Lipunang Patas sa Bagong Pilipinas; Kakayahan ng Kababaihan, patutunayan!”\r\n<br><br>\r\nPresent in the celebration were the University Key Officials led by NEMSU President Nemesio G. Loayon, faculty, staff, and students.  \r\n<br><br>\r\nDr. Loayon, highlighted in his speech that the NWMC pays tribute to the remarkable contributions of women throughout history, acknowledging their strength, resilience, and unwavering dedication to progress.\r\n<br><br>\r\nNational Women\'s Month is not just a time to reflect; it\'s a call to action—a reminder that our work towards gender equality is far from over.\r\n<br/>', 'pcw-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-03-05 08:50:11', '2024-03-05 08:50:11', '2024-03-05 08:50:11'),
('3dcd4222-91de-11f0-a6c6-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀 𝗜𝗕𝗢𝗚 𝗶𝗻 𝗣𝗮𝗿𝘁𝗻𝗲𝗿𝘀𝗵𝗶𝗽 𝘄𝗶𝘁𝗵 𝗦𝗲𝗿𝗶𝗻𝗴 𝗛𝗲𝗶𝗿𝘀', '𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚', 'North Eastern Mindanao State University (NEMSU)-Cantilan Campus formally launches the Infinity Binary Operation Game (IBOG) in collaboration with the Heirs of Cosme Y. Sering, sealing the initiative through a ceremonial Memorandum of Agreement (MOA) signing at the NEMSU Cantilan Hotel, August 29. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚 6.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU)-Cantilan Campus formally launches the Infinity Binary Operation Game (IBOG) in collaboration with the Heirs of Cosme Y. Sering, sealing the initiative through a ceremonial Memorandum of Agreement (MOA) signing at the NEMSU Cantilan Hotel, August 29. \r\n<br/>\r\nThis event highlights the NEMSU’s continuing pursuit of research, innovation, and sustainable development, with the IBOG project being hailed as a milestone in merging education, technology, and community engagement.\r\n<br/>\r\nIn his presentation, Associate Professor Reinar A. Acevedo, project proponent and developer of IBOG, introduces the game as a mathematics-based board game designed to address learning gaps in rational number operations and common misconceptions about infinity. “I call it infinity because the highlight of this game is about infinity — a concept often foreign to learners. This board game transforms abstract mathematical concepts into a fun, meaningful, and engaging learning experience,” he explains.\r\n<br/>\r\nKey university officials, including Dr. Rolly G. Salvaleon (VP for Research) and Dr. Maria Lady Sol A. Suazo (VP for Academic Affairs), join representatives from the HCYS family in the launching ceremony. Their collective message underscores the university’s commitment to supporting projects that blend scholarship and innovation.\r\n<br/>\r\n“This initiative is powerful in purpose because it addresses students’ difficulties in learning mathematics. It proves that even the hardest concepts can be learned when introduced in a more meaningful and engaging way,” Dr. Salvaleon states, adding his encouragement to digitalize the board game to broaden its reach.\r\n<br/>\r\nOne of the highlights of the MOA signing is the announcement of an annual ₱50,000 prize sponsorship from the heirs of the late Cosme Y. Sering. This pledge supports yearly IBOG tournaments, boosting the game’s popularity and creating opportunities for learners and enthusiasts in the surrounding communities.\r\n<br/>\r\nThe event marks the beginning of IBOG’s development toward production and commercialization but reflects NEMSU’s vision of becoming a leading research institution that advances technology and innovation for sustainable growth.\r\n<br/>\r\nAs the ceremony concludes with messages of commitment and a call for collaboration, the IBOG project stands as a symbol of how creativity, research, and partnerships can pave new ways of learning.\r\n<br/><br/>\r\nPhotos by CJ Lance Cubillas', '𝗡𝗘𝗠𝗦𝗨-𝗟𝗮𝘂𝗻𝗰𝗵𝗲𝘀-𝗜𝗕𝗢𝗚.jpg', 'Maisie Pecasales', 0, 'news', 1, '2025-08-30 10:42:02', NULL, NULL),
('422f3e5f-b8c3-11ee-aa14-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐂𝐨𝐥𝐥𝐞𝐠𝐞 𝐨𝐟 𝐋𝐚𝐰 𝐊𝐢𝐜𝐤𝐬 𝐎𝐟𝐟 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 𝐘𝐞𝐚𝐫 𝐰𝐢𝐭𝐡 𝐈𝐧𝐬𝐢𝐠𝐡𝐭𝐟𝐮𝐥 𝐒𝐭𝐮𝐝𝐞𝐧𝐭 𝐎𝐫𝐢𝐞𝐧𝐭𝐚𝐭𝐢𝐨𝐧', 'Law-2024', 'To mark the commencement of the academic year, the North Eastern Mindanao State University College of Law held its Student Orientation at the Audio Visual Center (AVC) on January 19, 2024. The event was attended by the distinguished Dean of the College of Law, Attorney Daniel L. Diaz, University President Dr. Nemesio G. Loayon, Vice President for Academic Affairs Dr. Ma. Lady Sol Suazo, and Campus Director Dr. Abundio C. Miralles, faculty and staff of the College of Law, and students.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nemsu-law-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nDuring the event, University President Dr. Nemesio G. Loayon delivered a compelling message, outlining his vision for NEMSU and emphasizing the vital role that the College of Law plays in realizing the broader mission of the university. Dr. Loayon praised the dedication of both faculty and students to legal education, stressing the imperative of producing ethical and socially responsible legal professionals who will make positive contributions to society.<br>\r\nDr. Ma. Lady Sol A. Suazo, the Vice President for Academic Affairs, underscored the profound significance of pursuing a law degree not merely for personal gain but as a manifestation of one\'s God-given talents in service to others. Her impassioned address resonated with the aspiring legal minds in the audience, emphasizing the transformative potential of legal education in shaping individuals who are not only competent in the field but also deeply committed to social justice.<br>\r\nThe Student Orientation served as a platform to provide invaluable insights into the institution\'s academic offerings, culture, and various opportunities available for students. With the faculty\'s guidance and the inspiration drawn from leaders like Dean Atty. Daniel L. Diaz, University President Dr. Nemesio G. Loayon, VPAA Dr. Ma. Lady Sol A. Suazo, and the whole NEMSU College of Law community, the incoming cohort of law students can anticipate a transformative journey marked by intellectual rigor, ethical grounding, and a deep sense of responsibility to serve the greater good. <br>\r\nAs the academic year unfolds, NEMSU College of Law stands poised to produce not just legal practitioners, but ethical leaders who will shape the future of the legal landscape.\r\n<br/>', 'nemsu-law-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-19 16:33:23', '2024-01-19 16:33:23', '2024-01-19 16:33:23'),
('42b16fce-9f09-42b4-b455-ccfd0dfb8d1d', 'NEMSU hosts FY 2023 DBM-SUCs & CHED 1st Quarter FDU Meeting', 'nemsu-hosts-fy-2023-dbm-sucs-amp-ched-1st-quarter-fdu-meeting', '<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">READ| The North Eastern Mindanao State University (NEMSU) spearheaded the DBM-SUCs and CHED 1<sup>st</sup> Quarter Full-time Delivery Unit (FDU) Meeting</span>, held at Alima ARQ Beach Resort, Britannia, San Agustin, Surigao del Sur.</span></span></p>', '<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">The FD</span>U is aimed at<span style=\"color:black\"> direct</span>ing the agencies<span style=\"color:black\"> to facilitate the implementation of programs and projects in order to realize the intended economic and social goals of the government for FY 2023.</span></span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">In attendance<span style=\"color:black\"> were the Regional Offices of the Department of Budget and Management (DBM), led by RD Maria Fe D. Jagna, the Commission on Higher Education (CHED),&nbsp; led by RD George M. Colorado, and the </span>Presidents<span style=\"color:black\"> of State Universit</span>ies<span style=\"color:black\"> and Colleges (SUC</span>s<span style=\"color:black\">) in Caraga Region together with their respective Vice Presidents for Administration and Finance, Budget Officers, Planning Officers and Accountants, among </span>other key officials<span style=\"color:black\">.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/FDU2.png\" /></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">NEMSU, as the host, has optimized its attendance, which included the Campus Directors and the committee members, along with the key officials.</span></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">Dr. Nemesio G. Loayon, NEMSU President, expressed his welcome greetings by highlighting the importance of financial management in achieving common goals and objectives.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/FDU3.png\" /></span></p>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">In his message, he asserted the vital role of SUCs&rsquo; solid understanding </span>of the financial<span style=\"color:black\"> situation and to be proactive in managing resources. With the comprehensive presentations and inputs from DBM and CHED</span>, t<span style=\"color:black\">he meeting intends to increase the close coordination between DBM RO-XIII and its client agencies in order to ensure that the agency&#39;s budget is fully utilized and that projects are implemented in accordance with budgetary requirements, ensuring that government resources are used wisely. <em>(Public Information Office)</em></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/FDU5.png\" /></span></p>\r\n', 'FDU5.png', 'Public Information Office', NULL, 'news', 1, '2023-02-16 12:06:20', '2023-02-17 04:46:28', '2023-02-17 04:46:28'),
('42fe9867-3d7c-11ee-a66e-a233a240566f', 'CHED Comm. Jo Mark M. Libre symphonizes the must-have SUCSTREND Event, leading NEMSU Delegation to Address Industry 5.0 Challenges', 'suctrend-2023', 'The NEMSU Pres. Nemesio G. Loayon, is steering the delegation from NEMSU to SUCSTREND: Human Resource Management in the Age of Industrial Revolution 5.0 from August 17-19, 2023', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>CHED Comm. Jo Mark M. Libre symphonizes the must-have SUCSTREND Event, leading NEMSU Delegation to Address Industry 5.0 Challenges. <br><br>\r\nThe NEMSU Pres. Nemesio G. Loayon, is steering the delegation from NEMSU to SUCSTREND: Human Resource Management in the Age of Industrial Revolution 5.0 from August 17-19, 2023 at Zamboanga State College of Marine Sciences and Technology.\r\nAs NEMSU navigates the challenges and opportunities presented by this new era, HR professionals play a vital role in facilitating a seamless transition for both employees and the academic community as a whole. <br><br>\r\nWith this, NEMSU extends profound gratitude to Commission on Higher Education(CHED) Comm. Jo Mark M. Libre for spearheading the event that ensures the successful adaptation of the workforce to these transformative changes. \r\n<br>', 'suctren-00.jpg', 'Public Information Office', 17, 'news', 1, '2023-08-18 12:00:59', '2023-08-18 12:00:59', '2023-08-18 12:00:59'),
('48f214fc-18ce-11ef-b18a-a233a240566f', '𝐒𝐓𝐔𝐃𝐄𝐍𝐓𝐒 𝐁𝐔𝐒𝐈𝐍𝐄𝐒𝐒 𝐂𝐎𝐍𝐆𝐑𝐄𝐒𝐒 𝟐𝟎𝟐𝟒', 'Bizcon-2024', 'It is a great honor to address this year\'s Students Business Congress, held under the powerful theme: 𝐈𝐧𝐬𝐩𝐢𝐫𝐞, 𝐈𝐧𝐭𝐞𝐠𝐫𝐚𝐭𝐞, 𝐈𝐧𝐧𝐨𝐯𝐚𝐭𝐞: 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐞𝐬 𝐟𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐢𝐧𝐠 𝐒𝐮𝐜𝐜𝐞𝐬𝐬.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIt is a great honor to address this year\'s Students Business Congress, held under the powerful theme: 𝐈𝐧𝐬𝐩𝐢𝐫𝐞, 𝐈𝐧𝐭𝐞𝐠𝐫𝐚𝐭𝐞, 𝐈𝐧𝐧𝐨𝐯𝐚𝐭𝐞: 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐞𝐬 𝐟𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐢𝐧𝐠 𝐒𝐮𝐜𝐜𝐞𝐬𝐬.\r\n<br>\r\n✨𝐈𝐧𝐬𝐩𝐢𝐫𝐞. Let your vision and creativity challenge the status quo and drive positive change in the world.\r\n<br>\r\n🤝 𝐈𝐧𝐭𝐞𝐠𝐫𝐚𝐭𝐞. Collaboration and the merging of diverse talents build stronger business strategies. Success is a shared journey.\r\n<br>\r\n🚀 𝐈𝐧𝐧𝐨𝐯𝐚𝐭𝐞. Sustainable success comes from offering unique and valuable products. As Jim Koch said, “You have a viable business only if your product is either better or cheaper than the alternatives.”\r\n<br>\r\nDraw strength from Hebrews 10:39, \"But we do not belong to those who shrink back and are destroyed, but to those who have faith and are saved.\" Persevere and have faith in your vision and abilities.\r\n<br>\r\nTogether, let\'s create a future marked by sustainable success and meaningful impact. Thank you and Mabuhay! May God always bless North Eastern Mindanao State University. 🌟📚🌍\r\n', 'bizcons.png', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2024-05-23 14:32:43', '2024-05-23 14:32:43', '2024-05-23 14:32:43');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('49229358-e4ed-11ef-8bc4-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝘁𝗮𝗰𝗸𝗹𝗲𝘀 𝗸𝗲𝘆 𝗶𝗻𝘀𝘁𝗶𝘁𝘂𝘁𝗶𝗼𝗻𝗮𝗹 𝗺𝗮𝘁𝘁𝗲𝗿𝘀 𝗳𝗼𝗿 𝗙.𝗬 𝟮𝟬𝟮𝟱', 'Institutional-Matters-F.Y.2025', 'North Eastern Mindanao State University (NEMSU) convened its 𝗙𝗶𝗿𝘀𝘁 𝗤𝘂𝗮𝗿𝘁𝗲𝗿 𝗘𝘅𝗲𝗰𝘂𝘁𝗶𝘃𝗲 𝗖𝗼𝗺𝗺𝗶𝘁𝘁𝗲𝗲 𝗠𝗲𝗲𝘁𝗶𝗻𝗴 at NEMSU Bislig Campus to discuss major institutional proposals, procurement plans, and financial strategies for Fiscal Year 2025. The meeting was attended by key university officials and executives led by University President Dr. Nemesio G. Loayon.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-03.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-04.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-06.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-07.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼𝗿-𝗙.𝗬𝟮𝟬𝟮𝟱-08.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) convened its 𝗙𝗶𝗿𝘀𝘁 𝗤𝘂𝗮𝗿𝘁𝗲𝗿 𝗘𝘅𝗲𝗰𝘂𝘁𝗶𝘃𝗲 𝗖𝗼𝗺𝗺𝗶𝘁𝘁𝗲𝗲 𝗠𝗲𝗲𝘁𝗶𝗻𝗴 at NEMSU Bislig Campus to discuss major institutional proposals, procurement plans, and financial strategies for Fiscal Year 2025. The meeting was attended by key university officials and executives led by University President Dr. Nemesio G. Loayon.\r\n<br/><br/>\r\nOne of the priority concerns raised was the identification of courses with high dropout rates to implement targeted interventions. In line with this, the committee reviewed a proposal for a university-sponsored scholarship program for student-athletes, and academically exceptional students. The initiative aims to provide financial assistance and minimize dropout rates among deserving students.\r\n<br/><br/>\r\nMoreover, the meeting also highlighted the continuation of the Tagbina Campus building project, with more than ₱2 million allocated for procurement. The initiative, classified as a continuing project, was added to the Annual Procurement Plan (APP), utilizing mandatory reserved funds due to structural damage caused by recent earthquakes.\r\n<br/><br/>\r\nVice President for Academic Affairs (VPAA) Dr. Maria Lady Sol A. Suazo discussed ongoing procurement matters, particularly Item No. 134, which focuses on delinquent contractors. The Project Management Unit (PMU) was requested to provide a bird’s-eye view of existing projects, with campus directors set to receive updates on the status of these initiatives.\r\n<br/><br/>\r\nFurther strengthening NEMSU’s academic framework, the Research Office was tasked with initiating an academic program through the conduct of at least one research proposal as part of its initial strategy.\r\nAdditionally, discussions centered on university branding and identity, particularly the NEMSU Alpas logo. The university is set to apply for a trademark to protect its branding, with plans to launch a revised version featuring the applied trademark. A temporary restriction order was also considered while awaiting the official approval of the trademark.\r\n<br/><br/>\r\nDuring the afternoon session, the discussion shifted to financial sustainability, particularly the absence of a capital outlay for 2025-2026. In response, a proposal of Prof Ramel Tomaquin to apply for a loan was put forward as an alternative funding strategy.\r\n<br/><br/>\r\nThe committee deliberated on Section 17 loan agreements, emphasizing the need to examine the university’s capacity to pay, assess financial risks, and ensure that NEMSU’s credit standing remains intact. President Nemesio highlighted the importance of adopting an “Entrepreneurial Mindset”, suggesting that infrastructure projects should be income-generating to sustain university operations. \r\n<br/><br/>\r\nAs part of NEMSU’s 8-Point Agenda, Dr. Abundio Miralles, Vice President for Admin and Finance emphasized that the Office of the President will oversee the implementation of programs and activities aligned with the university’s strategic vision.  Campus Directors from different campuses were encouraged to introduce relevant initiatives that contribute to institutional growth.\r\n<br/><br/>\r\nOther matters discussed included guidelines for inter-campus per diem, ensuring a balance between personnel comfort and safety; implementation of employee IDs and a new student ID template, set to take effect next semester, and the official transition of the university’s registered name from SDSSU to NEMSU.\r\n<br/><br/>\r\nThe meeting concluded with a call for collaboration among university officials to effectively implement these initiatives, ensuring NEMSU’s continuous development in both academic and administrative aspects.\r\n', '𝗺𝗮𝘁𝘁𝗲𝗿𝘀-𝗳𝗼r-𝗙.𝗬𝟮𝟬𝟮𝟱.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-04 08:33:38', '2025-02-04 08:33:38', '2025-02-04 08:33:38'),
('4924ce47-86f3-11f0-a6c6-a233a240566f', '𝐇𝐚𝐤𝐛𝐚𝐧𝐠, 𝐒𝐚𝐲𝐚, 𝐚𝐭 𝐒𝐞𝐥𝐞𝐛𝐫𝐚𝐬𝐲𝐨𝐧: 𝐌𝐚𝐤𝐮𝐥𝐚𝐲 𝐧𝐚 𝐀𝐒𝐄𝐀𝐍 𝐃𝐚𝐲 𝟐𝟎𝟐𝟓 𝐬𝐚 𝐍𝐄𝐌𝐒𝐔 𝐂𝐚𝐠𝐰𝐚𝐢𝐭', '𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭', 'Sa temang “Buwan ng ASEAN: Sama-sama sa Pag-unlad,” ginanap ng North Eastern Mindanao State University (NEMSU) – Cagwait Campus ang ASEAN Day 2025 sa 3-Storey Academic Building.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-6.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n 𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐒𝐮𝐫𝐢𝐠𝐚𝐨 𝐝𝐞𝐥 𝐒𝐮𝐫 - Sa temang “Buwan ng ASEAN: Sama-sama sa Pag-unlad,” ginanap ng North Eastern Mindanao State University (NEMSU) – Cagwait Campus ang ASEAN Day 2025 sa 3-Storey Academic Building.\r\n<br/><br/>\r\nNagsimula ang selebrasyon sa isang maikling programa na sinundan ng makulay na parada ng mga estudyante at guro na may dalang flaglets ng sampung bansang kasapi ng ASEAN bilang sagisag ng pagkakaisa at pagtutulungan.\r\nNagbigay ng pambungad na mensahe si Dr. Joezer S. Azon, Assistant Campus Director, kung saan kanyang binigyang-diin ang kahalagahan ng pagkakaisa, pagpapahalaga sa kultura, at aktibong partisipasyon ng mga estudyante sa pagdiriwang ng ASEAN Day.\r\n<br/><br/>\r\nIsa sa mga tampok na bahagi ng programa ang Best ASEAN Costume Competition, kung saan nagbihis ang bawat departamento sa tradisyonal na kasuotan ng bansang kanilang kinatawan. Matapos nito, nagpakitang-gilas ang bawat taon at departamento sa kanilang mga cheer at yell na nagpasigla sa buong venue.\r\nBago ang pagsisimula ng iba pang kompetisyon, nagbigay ng inspirasyonal na mensahe si Dr. Rozette E. Mercado, OIC-Campus Director, na muling nagpaalala sa kahalagahan ng pagkakaisa, aktibong partisipasyon, at pagpapahalaga sa kultura at kasaysayan ng ASEAN.\r\n<br/><br/>\r\nPagkatapos ng masiglang paligsahan, idineklara ang mga nagwagi sa Best ASEAN Costume, na nagbigay ng dagdag na inspirasyon at sigla sa mga kalahok. Sumunod dito ang iba’t ibang kompetisyon gaya ng mural painting, debate, at quiz bowl.\r\nBilang pagtatapos ng selebrasyon, nagbigay ng closing remarks si Sir Roque Quezada, MTTE, upang ipahayag ang pasasalamat sa lahat ng dumalo at naging bahagi ng matagumpay na pagdiriwang.\r\n<br/><br/>', '𝐀𝐒𝐄𝐀𝐍-𝐃𝐚𝐲-𝟐𝟎𝟐𝟓-𝐬𝐚-𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-1.jpg', 'Jennifer Vasquez', 0, 'news', 1, '2025-08-18 13:11:21', NULL, NULL),
('493f4bc6-53a7-11ee-b55e-a233a240566f', 'North Eastern Mindanao State University President Prof. Nemesio G. Loayon Enhances Partnerships in Philippine Public Higher Education;\r\nAttends \"Pagtutulay, Pagtutuloy\" Event at Dusit Thani Residence Davao', 'Partnerships-2023', 'Davao City, September 15, 2023– North Eastern Mindanao State University\'s President, Prof. Nemesio G. Loayon, played a prominent role in ', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University President Prof. Nemesio G. Loayon Enhances Partnerships in Philippine Public Higher Education;\r\nAttends \"Pagtutulay, Pagtutuloy\" Event at Dusit Thani Residence Davao<br><br>\r\nDavao City, September 15, 2023– North Eastern Mindanao State University\'s President, Prof. Nemesio G. Loayon, played a prominent role in strengthening partnerships within the Philippine public higher education landscape during today\'s \"Pagtutulay, Pagtutuloy\" event held at the prestigious Dusit Thani Residence Davao.<br><br>\r\nThe event, organized by the University of the Philippines brought together esteemed leaders from various Philippine public higher education institutions to discuss the future of education and collaboration.<br><br>\r\nPresident Loayon stated, \"Our commitment to providing quality education remains unwavering, but in today\'s rapidly changing world, we must adapt and seek partnerships that enable us to offer the best learning experiences to our students.\".<br><br>\r\nThe \"Pagtutulay, Pagtutuloy\" event served as a platform for leaders in Philippine higher education to exchange ideas, best practices, and strategies for the continued advancement of the nation\'s educational system. It also highlighted the crucial role that institutions like North Eastern Mindanao State University play in shaping the future of the Philippines.<br><br>\r\nThis is a dream coming into reality in the leadership of the 22nd UP President Atty. Angelo A. Jimenez, to bring the UP quality into the SUCs, where there will be no monopoly of knowledge and expertise,  being the National University in the country. His investiture \"Panaad at Kabilin\" was held yesterday at UP Mindanao for the first time in UP history. <br><br>\r\nProf. Loayon\'s participation in this significant event showcased his university\'s commitment to excellence and collaboration, further solidifying North Eastern Mindanao State University\'s position as a beacon of higher education in the region.<br><br>\r\nPresident Loayon expressed his optimism for the future of Philippine education, stating, \"Today\'s discussions have opened new doors and possibilities for our institution. We are eager to embark on this journey of transformation and partnership, ultimately benefiting our students and the entire nation.\"<br><br>\r\nThe \"Pagtutulay, Pagtutuloy\" event marked a pivotal moment in Philippine higher education, with President Loayon and North Eastern Mindanao State University leading the way toward a brighter future for students and institutions alike.\r\n\r\n', 'phe-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', NULL, 'news', 1, '2023-09-15 11:03:11', '2023-09-15 11:03:11', '2023-09-15 11:03:11'),
('4ab7f1c8-21f9-11ee-816f-a233a240566f', 'SYSTEM-WIDE LIBRARIANS’ AND STAFF MEETING', 'SYSTEM-WIDE-MEETING', '<p>Despite the pandemic, A F2F system-wide librarians’ and staff meeting of the seven campuses was held with the approval of the University President on March 22-23, 2021, at the main campus 3rd floor academic building with no less than the Director of Libraries, Mrs. Aida C. Osorio as the presiding officer.</p>', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nDespite the pandemic, A F2F system-wide librarians’ and staff meeting of the seven campuses was held with the approval of the University President on March 22-23, 2021, at the main campus 3rd floor academic building with no less than the Director of Libraries, Mrs. Aida C. Osorio as the presiding officer.\r\n<br><br>\r\n\r\nThe meeting started with a prayer led by Mr. Ronnie J. Sajelan followed by checking of attendance and without further ado, the meeting proper. Agenda were listed: Revision of Unit Manual; Collection Development Policy Statement; Library Staff Development Plan and ISO documents requirements on the Processes: QOP, SOP, QOM, RR…. Thorough discussions of the agenda were made and points of clarifications from the librarians were taken. More emphases were made on the revision of the Unit Manual and the ISO documents, where Sir James Q. Grefalde is invited virtually as the Resource Speaker. Many changes were incorporated and properly documented by the secretary. The Library Development Plan was also revisited.\r\n<br><br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_03.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>It was a day full of energy because snacks and lunch were served while the librarians are still working. So much has been done, the meeting adjourned at 5:00 p.m.\r\n<br><br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/library/wide_06.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>Resource Speaker, Mr. James Q. Grefalde highlighted his topic on the policies on ISO preparation of documents.\r\n<br><br>\r\n</span></p>', 'System-Wide.jpg', 'University Library', 10, 'news', 1, '2021-06-14 08:09:53', '2021-06-14 08:09:53', '2021-06-14 08:09:53'),
('4bac28ca-86ec-11f0-a6c6-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀 𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹 𝗧𝗶𝗲𝘀 𝗧𝗵𝗿𝗼𝘂𝗴𝗵 𝗠𝗢𝗔 𝗦𝗶𝗴𝗻𝗶𝗻𝗴 𝗳𝗼𝗿 𝗖𝗼𝗹𝗹𝗲𝗴𝗲 𝗼𝗳 𝗠𝗲𝗱𝗶𝗰𝗶𝗻𝗲', '𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴', 'In a significant move towards strengthening community-based healthcare education, the North Eastern Mindanao State University (NEMSU) held a Stakeholders’ Meeting and Multi-Agency Memorandum of Agreement (MOA) Signing Ceremony for the NEMSU College of Medicine today, August 4, 2025, at the University’s Conference Room.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-5.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a significant move towards strengthening community-based healthcare education, the North Eastern Mindanao State University (NEMSU) held a Stakeholders’ Meeting and Multi-Agency Memorandum of Agreement (MOA) Signing Ceremony for the NEMSU College of Medicine today, August 4, 2025, at the University’s Conference Room.\r\n<br/>\r\nThe ceremony, themed “Partnerships with Purpose: Strengthening Alliances in Health, Culture, and Compassion,” brought together representatives from the Provincial Health Office (PHO), City Health Office of Tandag, Municipal Health Office of Tago, and the Provincial Indigenous Peoples Mandatory Representative (IPMR), alongside university officials and partnered agencies and representatives of the Provincial and Municipal level.\r\n<br/>\r\nDuring the event, Dr. Ma. Cecilia C. Cuaresma-Cruz, Dean of the NEMSU College of Medicine, delivered the overview of the institutional partnership. She outlined the collaborative framework that will support the delivery of a community-oriented medical education program. \r\n<br/>\r\nAn open forum and MOA discussion followed, wherein stakeholders from health offices and IP communities provided their insights and affirmed their commitment to the initiative. The discussion highlighted the shared responsibilities in facilitating student internships, clinical rotations, and public health programs, as well as in supporting research, outreach, and health education campaigns in the partner communities.\r\n<br/>\r\nFollowing the discussions, the confirmation of partnerships was formalized through collective statements of support and commitment from the university and agency representatives, where all expressed institutional readiness to support the goals of the College of Medicine.\r\n<br/>\r\nThe activity concluded with the official signing of the MOA and a message of gratitude from Dr. Cuaresma-Cruz, who underscored the importance of collaborative governance in building a future generation of doctors grounded in compassion, competence, and cultural awareness.\r\n<br/>\r\nThe initiative marks a strategic step in aligning the university’s medical education with real-world community needs and reaffirms NEMSU’s role as a catalyst for inclusive and transformative public service.\r\n<br/>', '𝗡𝗘𝗠𝗦𝗨-𝗦𝘁𝗿𝗲𝗻𝗴𝘁𝗵𝗲𝗻𝘀-𝗠𝘂𝗹𝘁𝗶-𝗦𝗲𝗰𝘁𝗼𝗿𝗮𝗹-𝗧𝗶𝗲𝘀-𝗧𝗵𝗿𝗼𝘂𝗴𝗵-𝗠𝗢𝗔-𝗦𝗶𝗴𝗻𝗶𝗻𝗴-1.jpg', 'Public Information Office', 0, 'news', 1, '2025-08-04 11:48:49', NULL, NULL),
('4bd77134-1f88-11ee-816f-a233a240566f', 'The law, under Presidential Decree No. 907 grants those who graduated summa cum laude, magna cum laude or cum laude a Civil Service Eligibility.', 'Latin Honors', '', '<p style=\"text-align:justify\">We\'re glad to assist today, students with Latin honors in filing their eligibility at the Civil Service Commission\'s Caraga Regional Office.</p> <br />\r\n\r\n<p style=\"text-align:justify\">The law, under Presidential Decree No. 907 grants those who graduated summa cum laude, magna cum laude or cum laude a Civil Service Eligibility.</p> <br />\r\n\r\n<p style=\"text-align:justify\"> It\'s important for students to have the support they need in navigating the guidelines and requirements for such eligibility at the second level. Curriculum Director, Dr Erwin B. Berry and Asst. Campus Director, Dr. James Grefalde accompanied the candidates for graduation with Latin Honors, with a free ride. We thank Cantilan Campus Director, Dr. Juancho A. Intano for letting us use their coaster van.\r\nWe hope that the assistance provided by NEMSU was helpful and made the process smoother for the students.\r\n\r\nKudos to the Vice President for Academic Affairs, Prof. Maria Lady Sol A. Suazo for the full support of this endeavor.</p><br>\r\n\r\n<p style=\"text-align:left\">\r\n#studentassistance \r\n#CivilServiceCommission \r\n#LatinHonors\r\n#nemsuvision #nemsutouch #presidentofthegrassroots #VibrantLeadership\r\n</p><br/>\r\n', 'Latin-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-06-15 16:54:02', '2023-06-15 16:54:02', '2023-06-15 16:54:02'),
('4bfd0ed6-91db-11f0-a6c6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐒𝐭𝐮𝐝𝐞𝐧𝐭𝐬 𝐑𝐞𝐚𝐜𝐡 𝐅𝐢𝐧𝐚𝐥𝐬 𝐚𝐭 𝐈𝐧𝐭𝐞𝐫𝐧𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦', '𝐈𝐧𝐭𝐞𝐫𝐧𝐚𝐭𝐢𝐨𝐧𝐚𝐥-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥-𝐢𝐧-𝐕𝐢𝐞𝐭𝐧𝐚𝐦', 'North Eastern Mindanao State University (NEMSU) students represented the university in the Research Festival 2025 held at FPT University, Quy Nhon Campus, Binh Dinh, Vietnam, on August 14–17.', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦 6.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦 5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦 4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦 3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦 2.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) students represented the university in the Research Festival 2025 held at FPT University, Quy Nhon Campus, Binh Dinh, Vietnam, on August 14–17. <br>\r\nChristian John Arpilleda from the Department of Business and Management and Juros Lasco from the Department of Industrial Technology advanced to the Final Round in the Business Administration and Multimedia Communication Committees, respectively. They were accompanied by Dr. Loth Orozco, Internationalization Head of NEMSU-Cantilan Campus.\r\n<br/><br/>\r\nTogether with delegates from the University of Mindanao (UM), the NEMSU representatives toured the FPT University–Binh Dinh Campus, visited classrooms and facilities, and joined a cultural exchange session that introduced them to basic Vietnamese words, numbers, and traditions. They also attended a music session where they tried traditional Vietnamese instruments.\r\n<br/><br/>\r\nThe participants also visited Explorascience in Quy Nhon, Vietnam’s first science discovery center and the second of its kind in Southeast Asia, featuring interactive exhibits, live shows, and a planetarium.\r\n<br/><br/>\r\nThis meaningful step into student mobility was made possible through the unwavering support of Dr. Nemesio G. Loayon, University President; Dr. Maria Lady Sol A. Suazo, Vice President for Academic Affairs; Dr. Rolly G. Salvaleon, Vice President for Research and Extension; Ermie Lux L. Matildo, Director of the Office of International Affairs; and Dr. Juancho A. Intano, NEMSU Cantilan Campus Director.\r\n<br/><br/>\r\n𝘗𝘩𝘰𝘵𝘰 𝘤𝘰𝘶𝘳𝘵𝘦𝘴𝘺: 𝘍𝘗𝘛 𝘜𝘯𝘪𝘷𝘦𝘳𝘴𝘪𝘵𝘺 𝘢𝘯𝘥 𝘕𝘌𝘔𝘚𝘜-𝘊𝘢𝘯𝘵𝘪𝘭𝘢𝘯 𝘥𝘦𝘭𝘦𝘨𝘢𝘵𝘪𝘰𝘯.', '𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡 𝐅𝐞𝐬𝐭𝐢𝐯𝐚𝐥 𝐢𝐧 𝐕𝐢𝐞𝐭𝐧𝐚𝐦.jpg', 'Public Information Office', 0, 'news', 1, '2025-08-19 10:17:31', NULL, NULL),
('4cee4185-1d5f-11ef-b18a-a233a240566f', '𝘽𝘼𝘾𝘾𝘼𝙇𝘼𝙐𝙍𝙀𝘼𝙏𝙀 𝙈𝘼𝙎𝙎 𝘼𝙉𝘿 𝙋𝙍𝘼𝙄𝙎𝙀 𝘼𝙉𝘿 𝙒𝙊𝙍𝙎𝙃𝙄𝙋', 'Baccalaureate-Mass-2024', 'In this momentous celebration, let us come together to give glory and praise to the Lord for the remarkable journey we have had during the Academic Year 2023-2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/baccalaureate-mass-2024.jpg\" /></div>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn this momentous celebration, let us come together to give glory and praise to the Lord for the remarkable journey we have had during the Academic Year 2023-2024.\r\n<br><br>\r\nLet us be gathered for the 𝐁𝐚𝐜𝐜𝐚𝐥𝐚𝐮𝐫𝐞𝐚𝐭𝐞 𝐌𝐚𝐬𝐬 (for Catholics) at the New Cathedral and the 𝐏𝐫𝐚𝐢𝐬𝐞 𝐚𝐧𝐝 𝐖𝐨𝐫𝐬𝐡𝐢𝐩 𝐒𝐞𝐫𝐯𝐢𝐜𝐞 (for non-Catholics) at the AVC-NEMSU Tandag Campus on 𝐅𝐫𝐢𝐝𝐚𝐲, 𝐉𝐮𝐧𝐞 𝟐𝟏, 𝟐𝟎𝟐𝟒, 𝐚𝐭 𝟗:𝟎𝟎 𝐀𝐌.\r\n<br><br>\r\nGraduating students, please wear your graduation toga during these ceremonies. The Praise and Worship program is set to be finalized this week. Catholic graduating students are requested to be at the New Cathedral by 8:30 AM to participate in the processional march and to secure your seats according to your program. This will ensure we observe the solemnity of the celebration with our very own 𝐌𝐨𝐬𝐭 𝐑𝐞𝐯. 𝐑𝐚𝐮𝐥 𝐁. 𝐃𝐚𝐞𝐥, 𝐃𝐃, who will preside over the Mass.\r\n<br><br>\r\nYour presence - graduating students, parents, guests, and friends—is the most cherished part of this meaningful occasion.\r\n<br><br>\r\nFor this month, our Lead Mass Sponsor will be the College of Teacher Education. Together, let us rejoice, reflect, and renew our commitment to excellence and communal spirit as one NEMSU Family.\r\n<br><br>\r\nThank you and God be with you. 🤍💙<br>\r\nThe Values Formation Office 🕊️<br>\r\nTandag Campus\r\n<br/>\r\n\r\n</div>', 'baccalaureate-mass-2024.jpg', 'Public Information Office', 0, 'announcement', 1, '2024-05-26 10:00:44', '2024-05-26 10:00:44', '2024-05-26 10:00:44'),
('4e7b9eea-5c29-11ee-a632-a233a240566f', 'NEMSU bolsters Safe and Drug-free Environment', 'Bolsters-2023', 'With the aim of combating illegal drugs and fostering student safety, North Eastern Mindanao State University Main has taken proactive steps together with the Commission on Higher Education (CHED) to ensure that every student\'s educational journey is free from threats.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nWith the aim of combating illegal drugs and fostering student safety, North Eastern Mindanao State University Main has taken proactive steps together with the Commission on Higher Education (CHED) to ensure that every student\'s educational journey is free from threats.<br><br>\r\nCHED Caraga, in collaboration with various government agencies such as the Department of the Interior and Local Government (DILG), the Philippine Drug Enforcement Agency (PDEA), the Philippine National Police (PNP), the National Police Commission (NAPOLCOM), the National Intelligence Coordinating Agency (NICA), and the Philippine Information Agency (PIA), is embarking on a comprehensive effort to encourage the youth to actively participate in the campaigns against illegal drugs. These campaigns are known as Adbokasiya Laban sa Illegal na Droga (ALAB) and Buhay Ingatan, Droga\'y Ayawan (BIDA).<br><br>\r\nDr. Dave Villarin, the Chief of Information Management Branch, shares profound insights into the pivotal role that the youth play in shaping the nation\'s future. He emphasizes that the youth represent the strength of our nation and serve as the torchbearers of change. It is crucial to guide them in the right direction, as they are the hope of tomorrow.<br><br>\r\nAlso discussed is the significance of drug education by Chief Dindo D. Abellanosa. He asserts, \"Ayaw lang jud gamit kay makaguba ug utok,\" leaving a cautionary note that using illegal substances will not provide solutions to life\'s challenges; instead, they will only exacerbate one\'s problems.<br><br>\r\n𝘙𝘦𝘱𝘰𝘳𝘵 𝘣𝘺 𝘕𝘦𝘳𝘭𝘢𝘯𝘪𝘦 𝘎𝘰𝘱𝘪𝘰<br>\r\n𝘗𝘩𝘰𝘵𝘰𝘴 𝘣𝘺 𝘓𝘭𝘰𝘺𝘥 𝘕𝘢𝘳𝘢𝘯𝘫𝘰 & 𝘙𝘰𝘨𝘦𝘳 𝘉𝘢𝘨𝘰𝘰𝘥<br><br>\r\n#TheVanguardPublication\r\n\r\n', 'bolster-00.jpg', 'The Vanguard Publication', NULL, 'news', 1, '2023-09-21 11:59:11', '2023-09-21 11:59:11', '2023-09-21 11:59:11'),
('4fc8ba00-3f43-4cb6-9f72-271f3754a3ad', 'CHED Commissioner, Dr. Libre graces Curriculum Revision of NEMSU', 'ched-commissioner-dr-libre-graces-curriculum-revision-of-nemsu', '<p>During the Curriculum Review, Revision, and Mapping across Programs of North Eastern Mindanao State University, CHED Commisioner Dr. Jo Mark M. Libre afforded his overwhelming support for NEMSU by virtually gracing its curriculum revision activity despite his hectic schedule.</p>', '<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">During the Curriculum Review, Revision, and Mapping across Programs of North Eastern Mindanao State University, CHED Commisioner Dr. Jo Mark M. Libre afforded his overwhelming support for NEMSU by virtually gracing its curriculum revision activity despite his hectic schedule.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">Dr. Libre expressed his concern regarding the current situation of the students and challenged the university to consistently examine and revise the curriculum.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">&quot;The curriculum has always been the heart of every academic institution, and I challenge the university to have a constant conduct of the curriculum colloquium with our stakeholders,&quot; Dr. Libre articulated.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">In support of the curricular revision activity, Dr. Libre lauded the intervention of the University&#39;s administration with it&#39;s continuous dedication to pursue quality education.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">&quot;It is through the changes that we will make to the structure and design that we somehow align the instructional activities and materials of the program as well as the institutional outcomes,&quot; the Commissioner added.</span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">Nearing the end of his message, Dr. Libre reiterated his challenge to the institution in applying the main purpose of the activity and consistently reshaping the academic landscape of the university for the years to come.</span></p>', '335857220_1181360105896446_5094610700545455392_n.jpg', 'Marc Daniel Enero', NULL, 'news', 1, '2023-03-17 09:06:07', '2023-03-17 01:14:15', '2023-03-17 01:14:15'),
('51515796-53a6-11ee-b55e-a233a240566f', 'NEMSU Pres. Nemesio G. Loayon inks Mindanao Declaration on Excellence and Equity in Public HEIs with UP & SUCs', 'UP-SUCs-2023', 'Davao City, September 15, 2023- The President of North Eastern Mindanao State University (NEMSU), Dr. Nemesio G. Loayon, signed the Mindanao Declaration on Excellence and Equity in Public Higher Education', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/up-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU Pres. Nemesio G. Loayon inks Mindanao Declaration on Excellence and Equity in Public HEIs with UP & SUCs<br><br>\r\nDavao City, September 15, 2023- The President of North Eastern Mindanao State University (NEMSU), Dr. Nemesio G. Loayon, signed the Mindanao Declaration on Excellence and Equity in Public Higher Education with the University of the Philippines and other State Universities and Colleges in the Country during the SUC Summit held at Dusit Thani Residence in Davao City on September 15, 2023.\r\nThe event was attended by various officials including Sen. Bong Go, CHED Chairperson J Prospero De Vera III, Commissioner Jo Mark Libre, UP President Angelo Jimenez, SUC Presidents, and other dignitaries.<br><br>\r\nThe summit, called \"Pagtutulay, Pagtutuloy: The 1st UP-SUC Summit,\" aimed to bring together leaders and prime movers of State Universities and Colleges (SUCs) to inspire inter-SUC engagements in transdisciplinary academic, research, and public service programs.<br><br>\r\nIt is envisioned to promote many things, including presenting opportunities for student and faculty exchange, research and public service collaboration, and sharing resources.<br><br>\r\nAdditionally, the summit aimed to promote best practices and innovative approaches in teaching and learning, research, and public service.\r\nDiscussions centered around strategies for establishing and maintaining linkages between and among SUCs.<br><br>\r\nThe summit also aimed to establish a network for sustainable and effective collaboration among UP, SUCs, and the Commission on Higher Education (CHED).\r\nThe event highlighted panel discussions on UP and SUC-initiated collaborations and actual demonstrations of UP’s innovations, programs, and resources, which may be offered collectively with the SUCs. CHED Chair J. Prospero De Vera delivered the Keynote Message.<br><br>\r\nThe one-day event culminated in the signing of the Mindanao Declaration that sealed the commitment of UP and the other SUCs towards stronger and more effective cooperation.<br><br>\r\nAfter the panel discussion on UP-initiated Academic, Research, and Public Service Collaborations with speakers Elena R. Mirano, Professor Emeritus, Arts Studies, UP Diliman; Gerardo D. Legaspi, Director, UP Philippine General Hospital; Violeta V. Bautista, Professor Emeritus, UP Diliman-CCSP and Founding Director, UPD-Psychosocial Services; Luis G. Sison, Director, UP Technology Transfer and Business Development Office, President Loayon opined and inquired about establishing the NEMSU College of Medicine, how UP can assist NEMSU for its operations, and the roles and obligations of the parties to make such collaboration a dream-come-true milestone.<br><br>\r\nPresident Loayon along with other SUC Presidents had a photo opportunity with Sen. Bong Go.\r\n\r\n', 'up-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', NULL, 'news', 1, '2023-09-15 16:33:11', '2023-09-15 16:33:11', '2023-09-15 16:33:11'),
('5174705b-6e71-11f0-ae5d-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩 𝐢𝐧 𝐕𝐢𝐫𝐭𝐮𝐚𝐥 𝐌𝐎𝐔 𝐒𝐢𝐠𝐧𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲', '𝐍𝐄𝐌𝐒𝐔-𝐚𝐧𝐝-𝐉𝐮𝐧𝐢𝐨𝐫-𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭-𝐨𝐟-𝐭𝐡𝐞-𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬-𝐒𝐞𝐚𝐥-𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩', 'July 23, 2025 — 𝙏𝙝𝙚 𝙉𝙤𝙧𝙩𝙝 𝙀𝙖𝙨𝙩𝙚𝙧𝙣 𝙈𝙞𝙣𝙙𝙖𝙣𝙖𝙤 𝙎𝙩𝙖𝙩𝙚 𝙐𝙣𝙞𝙫𝙚𝙧𝙨𝙞𝙩𝙮 (𝙉𝙀𝙈𝙎𝙐) 𝙖𝙣𝙙 𝙅𝙪𝙣𝙞𝙤𝙧 𝘼𝙘𝙝𝙞𝙚𝙫𝙚𝙢𝙚𝙣𝙩 𝙤𝙛 𝙩𝙝𝙚 𝙋𝙝𝙞𝙡𝙞𝙥𝙥𝙞𝙣𝙚𝙨, 𝙄𝙣𝙘. 𝙤𝙛𝙛𝙞𝙘𝙞𝙖𝙡𝙡𝙮 𝙚𝙣𝙩𝙚𝙧𝙚𝙙 𝙞𝙣𝙩𝙤 𝙖 𝙨𝙩𝙧𝙖𝙩𝙚𝙜𝙞𝙘 𝙥𝙖𝙧𝙩𝙣𝙚𝙧𝙨𝙝𝙞𝙥 𝙩𝙝𝙧𝙤𝙪𝙜𝙝 𝙖 𝙫𝙞𝙧𝙩𝙪𝙖𝙡 𝙈𝙚𝙢𝙤𝙧𝙖𝙣𝙙𝙪𝙢 𝙤𝙛 𝙐𝙣𝙙𝙚𝙧𝙨𝙩𝙖𝙣𝙙𝙞𝙣𝙜 (𝙈𝙊𝙐) 𝙨𝙞𝙜𝙣𝙞𝙣𝙜 𝙘𝙚𝙧𝙚𝙢𝙤𝙣𝙮 held at 2:00 PM Philippine Time.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩-3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩-4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩-5.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nJuly 23, 2025 — 𝙏𝙝𝙚 𝙉𝙤𝙧𝙩𝙝 𝙀𝙖𝙨𝙩𝙚𝙧𝙣 𝙈𝙞𝙣𝙙𝙖𝙣𝙖𝙤 𝙎𝙩𝙖𝙩𝙚 𝙐𝙣𝙞𝙫𝙚𝙧𝙨𝙞𝙩𝙮 (𝙉𝙀𝙈𝙎𝙐) 𝙖𝙣𝙙 𝙅𝙪𝙣𝙞𝙤𝙧 𝘼𝙘𝙝𝙞𝙚𝙫𝙚𝙢𝙚𝙣𝙩 𝙤𝙛 𝙩𝙝𝙚 𝙋𝙝𝙞𝙡𝙞𝙥𝙥𝙞𝙣𝙚𝙨, 𝙄𝙣𝙘. 𝙤𝙛𝙛𝙞𝙘𝙞𝙖𝙡𝙡𝙮 𝙚𝙣𝙩𝙚𝙧𝙚𝙙 𝙞𝙣𝙩𝙤 𝙖 𝙨𝙩𝙧𝙖𝙩𝙚𝙜𝙞𝙘 𝙥𝙖𝙧𝙩𝙣𝙚𝙧𝙨𝙝𝙞𝙥 𝙩𝙝𝙧𝙤𝙪𝙜𝙝 𝙖 𝙫𝙞𝙧𝙩𝙪𝙖𝙡 𝙈𝙚𝙢𝙤𝙧𝙖𝙣𝙙𝙪𝙢 𝙤𝙛 𝙐𝙣𝙙𝙚𝙧𝙨𝙩𝙖𝙣𝙙𝙞𝙣𝙜 (𝙈𝙊𝙐) 𝙨𝙞𝙜𝙣𝙞𝙣𝙜 𝙘𝙚𝙧𝙚𝙢𝙤𝙣𝙮 held at 2:00 PM Philippine Time.\r\n\r\n<br/><br/>\r\nThis momentous event marked a significant step forward in NEMSU’s commitment to fostering youth development and academic excellence by collaborating with one of the country’s leading organizations in youth empowerment and entrepreneurship education.\r\nPresent during the virtual signing was NEMSU President, Dr. Nemesio G. Loayon, who led the university delegation and expressed strong support for the partnership. Dr. Loayon emphasized the importance of aligning with institutions like Junior Achievement to provide NEMSU students with enhanced opportunities for leadership development, financial literacy, and entrepreneurial experience.\r\n<br/><br/>\r\nAlso in attendance were the university’s key officials and representatives, including the Vice Presidents, Campus Directors from Tandag, Tagbina, Lianga, and Cantilan, CBM Dean, Director for Curriculum Development, Legal Officer, Heads for Curriculum Development (Cantilan, Lianga, Tandag, and Tagbina), CBM Department Chairs, and CBM Program Coordinators.\r\nThe MOU outlines clear goals for collaboration on programs that promote real-world skills and learning experiences, reinforcing NEMSU’s mission to prepare students for future careers and community engagement.\r\n<br/><br/>\r\nThis meaningful partnership underscores NEMSU’s continued drive to build impactful collaborations that enrich the academic journey of its students, while supporting the university’s vision of transformative and inclusive education.\r\n', '𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐉𝐮𝐧𝐢𝐨𝐫 𝐀𝐜𝐡𝐢𝐞𝐯𝐞𝐦𝐞𝐧𝐭 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐒𝐞𝐚𝐥 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-23 08:42:47', NULL, NULL),
('51861e2a-89f7-11ee-8f14-a233a240566f', 'NEMSUs Center for Human Rights Education Main Campus is Champion during the Regional Higher Education Confab for Human Rights Year 2 in Butuan City. ', 'Confab-Human-rights-champ', 'NEMSUs Center for Human Rights Education Main Campus is Champion during the Regional Higher Education Confab for Human Rights Year 2 in Butuan City. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/human-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/human-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/human-03.JPG\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSUs Center for Human Rights Education Main Campus is Champion during the Regional Higher Education Confab for Human Rights Year 2 in Butuan City. A Cash Prize of 20,000 is granted plus 40, 000 as fund for the Project Implementation proposed by the Team of Project Proponents: Rico Jay L. Caberte  and Jericka G. Soria Project adviser ROBERT E WARIZA JR Congratulations!\r\n<br>', 'human-00.jpg', 'Office of the Campus Director - Tandag', 0, 'news', 1, '2023-11-23 19:10:11', '2023-11-23 19:10:11', '2023-11-23 19:10:11'),
('51d2762d-d11e-11ee-aa14-a233a240566f', '𝐂𝐡𝐚𝐫𝐭𝐢𝐧𝐠 𝐭𝐡𝐞 𝐂𝐨𝐮𝐫𝐬𝐞: 𝐍𝐄𝐌𝐒𝐔\'𝐬 𝐃𝐢𝐯𝐞 𝐢𝐧𝐭𝐨 𝐂𝐨𝐥𝐥𝐞𝐠𝐞 𝐨𝐟 𝐌𝐞𝐝𝐢𝐜𝐢𝐧𝐞 𝐏𝐡𝐚𝐬𝐞 𝟏 𝐏𝐥𝐚𝐧𝐧𝐢𝐧𝐠', 'College-of-medicine-2024', 'The North Eastern Mindanao State University (NEMSU) successfully conducted the 3-day Navigating Phase 1: A Workshop and Training for the Application of the College of Medicine Program on February 18-21, 2023, at Spacebar, Cagwait, Surigao del Sur. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-00.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-05.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-06.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/cm-08.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University (NEMSU) successfully conducted the 3-day Navigating Phase 1: A Workshop and Training for the Application of the College of Medicine Program on February 18-21, 2023, at Spacebar, Cagwait, Surigao del Sur. \r\nThe workshop brought together key officials, including Dr. Nemesio G. Loayon, the University President, Dr. Ma. Lady Sol A. Suazo, the Vice President for Academic Affairs, Dr. Abundio C. Miralles, the Vice President for Administration and Finance, Dr. Rolly G. Salvaleon, the Vice President for Research and Extension, alongside other committee members. <br><br>\r\nDr. Cecilia Cruz, a renowned expert, served as the resource speaker during the three-day workshop and training.<br><br>\r\nThroughout the workshop, Dr. Cruz provided invaluable insights, focusing on the goal of establishing a medical school in Surigao del Sur that caters to Mindanaons, with a special emphasis on the Indigenous Community. The objective is to produce five-star doctors for the country, dedicated to serving the nation in the field of health. Discussions also revolved around crucial aspects such as curriculum development, infrastructure requirements, and the overall strategy for the successful establishment of the College.<br><br>\r\nNEMSU remains committed to enhancing its academic offerings and ensuring quality education. The workshop served as a vital platform for collaboration and strategic planning, marking a significant step forward in the university\'s pursuit of excellence in medical education.\r\n<br/>', 'cm-09.jpg', 'Public Information Office', 0, 'news', 1, '2024-02-21 09:50:11', '2024-02-21 09:50:11', '2024-02-21 09:50:11'),
('529aea66-1b5e-11ef-b18a-a233a240566f', '𝐒𝐭𝐮𝐝𝐞𝐧𝐭 𝐓𝐞𝐚𝐜𝐡𝐞𝐫𝐬\' 𝐂𝐨𝐧𝐠𝐫𝐞𝐬𝐬 𝟐𝟎𝟐𝟒', 'CTE-Congress-2024', ' The opening program for this year\'s Student Teachers\' Congress 2024 officially commenced this morning, May 25, 2024, at Prospero Pichay, Sr. Gymnasium. The event gathers pre-service teachers from the six (6) NEMSU campuses offering teacher education programs. ', 'The opening program for this year\'s Student Teachers\' Congress 2024 officially commenced this morning, May 25, 2024, at Prospero Pichay, Sr. Gymnasium. The event gathers pre-service teachers from the six (6) NEMSU campuses offering teacher education programs. Participants are set to engage in a series of workshops, lectures, and collaborative activities designed to enhance their professional development. \r\n<br><br>\r\nThis annual congress serves as a platform for aspiring educators to network, share experiences, and gain insights from experts in the field of education.', 'cte-congress.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-24 20:48:31', '2024-05-24 20:48:31', '2024-05-24 20:48:31'),
('530fd026-6c88-11ee-a3fc-a233a240566f', 'Gender and Development Seminar', 'Cantilan-Gad-2023', 'The faculty and staff of North Eastern Mindanao State University Cantilan Campus conducted its family day along with Gender and Development Seminar last September 28-29, 2023 with the theme, “Transforming Public Service in the Next Decade:', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/gad-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe faculty and staff of North Eastern Mindanao State University Cantilan Campus conducted its family day along with Gender and Development Seminar last September 28-29, 2023 with the theme, “Transforming Public Service in the Next Decade: Honing Agile and Future-ready Servant-heroes,” held at JB Nature Farm and Resort, Sukailang, Surigao City, Surigao del Norte. The event serves as a memoir to remember that employees\' bonds go beyond the office and classroom walls. It is the support, unity, and trust shared that will make  a strong team . It celebrates the selfless dedication, sacrifice, and service that strengthened the bonds of those who shape students\' future. It also serves as a strategic move in creating a positive and supportive work environment, ensuring the continuity of educational excellence.<br><br>', 'gad-00.jpg', 'The Craftsman Publication', NULL, 'news', 1, '2023-10-04 15:29:11', '2023-10-04 15:29:11', '2023-10-04 15:29:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('5484c445-3a3b-11ee-a66e-a233a240566f', '𝐌𝐎𝐀 𝐬𝐢𝐠𝐧𝐢𝐧𝐠 𝐛𝐞𝐭𝐰𝐞𝐞𝐧 𝐍𝐨𝐫𝐭𝐡 𝐄𝐚𝐬𝐭𝐞𝐫𝐧 𝐌𝐢𝐧𝐝𝐚𝐧𝐚𝐨 𝐒𝐭𝐚𝐭𝐞 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐲 𝐚𝐧𝐝 𝐀𝐝𝐞𝐥𝐚 𝐒𝐞𝐫𝐫𝐚 𝐓𝐲 𝐌𝐞𝐦𝐨𝐫𝐢𝐚𝐥 𝐌𝐞𝐝𝐢𝐜𝐚𝐥 𝐂𝐞𝐧𝐭𝐞𝐫', 'nemsu-astmmc-2023', 'A Memorandum Of Agreement Signing was held between the North Eastern Mindanao State University (Represented by NEMSU President Dr. Nemesio G. Loayon) and Adela Serra Ty Memorial Medical Center', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/moa-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nA Memorandum Of Agreement Signing was held between the North Eastern Mindanao State University (Represented by NEMSU President Dr. Nemesio G. Loayon) and Adela Serra Ty Memorial Medical Center (represented by Medical Chief II Panfilo Jorge M. Tremedal III, MD, MHA, FPCHA, FPSMSG) at the Culmination Program of ASTMMC’s National Health Week Celebration.\r\n<br/>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU and ASTMMC agreed to establish partnerships for it can have far-reaching positive impacts on education, research, healthcare delivery, and the overall attainment of medical services to the public. This collaboration also provides an opportunity of fruitful engagements as NEMSU is on its way in opening the College of Medicine. Thus, ASTMMC can provide medical expertise and assistance in the pursuit of opening the College of Medicine. In the same way, NEMSU can also assist the medical institution in providing ongoing professional development for healthcare providers. Access to academic resources, workshops, and collaborative opportunities helps medical workers stay updated on the latest advancements in their field.\r\n<br/>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThis partnership leverages the strengths of both sectors to create a synergistic relationship that benefits patients, healthcare providers, researchers, educators, and society as a whole.\r\n<br/>', 'moa-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-08-11 23:20:11', '2023-08-11 23:20:11', '2023-08-11 23:20:11'),
('56d9e269-0e90-11ef-b18a-a233a240566f', '𝟰𝘁𝗵 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 𝗗𝗮𝘆 𝗮𝗻𝗱 𝘁𝗵𝗲 𝟯𝟬𝘁𝗵 𝗙𝗼𝘂𝗻𝗱𝗶𝗻𝗴 𝗔𝗻𝗻𝗶𝘃𝗲𝗿𝘀𝗮𝗿𝘆 𝗼𝗳 𝘁𝗵𝗲 𝗖𝗼𝗺𝗺𝗶𝘀𝘀𝗶𝗼𝗻 𝗼𝗻 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 (𝗖𝗛𝗘𝗗)', '4th-CHED', 'North Eastern Mindanao State University is one in commemorating the 𝟰𝘁𝗵 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 𝗗𝗮𝘆 𝗮𝗻𝗱 𝘁𝗵𝗲 𝟯𝟬𝘁𝗵 𝗙𝗼𝘂𝗻𝗱𝗶𝗻𝗴 𝗔𝗻𝗻𝗶𝘃𝗲𝗿𝘀𝗮𝗿𝘆 𝗼𝗳 𝘁𝗵𝗲 𝗖𝗼𝗺𝗺𝗶𝘀𝘀𝗶𝗼𝗻 𝗼𝗻 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 (𝗖𝗛𝗘𝗗). This impactful celebration, held from May 10 to 17, 2024, with the theme “𝗧𝗿𝗮𝗻𝘀𝗳𝗼𝗿𝗺𝗮𝘁𝗶𝘃𝗲 𝗮𝗻𝗱 𝗥𝗲𝘀𝗶𝗹𝗶𝗲𝗻𝘁 𝗣𝗵𝗶𝗹𝗶𝗽𝗽𝗶𝗻𝗲 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻.”', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University is one in commemorating the 𝟰𝘁𝗵 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 𝗗𝗮𝘆 𝗮𝗻𝗱 𝘁𝗵𝗲 𝟯𝟬𝘁𝗵 𝗙𝗼𝘂𝗻𝗱𝗶𝗻𝗴 𝗔𝗻𝗻𝗶𝘃𝗲𝗿𝘀𝗮𝗿𝘆 𝗼𝗳 𝘁𝗵𝗲 𝗖𝗼𝗺𝗺𝗶𝘀𝘀𝗶𝗼𝗻 𝗼𝗻 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻 (𝗖𝗛𝗘𝗗). This impactful celebration, held from May 10 to 17, 2024, with the theme “𝗧𝗿𝗮𝗻𝘀𝗳𝗼𝗿𝗺𝗮𝘁𝗶𝘃𝗲 𝗮𝗻𝗱 𝗥𝗲𝘀𝗶𝗹𝗶𝗲𝗻𝘁 𝗣𝗵𝗶𝗹𝗶𝗽𝗽𝗶𝗻𝗲 𝗛𝗶𝗴𝗵𝗲𝗿 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻.”\r\n<br><br>\r\nIt symbolizes a commitment towards excellence in higher education, reflecting on the transformative journey and resilience of education systems across the Philippines.\r\nNorth Eastern Mindanao State University’s participation highlights its dedication to contributing significantly to this national advancement in education.\r\nCongratulations CHED and here\'s to many more years of excellence and success\r\n<br/>', '4th-Higher-Ed.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-10 13:43:39', '2024-05-10 13:43:39', '2024-05-10 13:43:39'),
('5765c1cd-a450-11ee-9af6-a233a240566f', 'NEMSU Board of Regents Approves Key Measures in 4th Quarter Meeting at CHED Central Office', '1th-Quarter-Meeting-at-CHED-Central-Office', 'In a landmark session held at the Commission on Higher Education (CHED) Central Office, the North Eastern Mindanao State University (NEMSU) Board of Regents convened for their 4th Quarter Regular Meeting, endorsingl initiatives for the institution\'s growth and development.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bors-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bors-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bors-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU Board of Regents Approves Key Measures in 4th Quarter Meeting at CHED Central Office\r\n<br>\r\nDecember 19, 2023\r\n<br>\r\nIn a landmark session held at the Commission on Higher Education (CHED) Central Office, the North Eastern Mindanao State University (NEMSU) Board of Regents convened for their 4th Quarter Regular Meeting, endorsing initiatives for the institution\'s growth and development.\r\n<br>\r\nThe board greenlit a CNA reflecting a commitment to fair and just labor practices.\r\nA significant SRI was approved, acknowledging the dedication and contributions of the university\'s faculty and staff.\r\n<br>\r\n Recognizing excellence, the board sanctioned a PEI.\r\nThe list of candidates for graduation for the 1st semester of Academic Year 2023-2024 received unanimous approval, marking a significant step for students on the brink of completing their academic journey.\r\n<br>\r\nAcknowledging the importance of seamless digitalization, the board sanctioned the procurement of direct Internet access, aimed at enhancing connectivity and fostering a technologically advanced environment within NEMSU.\r\nIn a move to bolster academic research, seven research centers will be established within the university, fostering an environment conducive to innovation and scholarly pursuits.\r\n<br>\r\nThe board underscored its commitment to the welfare of Contract of Service (COS) and Job Order (JO) employees by approving gratuity pay.\r\nRecognizing the evolving landscape of the academic community, the board greenlighted a faculty reclassification  to ensure that faculty welfare is an attended concern as a University. \r\n<br>\r\nA groundbreaking agreement was reached between NEMSU and the Catholic Bishop of Tandag Inc., signifying a collaborative effort to utilize and share resources for mutual benefit through a lot area of more than 1,000 square meters for the pathway to Cagwait Campus\' entrance. \r\n<br>\r\n The comprehensive Faculty Development Policy and Admission and Retention Policy was approved, emphasizing continuous learning and professional growth.\r\nAcknowledging the need for stability during transitional periods, the board approved the hold-over capacity of designees until January 31, 2024.\r\n<br>\r\nThe decisions made during this meeting are poised to propel NEMSU into a new era of academic excellence, technological advancement, and collaborative partnerships. \r\nComm. Jo Mark M. Libre, NEMSU\'s BOR Chairperson,  presided the meeting. He also expressed his gratitude to NEMSU for its full participation and support during the flag raising ceremony held yesterday.\r\n<br>\r\n', 'bors-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2023-12-19 18:40:11', '2023-12-19 18:40:11', '2023-12-19 18:40:11'),
('578f95bb-e46a-11ef-8bc4-a233a240566h', '𝟰𝘁𝗵 𝗡𝗘𝗠𝗦𝗨𝗹𝘁𝗶 𝗣𝗿𝗲𝘀𝘀𝗖𝗼𝗻 𝗵𝗶𝗴𝗵𝗹𝗶𝗴𝗵𝘁𝘀 𝗰𝗮𝗺𝗽𝘂𝘀-𝘄𝗶𝗱𝗲 𝗸𝗲𝘆 𝘂𝗽𝗱𝗮𝘁𝗲𝘀, 𝗮𝗱𝗱𝗿𝗲𝘀𝘀𝗲𝘀 𝗾𝘂𝗲𝗿𝗶𝗲𝘀 𝗮𝗺𝗼𝗻𝗴 𝘀𝗲𝘃𝗲𝗻 𝗰𝗮𝗺𝗽𝘂𝘀𝗲𝘀', '4th-NEMSUlti-PressCon', 'With the goal of fostering an informed academic community, the North Eastern Mindanao State University’s (NEMSU) seven campuses convened on-site and online for the 4th NEMSUlti Executive Press Conference, highlighting the administration’s ongoing developments and achievements at NEMSU-Cantilan Campus yesterday, February 3.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nWith the goal of fostering an informed academic community, the North Eastern Mindanao State University’s (NEMSU) seven campuses convened on-site and online for the 4th NEMSUlti Executive Press Conference, highlighting the administration’s ongoing developments and achievements at NEMSU-Cantilan Campus yesterday, February 3.\r\n<br><br>\r\nThrough a live broadcast and Zoom, university key officials, student leaders, campus press, and stakeholders attended the conference to strengthen communication between the administration and the academic community through an open forum.\r\n<br><br>\r\nUniversity President III, Dr. Nemesio G. Loayon, presented the fiscal year 2024 report, featuring the university’s progress toward its long-term vision of becoming a research institution focused on advancing technology and innovation for sustainable development.\r\n<br><br>\r\nDr. Loayon emphasized the university\'s commitment to academic excellence by highlighting the high board exam success rate of graduates, which reflects the strength of the institution’s workforce and its adherence to quality education standards.\r\n<br><br>\r\nRegarding infrastructure development, Dr. Loayon shared updates on the construction of a three-story dormitory, a three-story academic building for the engineering department, a new library, and a two-story smart building at the Main Campus, along with a multi-sports covered court at Cantilan Campus and a computer laboratory at Tagbina Campus.\r\n<br><br>\r\nThe open forum, a key part of the press conference, allowed participants to raise concerns and discuss ongoing initiatives and strategies to ensure that relevant issues are addressed.\r\n<br><br>\r\nThe conference reaffirmed the administration’s commitment to fostering open dialogue, transparency, and collaboration within the academic community, ensuring that all members remain well-informed about the university’s progress and future developments. #TheSeaStrivers\r\n#NEMSULiangaCampus\r\n#SailingAndStrivingForTheTruth', '4th-nemsulti-presscon.jpg', 'Jeah Pajaron', 0, 'news', 1, '2025-02-04 09:03:14', '2025-02-04 17:03:14', '2025-02-04 17:03:14'),
('59ae9f31-0a0f-11ef-9740-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐫𝐞𝐜𝐞𝐢𝐯𝐞𝐬 𝐭𝐡𝐞 𝐂𝐞𝐫𝐭𝐢𝐟𝐢𝐞𝐝 𝐌𝐨𝐬𝐭 𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐥𝐞 𝐚𝐧𝐝 𝐋𝐢𝐯𝐞𝐚𝐛𝐥𝐞 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐲 𝐢𝐧 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞𝐬 𝐀𝐰𝐚𝐫𝐝', 'MOSLIV-Awards-2024', 'The North Eastern Mindanao State University recently received the award for Certified Most Sustainable and Liveable University in the Philippines by Nation Builders and MOSLIV Awards 2024, Sustainability Standards Inc. held at the Okada Manila Grand Ballroom on May 3, 2024. ', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University recently received the award for Certified Most Sustainable and Liveable University in the Philippines by Nation Builders and MOSLIV Awards 2024, Sustainability Standards Inc. held at the Okada Manila Grand Ballroom on May 3, 2024. \r\n<br><br>\r\nThis year\'s awarding ceremony theme, Patience beyond Power, Vigilance, and Leadership, highlights the qualities essential for building sustainable and liveable communities. NEMSU\'s commitment to these principles has set it apart as a beacon of excellence in higher education.\r\n<br><br>\r\nPresident Nemesio G. Loayon, accompanied by Executive Assistant Dr. Mick Mars P. Silvano, accepted the esteemed recognition, which included a medallion, plaque, wall marker, and book.\r\n<br><br>\r\nReceiving the Certified Most Sustainable and Liveable University award is a testament to NEMSU\'s ongoing efforts to create a thriving and inclusive environment for its students, faculty, and surrounding communities\r\n<br/>', 'MOSLIV-Awards-2024.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-04 16:07:19', '2024-05-04 16:07:19', '2024-05-04 16:07:19'),
('59dbae9c-0929-11ef-9740-a233a240566f', '𝐌𝐞𝐦𝐨𝐫𝐚𝐧𝐝𝐮𝐦 𝐨𝐟 𝐀𝐠𝐫𝐞𝐞𝐦𝐞𝐧𝐭 (𝐌𝐎𝐀) 𝐒𝐢𝐠𝐧𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲', 'MOA-NEMSU-UP', '𝐌𝐞𝐦𝐨𝐫𝐚𝐧𝐝𝐮𝐦 𝐨𝐟 𝐀𝐠𝐫𝐞𝐞𝐦𝐞𝐧𝐭 (𝐌𝐎𝐀) 𝐒𝐢𝐠𝐧𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲 between the Commission on Higher Education (CHED), University of the Philippines - Los Baños, and North Eastern Mindanao State University (NEMSU) Project ExcelLEArate: A Review and Strategy Program to Empower Students for Licensure Examination for Agriculturists (A Component of Access with Success: Paglaum kag Pagdaug).', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images//2024/MOA-NEMSU-UP/moa-nemsu-and-up-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/MOA-NEMSU-UP/moa-nemsu-and-up-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images//2024/MOA-NEMSU-UP/moa-nemsu-and-up-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images//2024/MOA-NEMSU-UP/moa-nemsu-and-up-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images//2024/MOA-NEMSU-UP/moa-nemsu-and-up-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images//2024/MOA-NEMSU-UP/moa-nemsu-and-up-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝐌𝐞𝐦𝐨𝐫𝐚𝐧𝐝𝐮𝐦 𝐨𝐟 𝐀𝐠𝐫𝐞𝐞𝐦𝐞𝐧𝐭 (𝐌𝐎𝐀) 𝐒𝐢𝐠𝐧𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲 between the Commission on Higher Education (CHED), University of the Philippines - Los Baños, and North Eastern Mindanao State University (NEMSU) Project ExcelLEArate: A Review and Strategy Program to Empower Students for Licensure Examination for Agriculturists (A Component of Access with Success: Paglaum kag Pagdaug).\r\n<br><br>\r\nNEMSU President Nemesio G. Loayon is joined by San Miguel Campus OIC Director Dr. Florife O. Urbiztondo and Executive Assistant Dr. Mick Mars P. Silvano. Signing with Pres. Loayon are CHED Chairperson Popoy De Vera, UP President Atty. Angelo Jimenez, and Chancellor Dr. Jose Camacho Jr.\r\nNEMSU expressed gratitude for this project through tribal leis and native mugs.\r\nMay 3, 2024; 2:00 PM at CHED Auditorium, Diliman, Quezon City.\r\n<br/>', 'moa-nemsu-and-up-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2024-05-03 14:27:01', '2024-05-03 14:27:01', '2024-05-03 14:27:01'),
('5a192be3-51cf-11ee-b55e-a233a240566f', 'Amidst cheers and applause, athletes from across the State Universities and Colleges (SUCs)', 'masts-2023', 'Dr. Nelson Cabral, president of MASTS and Zamboanga Peninsula Polytechnic State University', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/masts-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nAmidst cheers and applause, athletes from across the State Universities and Colleges (SUCs) in Mindanao gathered to showcase their skills at the Opening Ceremony of the 2023 MASTS Games at the Provincial Sports Complex in Amas, Kidapawan City. The energy was palpable as the sports competition kicked off, promising an exciting and memorable event for all.<br><br>\r\nDr. Nelson Cabral, president of MASTS and Zamboanga Peninsula Polytechnic State University, declared the official opening of the 2023 MASTS Games- Sports Competition.<br><br>\r\nThe opening ceremony was also graced by the representative of Sen. Sonny Angara, Hon. Comm. Jo Mark M. Libre, Governor Lala, representatives of the 3 congressional districts of Cotabato, some mayors, SUC Presidents, coaches, officiating officials, athletes, among others.<br><br>\r\nThe opening ceremony was held this afternoon at 4:00. Despite the rainy weather, the ceremony continued.<br><br>\r\nThe MASTS Games - Sports Competition is conducted to promote physical fitness, sportsmanship, and healthy competition among the athletes from different regions in Mindanao. It serves as a platform for athletes to showcase their skills and compete at the highest level, while also fostering camaraderie and goodwill among participants from diverse backgrounds. Additionally, the games aim to raise awareness about the importance of sports and physical activity in leading a healthy and fulfilling life.<br><br>\r\nThis Sports Competition is being conducted with a series of athletic events and competitions in various categories such as track and field, swimming, basketball, volleyball, and others. The competitions are held at the Provincial Sports Complex in Amas, Kidapawan City, Cotabato City State Polytechnic College, Cotabato Foundation College of Science and Technology, along with other identified venues in the Municipality of Arakan, with athletes from different regions competing against each other. The rules and regulations of the games are strictly enforced to ensure a fair and level playing field for all athletes. The event is being organized by the MASTS (Mindanao Association of State Tertiary Schools, Inc.), in collaboration with local sports organizations and government bodies, to ensure a smooth and successful event.\r\n\r\n\r\n', 'masts-00.jpg', 'Public Information Office', NULL, 'news', 17, '2023-09-10 21:33:11', '2023-09-10 21:33:11', '2023-09-10 21:33:11'),
('5c7496d9-91e2-11f0-a6c6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔-𝐓𝐂 𝐭𝐨𝐩𝐬 𝐇𝐮𝐦𝐚𝐧 𝐑𝐞𝐬𝐨𝐮𝐫𝐜𝐞 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧', '𝐍𝐄𝐌𝐒𝐔-𝐓𝐂-𝐭𝐨𝐩𝐬-𝐇𝐮𝐦𝐚𝐧-𝐑𝐞𝐬𝐨𝐮𝐫𝐜𝐞-𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧', 'The North Eastern Mindanao State University–Tagbina Campus was recognized as a Top Performing School after achieving a 100% passing rate in the August 2025 Certified Human Resource Associate (CHRA)™ Assessment Examination.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University–Tagbina Campus was recognized as a Top Performing School after achieving a 100% passing rate in the August 2025 Certified Human Resource Associate (CHRA)™ Assessment Examination.\r\n\r\n<br/><br/>\r\nWith the examination’s overall passing rate of 81.86%, NEMSU-TC managed to surpass the standard through its two Human Resource Management (HRM) graduates, both first-time takers.\r\n<br/><br/>\r\nThe institution is among Batch 62’s 117 acknowledged schools that performed higher than the national average rating, with at least two first-time examinees.\r\n<br/><br/>\r\nThe Human Resource Educators Association of the Philippines, Inc. (HREAP) administered the Online Assessment Examination on August 23 and 24 for the Institutional and National batches, respectively.', '𝐍𝐄𝐌𝐒𝐔-𝐓𝐂-𝐭𝐨𝐩𝐬-𝐇𝐮𝐦𝐚𝐧-𝐑𝐞𝐬𝐨𝐮𝐫𝐜𝐞-𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧.jpg', ' Cherra Mae Mangguilimutan', 0, 'news', 1, '2025-09-05 11:14:10', NULL, NULL),
('5d952226-47d9-11ee-b55e-a233a240566f', 'ML Esport Champion-(W)', 'local-masts-MLBB1', '<p><span style=\"font-size:11.0pt\">Samahang Tagbina itinaob ang kupunang Lianga sa kategoryang babae ng MLBB Final Tournament.</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">Samahang Tagbina itinaob ang kupunang Lianga sa kategoryang babae ng MLBB Final Tournament.<br><br>\r\nNEMSU Tagbina Esports (NTE) namayagpag sa Land of the Dawn matapos kumamada ng 2 - 0 na puntos (Best of 3 Games) laban sa hukbong Lianga. \r\n<br><br>\r\n\r\n#TheVanguardPublication\r\n#LocalMASTS2023\r\n</span></span></p>', 'van-ML-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-31 16:40:13', '2023-08-31 16:40:13', '2023-08-31 16:40:13'),
('5e4a9f94-e4f1-11ef-8bc4-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐇𝐨𝐥𝐝𝐬 𝐇𝐲𝐛𝐫𝐢𝐝 𝐌𝐞𝐞𝐭𝐢𝐧𝐠 𝐰𝐢𝐭𝐡 𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥 𝐐𝐮𝐚𝐥𝐢𝐭𝐲 𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭 𝐓𝐞𝐚𝐦 𝐌𝐞𝐦𝐛𝐞𝐫𝐬', '𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦', 'Tandag City — The North Eastern Mindanao State University (NEMSU) convened a hybrid meeting with members of the Regional Quality Assessment Team (RQAT) on January 31, 2025. The meeting, led by the University President Dr. Nemesio G. Loayon, aimed to discuss key updates and initiatives for maintaining and improving the institution’s academic standards and operations.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nTandag City — The North Eastern Mindanao State University (NEMSU) convened a hybrid meeting with members of the Regional Quality Assessment Team (RQAT) on January 31, 2025. The meeting, led by the University President Dr. Nemesio G. Loayon, aimed to discuss key updates and initiatives for maintaining and improving the institution’s academic standards and operations.\r\n<br/><br/>\r\nMembers from the Tandag Campus gathered in person at the Board Room of the Administration Building, while participants from other campuses joined via Zoom. The University emphasized the importance of attendance, highlighting the collective effort required to uphold academic quality across all NEMSU campuses.\r\n<br/><br/>\r\nThe hybrid setup allowed the RQAT members to collaborate seamlessly despite geographical differences, ensuring that critical matters regarding educational assessment and quality assurance were effectively addressed.\r\n<br/><br/>\r\nThis meeting marks another step in NEMSU’s commitment to fostering a culture of academic excellence and innovation through continuous engagement and quality evaluation.', '𝐌𝐞𝐞𝐭𝐢𝐧𝐠-𝐰𝐢𝐭𝐡-𝐑𝐞𝐠𝐢𝐨𝐧𝐚𝐥-𝐐𝐮𝐚𝐥𝐢𝐭𝐲-𝐀𝐬𝐬𝐞𝐬𝐬𝐦𝐞𝐧𝐭-𝐓𝐞𝐚𝐦.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-01 09:07:44', '2025-02-01 09:07:44', '2025-02-01 09:07:44'),
('60aa641d-9df7-11ee-8f14-a233a240566f', 'NEMSUan Debater breaks in Nigeria-based Tournament', 'NEMSUan-Debater-2023', 'Christian Hope Deligero, a BA-English sophomore student and a current NEMSU Debate Guild trainee, made waves in the Nigeria National Novice Tournament, bagging the 4th Best Speaker Award and ending his stellar run as a quarter finalist.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nChristian Hope Deligero, a BA-English sophomore student and a current NEMSU Debate Guild trainee, made waves in the Nigeria National Novice Tournament, bagging the 4th Best Speaker Award and ending his stellar run as a quarter finalist.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nChristian Hope Deligero, a BA-English sophomore student and a current NEMSU Debate Guild trainee, made waves in the Nigeria National Novice Tournament, bagging the 4th Best Speaker Award and ending his stellar run as a quarter finalist.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nHosted by the University of Ilorin Debate Club via Discord from December 15-17, 2023, the online tournament posed another layer of challenge as the difference in timezones meant that the debate rounds were held until 3 am (Philippine standard time).\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNevertheless, Deligero persisted with his composite partner from the Caraga State University, Clivann Climaco, whom he considers was one of the reasons for their shared victory.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n\"Personally, if it were somebody else, I have partnered with, I would never qualify for the quarterfinals. Our synergy is so complementary,\" Deligero shared in a Facebook post.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nFurthermore, he expressed his gratitude to the NEMSU Debate Guild, along with the people who contributed to his success in his introduction to the debate circuit.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n\"I was even doubting my skills if it were enough for me to break ba. Pero BIG thanks to the persons who contributed to my growth,\" he added.\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThis victory marks Deligero\'s first ever breakthrough in a debate tournament, and the fact that this was his first time makes the win more commendable.\r\n<br>', 'debate_guild_poster.jpg', 'Public Information Office', 0, 'news', 1, '2023-12-18 16:33:11', '2023-12-18 16:33:11', '2023-12-18 16:33:11'),
('6524e67c-47ab-11ee-b55e-a233a240566f', 'The NEMSU-LC Karatedo', 'local-masts-karatedo', '<p><span style=\"font-size:11.0pt\">𝗟𝗢𝗖𝗔𝗟 𝗠𝗔𝗦𝗧𝗦 𝗨𝗣𝗗𝗔𝗧𝗘: The NEMSU-LC Karatedo team had a valiant fight</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝗟𝗢𝗖𝗔𝗟 𝗠𝗔𝗦𝗧𝗦 𝗨𝗣𝗗𝗔𝗧𝗘: The NEMSU-LC Karatedo team had a valiant fight, hauling eight golds, seven silvers, and one bronze in this year\'s local MASTS held at NEMSU-Main Campus, Tandag City, Surigao del Sur, today.\r\n<br>\r\nReport by Lee Van Cleff M. Labsan <br>\r\nPhoto by Sean Capungan\r\n<br><br>\r\n#2023LocalMASTS<br>\r\n#TheSeaStrivers<br>\r\n#SailingAndStrivingForTheTruth', 'sea-karedo-00.jpg', 'The Sea Strivers Publication', 32, 'news', 1, '2023-08-30 16:33:11', '2023-08-30 16:33:11', '2023-08-30 16:33:11'),
('65d81757-8353-11ee-bea4-a233a240566f', '𝗡𝗘𝗪𝗦: 𝖯𝗂𝗍𝖼𝗁-𝖯𝖾𝗋𝖿𝖾𝖼𝗍 𝖵𝗂𝖼𝗍𝗈𝗋𝗒\r\nDCS pitching team enters top 5', 'Tagbina-Pitching-top5', 'Pitching their way to HEALTHCON \'23, NEMSU-TC\'s BSCS team achieved a breakthrough by securing a position among the elite top 5 in the recent Health Technology Ideation Pitching.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nPitching their way to HEALTHCON \'23, NEMSU-TC\'s BSCS team achieved a breakthrough by securing a position among  the elite top 5 in the recent Health Technology Ideation Pitching.\r\n<br>\r\nLed by Maryvelle Almirol and supported by Maria Fatima Baja, Queenie Matin-ao, and Ruby Janiola, the team presented their health technology innovation titled \'EyeConsulta\' at the 6th Caraga Health R&D Convention.\r\n<br>\r\nOut of 14 entries, only five victors were recognized as the top 5 finalists at Caraga State University, Butuan City.\r\n<br>\r\nAlongside certificates, the group was awarded a cash prize of five thousand for their \'outstanding\' performance in the competition.\r\nAnother DCS team is now gearing up for the grander stage in Samal on November 20 to 25.\r\n<br>\r\n🖊️: Cherra Manguilimutan\r\n#TheBlazePublication\r\n<br>\r\n', 'dcs-00.jpg', 'The Blaze - NEMSU Tagbina', 32, 'news', 1, '2023-11-10 21:25:11', '2023-11-10 21:25:11', '2023-11-10 21:25:11'),
('670c50a0-47db-11ee-b55e-a233a240566f', 'MASTS in Chess Tourney', 'local-masts-Chess', '<p><span style=\"font-size:11.0pt\">Securing an overall score of 18-7 in rounds 1 to 5, NEMSU-Main’s prime players ruled its kings against Cantilan’s contingents in the Chess tournament, Women’s Division, ripping 4 tickets to Cotabato.</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝑻𝒂𝒏𝒅𝒂𝒈 𝒃𝒍𝒐𝒄𝒌𝒔 𝑪𝒂𝒏𝒕𝒊𝒍𝒂𝒏’𝒔 𝑻𝒊𝒄𝒌𝒆𝒕 𝒕𝒐 𝑴𝑨𝑺𝑻𝑺 𝒊𝒏 𝑪𝒉𝒆𝒔𝒔 𝑻𝒐𝒖𝒓𝒏𝒆𝒚<br><br>\r\nSecuring an overall score of 18-7 in rounds 1 to 5, NEMSU-Main’s prime players ruled its kings against Cantilan’s contingents in the Chess tournament, Women’s Division, ripping 4 tickets to Cotabato.<br><br>\r\nTandag’s team managed to establish a promising lead during the first round with 2 wins, 2 draws, and 1 loss, gaining more momentum in the next with 4 wins and 1 loss.<br><br>\r\nAfter reaching the team’s peak in round 4 where they ruled all the matches, things took an 80-degree turn when they lost three times in the succeeding round.\r\nNevertheless, the NEMSU-Tandag Chess team maintained their stronghold in the competition, sealing 4 of 5 slots in the upcoming MASTS.<br><br>\r\nLeading the pack was Divine Jea Manzano with 4.5 accumulated points. She stated that her primary focus during the match was simply to win and learn. <br><br>\r\n\"Actually, proud ako sa Ginoo kay siya sab ang mitugot sa ako kadaugan,” Manzano added.<br><br>\r\nWritten by Ime Cadavos<br>\r\nPhotos by Roger Bagood and Jhoana Marie Cabadonga<br>\r\n#TheVanguardPublication<br>\r\n#LocalMASTS2023\r\n</span></span></p>', 'van-chess-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-30 17:40:13', '2023-08-30 17:40:13', '2023-08-30 17:40:13'),
('681e0cad-86e6-11f0-a6c6-a233a240566f', '𝐓𝐇𝐄 𝟒𝐓𝐇 𝐍𝐄𝐌𝐒𝐔 𝐃𝐀𝐘', '𝐓𝐇𝐄-𝟒𝐓𝐇-𝐍𝐄𝐌𝐒𝐔-𝐃𝐀𝐘', '𝐓𝐇𝐄 𝟒𝐓𝐇 𝐍𝐄𝐌𝐒𝐔 𝐃𝐀𝐘 | North Eastern Mindanao State University (NEMSU) has grown from its humble beginnings to become a thriving multicampus institution that is influencing the direction of education in the region. ', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝐓𝐇𝐄 𝟒𝐓𝐇 𝐍𝐄𝐌𝐒𝐔 𝐃𝐀𝐘 | North Eastern Mindanao State University (NEMSU) has grown from its humble beginnings to become a thriving multicampus institution that is influencing the direction of education in the region. With campuses located in Tandag, Cantilan, Tagbina, Lianga, San Miguel, Cagwait, and Bislig, NEMSU continues to grow in influence and impact—serving diverse communities with a steadfast commitment to academic excellence and social transformation.\r\n<br/>\r\nBehind this progress lies an important moment in history: the enactment of Republic Act No. 11584 on July 30, 2021, which marked the transformation of Surigao del Sur State University into what we now know as North Eastern Mindanao State University. This legislative move was more than institutional rebranding—it was a declaration of purpose, a signal of new beginnings rooted in a proud legacy.\r\n<br/>\r\nAs the university celebrates its fourth founding anniversary, it proudly carries the theme “𝑨𝒅𝒗𝒂𝒏𝒄𝒊𝒏𝒈 𝑻𝒓𝒂𝒏𝒔𝒇𝒐𝒓𝒎𝒂𝒕𝒊𝒗𝒆 𝑬𝒅𝒖𝒄𝒂𝒕𝒊𝒐𝒏, 𝑬𝒎𝒑𝒐𝒘𝒆𝒓𝒊𝒏𝒈 𝑪𝒐𝒎𝒎𝒖𝒏𝒊𝒕𝒊𝒆𝒔 & 𝑺𝒖𝒔𝒕𝒂𝒊𝒏𝒊𝒏𝒈 𝑬𝒙𝒄𝒆𝒍𝒍𝒆𝒏𝒄𝒆 𝒇𝒐𝒓 𝒂 𝑭𝒖𝒕𝒖𝒓𝒆-𝑹𝒆𝒂𝒅𝒚 𝑵𝒂𝒕𝒊𝒐𝒏.” This theme encapsulates NEMSU’s commitment to driving innovation in education, fostering inclusive community development, and maintaining high standards that prepare learners for the challenges of tomorrow.\r\n<br/>\r\nNEMSU stands not only as an institution of learning but as a symbol of resilience, renewal, and forward-thinking leadership. Its journey continues, with every milestone reinforcing its promise to empower individuals and uplift communities across Northeastern Mindanao and beyond.\r\nPadayon sa pag-ALPAS, NEMSU!\r\n<br/>', '4th-nemsu.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-30 11:43:11', NULL, NULL),
('6881a0d2-392e-11ef-9551-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐛𝐫𝐞𝐚𝐤𝐬 𝐠𝐫𝐨𝐮𝐧𝐝 𝐟𝐨𝐫 𝐂𝐨𝐥𝐥𝐞𝐠𝐞 𝐨𝐟 𝐌𝐞𝐝𝐢𝐜𝐢𝐧𝐞, 𝐢𝐧𝐤𝐬 𝐩𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩 𝐰𝐢𝐭𝐡 𝐚𝐠𝐞𝐧𝐜𝐢𝐞𝐬', 'Ground-Breaking-College-of-Medicine', '𝐉𝐮𝐥𝐲 𝟑, 𝟐𝟎𝟐𝟒 – North Eastern Mindanao State University (NEMSU) has started building its College of Medicine and signed a partnership with Adela Serra Ty Memorial Medical Center (ASTMMC), complementary to the offering of the College of Medicine.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n\r\n𝐉𝐮𝐥𝐲 𝟑, 𝟐𝟎𝟐𝟒 – North Eastern Mindanao State University (NEMSU) has started building its College of Medicine and signed a partnership with Adela Serra Ty Memorial Medical Center (ASTMMC), complementary to the offering of the College of Medicine.\r\nNEMSU will construct the Php 95 million six-story medical building (Phase 1) to offer premier healthcare education and produce top-notch healthcare practitioners from the region. \r\n<br><br>\r\nCongressman Romeo S. Momo, Sr., the primary sponsor of House Bill No. 8825, establishing the NEMSU College of Medicine, has secured the necessary funding for this project — the Department of Public Works and Highways - 1st District Engineering Office, led by Engr. Ruel B. Bantugan facilitated the funding.\r\nNEMSU President Nemesio G. Loayon and ASTMMC Medical Center Chief Dr. Janice V. Pagaran-Alcordo signed an agreement declaring ASTMMC as the base hospital for the new program. This partnership ensures that medical students receive practical, hands-on training in real-world healthcare.\r\n<br><br>\r\nThe medical building will complement the premier healthcare education in Surigao del Sur and beyond. It aims to produce premier healthcare practitioners who are Surigaonon for the Surigaonon.\r\n<br><br>\r\nWith this initiative, students who do not have the financial resources to study in private institutions yet wish to attain a healthcare education will have the opportunity to study as the university strives to produce prospective doctors shaped by a curriculum tailored to address the community\'s needs in the status quo.\r\n<br><br>\r\nGovernor Alexander T. Pimentel and Dr. Fredrick Amihan of the Commission on Higher Education (CHED) expressed their support for the project, highlighting its potential to transform healthcare education and services in the province.\r\nThe College of Medicine is expected to open in the 2025 academic year and complete Phase 1 construction by June 2025. The next phase will be implemented in the future to ensure its full operation.\r\n</p>\r\n', 'Ground-Breaking-2024.jpg', 'Public Information Office', 0, 'news', 1, '2024-07-03 17:21:17', '2024-07-03 17:21:17', '2024-07-03 17:21:17'),
('699c718d-1fb1-11ee-816f-a233a240566f', '𝐄𝐲𝐞𝐬 𝐡𝐞𝐫𝐞, 𝐍𝐄𝐌𝐒𝐔𝐚𝐧𝐬!\r\nThe latest issue covering the Pre-Commencement and Commencement Exercises is now available. Grab a copy at The Vanguard office beside the Audio Visual Center.', 'covering-the-Pre-Commencement-Commencement-Exercises', '', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The latest issue covering the Pre-Commencement and Commencement Exercises is now available. Grab a copy at The Vanguard office beside the Audio Visual Center.</span></p>\r\n<br>\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Google drive: <a href=\"https://drive.google.com/drive/folders/13EJVsibJjKjgDVpbEFKeB7g-04Q_doW8?usp=sharing\" target=\"_blank\"><u>Files</u></a></span></p>\r\n\r\n', 'van-000.jpeg', 'The Vanguard Publication', NULL, 'news', 1, '2023-07-10 17:20:11', '2023-07-10 17:20:11', '2023-07-10 17:20:11'),
('6deb2b36-28cd-11ef-8173-a233a240566f', '𝐍𝐄𝐖𝐒 | 𝐍𝐄𝐌𝐒𝐔 𝐫𝐞𝐜𝐢𝐭𝐞𝐬 𝐁𝐚𝐠𝐨𝐧𝐠 𝐏𝐢𝐥𝐢𝐩𝐢𝐧𝐚𝐬 𝐇𝐲𝐦𝐧, 𝐏𝐥𝐞𝐝𝐠𝐞', 'Bagong-Pilipinas-Hymn-Pledge', 'NEMSU, through the Office of the University President, implemented its first recitation of the Bagong Pilipinas Hymn and Pledge, on June 10, 2024, during its flag-raising ceremony.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU, through the Office of the University President, implemented its first recitation of the Bagong Pilipinas Hymn and Pledge, on June 10, 2024, during its flag-raising ceremony.<br><br>\r\nNEMSU, as a government institution, included the recitation of the Bagong Pilipinas Hymn and Pledge. This follows the memorandum announced by the Presidential Communications Office on Sunday, signed by Executive Secretary Lucas Bersamin, that all government agencies and instrumentalities, including government-owned or controlled corporations and educational institutions, were ordered to include the recitation.<br><br>\r\nPresident Nemesio G. Loayon expressed the importance of understanding and memorizing its message to ensure all its government employees imbibe its principles.<br><br>\r\nThe university holds its flag-raising ceremony every Monday at 7:45 am.\r\n</p>\r\n', '650x600-Banner-Bagong-Pilipinas.png', 'Public Information Office', 0, 'news', 1, '2024-06-10 08:06:52', '2024-06-10 08:06:52', '2024-06-10 08:06:52'),
('71457879-4e4b-11ee-b55e-a233a240566f', 'Honoring Tradition and Celebration Excellence: BS Midwifery 2nd Pinning & Candle Lighting Ceremony', '2nd-Pinning-mid', 'The Bachelor of Science in Midwifery of North Eastern Mindanao State University - NEMSU celebrates its 2nd Pinning & Candle Lighting Ceremony. Attending the event are 1st District, Congressman Romeo S. Momo Sr., NEMSU Pres. Nemesio G. Loayon, CAS Dean, Dr. Romeo A. Patan, Guest Speaker - Dr. Reyna Marie Chua-Herrera, guests, faculty, staff and students. ', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2nd-Pinning-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe Bachelor of Science in Midwifery of North Eastern Mindanao State University - NEMSU celebrates its 2nd Pinning & Candle Lighting Ceremony. Attending the event are 1st District, Congressman Romeo S. Momo Sr., NEMSU Pres. Nemesio G. Loayon, CAS Dean, Dr. Romeo A. Patan, Guest Speaker - Dr. Reyna Marie Chua-Herrera, guests, faculty, staff and students. <br><br>\r\nAs these new graduates receive their pins and light their candles, they carry with them the legacy of midwifery and a commitment to providing exceptional care to expectant mothers and their families. <br><br>\r\nThe ceremony not only marks the end of their academic journey but also the beginning of their meaningful career as midwives, bringing light and hope to the world, one birth at a time.<br><br>\r\n<b>Congratulations</b>\r\n\r\n', '2nd-pinning-00.JPG', 'Public Information Office', NULL, 'news', 1, '2023-09-08 17:47:23', '2023-09-08 17:47:23', '2023-09-08 17:47:23'),
('725b66c1-4ee0-11ef-8071-a233a240566f', '𝗡𝗘𝗠𝗦𝗨 𝗵𝗼𝗹𝗱𝘀 𝗢𝗮𝘁𝗵 𝗧𝗮𝗸𝗶𝗻𝗴 𝗖𝗲𝗿𝗲𝗺𝗼𝗻𝘆 𝗳𝗼𝗿 𝗡𝗲𝘄𝗹𝘆 𝗥𝗲𝗰𝗹𝗮𝘀𝘀𝗶𝗳𝗶𝗲𝗱 𝗙𝗮𝗰𝘂𝗹𝘁𝘆', 'reclassified-2024', 'After the video documentary viewing, reclassified faculty members across the university campuses take their oath at NEMSU gymnasium.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nAfter the video documentary viewing, reclassified faculty members across the university campuses take their oath at NEMSU gymnasium.<br><br>\r\nWith great joy and pride, Dr. Maria Lady Sol A. Suazo, Vice President for Academic Affairs, expressed her gratitude to the NEMSU academic community and stakeholders for the invaluable support amidst challenges in making the significant event possible. <br><br>\r\n\"Today, together we are gathered, united by our collective achievements and the recognition of our hard-earned efforts. This success would not have been possible without the assistance of the many individuals and teams who played the crucial role in our journey, and today is the day that we say thank you to them,\" the VPAA stated.<br><br>\r\nMeanwhile, after the lively acknowledgement of participants of Mr.  Roel T. Lim, JD, MPA, President Nemesio G. Loayon extends his congratulatory message and address of challenge to the distinguished faculty members from the seven campuses.  \r\n\"You are the pillars of our university and it is through your tireless efforts we continue to provide quality education, inspire our students, and push the boundaries of knowledge,\" Pres. Loayon affirmed.<br><br>\r\n As we celebrate our achievements, I want to challenge each of you in line with our theme, we must strive to be transformative, this means continuously seeking innovative teaching methods, embracing new technologies, and fostering an environment where creativity and critical thinking can thrive,\" the president added.<br><br>\r\nThe Oath Taking Ceremony is one of the highlights in the celebration of the 3rd University Day. <br><br>\r\nReport by Gerwin Espinedo<br>\r\nPhotos by Clint Jude Carballo\r\n\r\n<br><br>\r\n#TheVanguardPublication\r\n', 'reclassified-00.jpg', 'The Vanguard Publication', 0, 'news', 1, '2024-07-30 16:58:23', '2024-07-30 16:58:23', '2024-07-30 16:58:23'),
('72f980d8-af80-11ee-9af6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐄𝐍𝐑𝐎𝐋𝐋𝐌𝐄𝐍𝐓 𝐇𝐎𝐓𝐋𝐈𝐍𝐄𝐒', 'Hotlines-2024', 'Got questions about enrollment? We\'ve got answers!', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/hotlines-00.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/hotlines-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/hotlines-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/hotlines-03.jpg\" /></div>\r\n</div>\r\n<br>\r\nGot questions about enrollment? We\'ve got answers!\r\nDial our hotline, and let our friendly team guide you through the process. Your academic adventure awaits!\r\n<br>\r\n#NorthEasternMindanaoStateUniversity<br>\r\n#nemsuenrollment<br>\r\n#nemsubeginnings<br>\r\n#nemsujourney', 'hotlines-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-10 14:15:11', '2024-01-10 14:15:11', '2024-01-10 14:15:11'),
('73249eaf-6dea-11f0-ae5d-a233a240566f', '𝐏𝐥𝐞𝐧𝐚𝐫𝐲 𝐭𝐚𝐥𝐤 𝐨𝐧 𝐭𝐡𝐞 𝐭𝐨𝐩𝐢𝐜 “𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐢𝐥𝐢𝐭𝐲 𝐚𝐧𝐝 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜 𝐌𝐞𝐜𝐡𝐚𝐧𝐢𝐬𝐦𝐬 𝐨𝐟 𝐍𝐄𝐌𝐒𝐔 𝐂𝐨𝐦𝐦𝐮𝐧𝐢𝐭𝐲 𝐄𝐱𝐭𝐞𝐧𝐬𝐢𝐨𝐧 𝐏𝐫𝐨𝐠𝐫𝐚𝐦𝐬”:', '𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐢𝐥𝐢𝐭𝐲-𝐚𝐧𝐝-𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜-𝐌𝐞𝐜𝐡𝐚𝐧𝐢𝐬𝐦𝐬', 'In a compelling plenary session, the President of North Eastern Mindanao State University (NEMSU) Dr. Loayon delivered an inspiring talk on the “Sustainability and Strategic Mechanisms of NEMSU Community Extension Programs.”', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐢𝐥𝐢𝐭𝐲 𝐚𝐧𝐝 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜 𝐌𝐞𝐜𝐡𝐚𝐧𝐢𝐬𝐦𝐬 𝐨𝐟 𝐍𝐄𝐌𝐒𝐔-1.jpg\" /></div>\r\n\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nIn a compelling plenary session, the President of North Eastern Mindanao State University (NEMSU) Dr. Loayon delivered an inspiring talk on the “Sustainability and Strategic Mechanisms of NEMSU Community Extension Programs.” He shared the university’s dynamic approach to community involvement, focusing on how NEMSU has successfully cultivated a strong culture of engagement among faculty members.\r\n\r\n<br/><br/>\r\nCentral to his talk were the university’s four strategic pillars that serve as the foundation of their extension initiatives: Food Security, Environmental Conservation Projects, Literacy and Educational Support, and Professional and Digital Empowerment. These pillars guide the university in aligning its extension activities with the real and pressing needs of communities.\r\n<br/><br/>\r\nThe President emphasized how NEMSU motivates its faculty by embedding extension work into academic responsibilities, providing support for innovative projects, and creating opportunities for interdisciplinary collaboration. He proudly showcased some of the tangible outputs of their programs—such as the unique and community-rooted Danggit Ice Cream and Banana Loaf, which highlight local resources and promote sustainable livelihood.\r\n<br/><br/>\r\nThis plenary talk not only underscored the sustainability of NEMSU’s extension efforts but also served as a model for how academic institutions can be agents of transformation through inclusive and strategic community engagement.\r\n<br/><br/>\r\n', '𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐢𝐥𝐢𝐭𝐲 𝐚𝐧𝐝 𝐒𝐭𝐫𝐚𝐭𝐞𝐠𝐢𝐜 𝐌𝐞𝐜𝐡𝐚𝐧𝐢𝐬𝐦𝐬 𝐨𝐟 𝐍𝐄𝐌𝐒𝐔.jpg', 'Public Information Office', 0, 'news', 1, '2025-06-11 16:38:05', NULL, NULL);
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('73517dbf-8eda-11ef-bdca-a233a240566f', '[𝐈𝐂𝐘𝐌𝐈] 𝐍𝐄𝐌𝐒𝐔 𝐇𝐨𝐥𝐝𝐬 𝐋𝐞𝐚𝐝𝐞𝐫𝐬𝐡𝐢𝐩 𝐚𝐧𝐝 𝐆𝐞𝐧𝐝𝐞𝐫 𝐃𝐞𝐯𝐞𝐥𝐨𝐩𝐦𝐞𝐧𝐭 𝐓𝐫𝐚𝐢𝐧𝐢𝐧𝐠, 𝐂𝐨𝐧𝐯𝐞𝐧𝐞𝐬 𝐊𝐞𝐲 𝐎𝐟𝐟𝐢𝐜𝐢𝐚𝐥𝐬 𝐟𝐨𝐫 𝐌𝐚𝐧𝐚𝐠𝐞𝐦𝐞𝐧𝐭 𝐂𝐨𝐦𝐦𝐢𝐭𝐭𝐞𝐞 𝐌𝐞𝐞𝐭𝐢𝐧𝐠', 'NEMSU-Holds-Leadership-and-GAD-Training', 'The North Eastern Mindanao State University (NEMSU) held a two-day Gender and Development, Leadership Development Training, followed by a Management Committee Meeting, at Os Landing Resort, on October 10-11, 2024. The event aimed to strengthen leadership capabilities and enhance management strategies within the university.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University (NEMSU) held a two-day Gender and Development, Leadership Development Training, followed by a Management Committee Meeting, at Os Landing Resort, on October 10-11, 2024. The event aimed to strengthen leadership capabilities and enhance management strategies within the university.\r\n<br><br>\r\nThe first day, October 10, focused on Gender and Development (GAD) and Leadership Training, facilitated by Dr. Harold Pareja. The training session provided valuable insights into gender sensitivity, inclusion, and leadership approaches that align with NEMSU\'s commitment to gender equity. Dr. Pareja emphasized the importance of creating an inclusive academic environment and highlighted strategies for empowering both men and women in leadership roles.\r\n<br><br>\r\nDay two, October 11, was dedicated to the Management Committee Meeting. Presided over by NEMSU President, Dr. Nemesio G. Loayon, the meeting gathered key officials and unit heads from various campuses to review ongoing university initiatives, discuss operational strategies, and plan for the upcoming academic term. The session provided an opportunity in presenting the different proposals to further enhance service delivery for students and faculty alike.', 'GAD-Banner-00.jpg', 'Public Information office', 0, 'news', 1, '2024-10-14 12:56:49', '2024-10-14 12:56:49', '2024-10-14 12:56:49'),
('74376e3d-28d1-11ef-8173-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐣𝐨𝐢𝐧𝐬 𝐭𝐡𝐞 𝟏𝟐𝟔𝐭𝐡 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞 𝐈𝐧𝐝𝐞𝐩𝐞𝐧𝐝𝐞𝐧𝐜𝐞 𝐃𝐚𝐲 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐢𝐨𝐧', '126th-Philippine-Independence-Day', 'Today, the officials and personnel of North Eastern Mindanao State University (NEMSU) Main Campus joined the nationwide celebration of the 126th Philippine Independence Day at the Old Town Hall of Tandag City, Surigao del Sur.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nToday, the officials and personnel of North Eastern Mindanao State University (NEMSU) Main Campus joined the nationwide celebration of the 126th Philippine Independence Day at the Old Town Hall of Tandag City, Surigao del Sur. NEMSU President Nemesio G. Loayon led the university\'s participation, accompanied by other key officials, faculty and staff. The Malisto Dance Troupe of NEMSU Main and other schools also offered dance presentations showcasing the rich culture of the nation. <br><br>\r\nThe event was graced by the presence of City and Provincial Officials, representatives from various government agencies, and education sectors.<br><br>\r\nNEMSU’s participation displays its commitment to nurturing a deep sense of national identity and civic responsibility among its students and stakeholders. This national event participated by NEMSU reinforces its dedication to not only academic excellence but also to empowering a community that values and upholds the ideals of freedom, democracy, and unity.', '650x600-Indepence-Day-24.png', 'Public Information Office', 0, 'news', 1, '2024-06-12 10:34:54', '2024-06-12 10:34:54', '2024-06-12 10:34:54'),
('74a41d76-52f2-11ef-8071-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐚𝐧𝐝 𝐄𝐚𝐬𝐭 𝐖𝐞𝐬𝐭 𝐑𝐮𝐫𝐚𝐥 𝐁𝐚𝐧𝐤, 𝐈𝐧𝐜. 𝐅𝐨𝐫𝐠𝐞 𝐏𝐚𝐫𝐭𝐧𝐞𝐫𝐬𝐡𝐢𝐩;\r\n𝐈𝐧𝐤𝐞𝐝 𝐌𝐎𝐀', 'MOA-East-West-Rural-Bank', 'Pres. Nemesio G. Loayon and East West Rural Bank, Inc. formalized their collaboration through a Memorandum of Agreement (MOA) Signing at the Office of the University President.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nPres. Nemesio G. Loayon and East West Rural Bank, Inc. formalized their collaboration through a Memorandum of Agreement (MOA) Signing at the Office of the University President. This partnership aims to strengthen financial services and opportunities for the NEMSU community.\r\n<br/>', 'MOA-East-west-bank.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2024-08-02 15:17:35', '2024-08-02 15:17:35', '2024-08-02 15:17:35'),
('760da959-b8ca-11ee-aa14-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐰𝐞𝐥𝐜𝐨𝐦𝐞𝐬 𝟗𝟎 𝐧𝐞𝐰 𝐦𝐞𝐦𝐛𝐞𝐫𝐬 𝐰𝐢𝐭𝐡 𝐎𝐚𝐭𝐡-𝐓𝐚𝐤𝐢𝐧𝐠 𝐂𝐞𝐫𝐞𝐦𝐨𝐧𝐲', 'Oath-90new-2024', 'Ninety newly appointed NEMSU personnel officially took their oath of office during the Oath-Taking Ceremony and Orientation on Civil Service Laws and University Policies at the Gold Bar Hotel and Restaurant on January 18, 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/oath-taking-2024-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNinety newly appointed NEMSU personnel officially took their oath of office during the Oath-Taking Ceremony and Orientation on Civil Service Laws and University Policies at the Gold Bar Hotel and Restaurant on January 18, 2024.\r\n<br>\r\nThis diverse cohort, consisting of 11 dedicated members from the teaching workforce and 79 accomplished administrative personnel, hailing from NEMSU\'s seven campuses, pledged their unwavering commitment to contribute to the university\'s growth and excellence with President Nemesio G. Loayon as the administering officer.\r\n<br>\r\n“We are all public servants. Therefore, we must exercise our duties to the best of our abilities for the university… When we work, we give ourselves. We give ourselves so that others will live.” President Loayon exclaimed highlighting the value of extending our time and going the extra mile for the service of the NEMSU academic community.\r\n<br>\r\nThis aligns with the Department of Budget and Management’s National Budget Circular No. 589: The Revised Organization and Staffing Standards for SUCs – Phase 1. The ceremony not only marked a symbolic initiation into their roles but also underscored the unity and collective dedication of the recruits to the values and principles upheld by NEMSU.\r\n<br>\r\nIn addition, NEMSU through its Human Resource Management Office, implemented a part of its onboarding program by providing an orientation on Civil Service Laws and laying down the salient points of the university policies. Such discussions revolved around the university’s organizational structure, administrative and academic matters, leave laws, ISO 9001 Awareness, IPCR and OPCR of faculty and staff, CODI and Sexual Harassment Law, and the grievance mechanism of the university.\r\n<br>\r\n“It takes brave men and women to recite the oath of office… You will not just become devoted civil servants, but also actual agents of change in your respective units.” Dr. Abundio C. Miralles, the Campus Director of NEMSU-Tandag, said as he formally opened the program instilling a strong sense of responsibility in the positions they have assumed.\r\n<br>\r\nAs these individuals embark on their respective roles, their induction stands as a testament to NEMSU\'s continuous efforts to strengthen its academic and administrative foundations. The university eagerly anticipates the positive impact and fresh perspectives these new members will bring to enrich the vibrant academic community. This event further solidifies NEMSU\'s commitment to fostering a dynamic and inclusive environment for both its students and staff.\r\n<br/>', 'oath-taking-2024-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-18 09:30:23', '2024-01-18 09:30:23', '2024-01-18 09:30:23'),
('76cffdf6-1f93-11ee-816f-a233a240566f', 'NEMSU - Bislig Campus 2nd University Commencement Exercises', 'Bislig-Campus-2nd-Commencement-Exercises', 'NEMSU President challenges newly-pronounced graduates to ace licensure examinations', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-03.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">NEMSU President challenges newly-pronounced graduates to ace licensure examinations\r\n<br><br>\r\nNEMSU President, Nemesio G. Loayon graced the NEMSU Bislig community with his presence, accompanied with a call for the graduates to be the next top notchers in the coming licensure examinations of their respective programs. \r\n<br><br>\r\n\"The main campus already produced board top notchers in the licensure examination for teachers. This time, we would challenge Bislig campus to produce top notchers for forestry and also in engineering programs,\" Loayon challenged the graduates.\r\n<br><br> \r\nNorth Eastern Mindanao State University had been awarded by the Professional Regulation Commission (PRC) as the Top 3 Best Engineering Programs in the Philippines. All the more challenge for the graduates to put in the effort and hustle.\r\n</span></p>\r\n<br><br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-06.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Commencement speaker introduces new formula to success\r\n<br><br>\r\nAs the graduates cap off their college journey, they have come in terms with various formulas along the way; Bernoulli equation, table of specifications, and the list could go on. For them to solve bigger problems in the equation of life, the commencement speaker, Lalaine May P. Ranes, Teacher III, DepEd, presents her version — the 5G formula.\r\n\r\n<br><br>\r\nThe 5G formula encapsulates; Goal (1G) — the driving force, Guts (2G) — the courage amid uncertainties, Grit (3G) — the undying perseverance and passion, Gratitude (4G) — the value of looking and giving back, and God (5G) — when all else fail, God never will.\r\n<br><br>\r\n\r\n\"Choose your network, be connected with the valuable 5G,\" Ranes stated. \r\nRanes also shared how she first perceived the expression, \"ana nalang\" as somewhat a showcase of mediocrity. However, a student made her realize that the expression stems on a deeper level of acceptance. Whatever college life throws at you, you have to carry on and fight for your dreams. Ana nalang!\r\n</span></p>\r\n<br><br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/bislig-09.jpg\" /></div>\r\n</div>\r\n<br><br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">NEMSU Bislig Class of 2023 sings Graduation Song and NEMSU Hymn\r\n<br><br>\r\n\r\nEmotions echo through different voices in one unifying melody of fulfillment — as the graduates pour their hearts out in singing the NEMSU Hymn, and their graduation song\r\n<br><br>\r\nA pitch perfect moment for everyone in the venue. \r\nIndeed, today, their lives begin.\r\n</span></p>\r\n<br><br>\r\n\r\n<p style=\"text-align:left\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\n\r\n#NEMSU2023 #GraduationDay #nemsucares #sculptingbetterlives\r\n\r\n</span></p>', 'bislig-00.jpg', 'The MAHARLIKAN', 32, 'news', 1, '2023-07-01 17:10:11', '2023-07-01 17:10:11', '2023-07-01 17:10:11'),
('77e56b39-4ee1-11ef-8071-a233a240566f', '𝐒𝐭𝐫𝐞𝐧𝐠𝐭𝐡𝐞𝐧𝐢𝐧𝐠 𝐋𝐞𝐠𝐚𝐥 𝐄𝐝𝐮𝐜𝐚𝐭𝐢𝐨𝐧: 𝐍𝐄𝐌𝐒𝐔 𝐂𝐨𝐥𝐥𝐞𝐠𝐞 𝐨𝐟 𝐋𝐚𝐰 𝐒𝐢𝐠𝐧𝐬 𝐌𝐎𝐀 𝐰𝐢𝐭𝐡 𝐃𝐎𝐉, 𝐃𝐄𝐍𝐑, 𝐏𝐒𝐖𝐃, 𝐂𝐇𝐑 & 𝐍𝐂𝐈𝐏', 'COL-MOA-DOJ-DENR-PSWD-CHR-NCIP-2024', 'Tandag City, July 26, 2024 - In a landmark event, the NEMSU College of Law entered into a Memorandum of Agreement (MOA) with Department of Justice, Department of Environment and Natural Resources, Provincial Social Welfare and Development, Commission on Human Rights and National Commission on Indigenous Peoples. The signing ceremony, held at the NEMSU Tandag campus, marks the beginning of a collaborative effort aimed at enhancing legal education and community engagement.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nTandag City, July 26, 2024 - In a landmark event, the NEMSU College of Law entered into a Memorandum of Agreement (MOA) with Department of Justice, Department of Environment and Natural Resources, Provincial Social Welfare and Development, Commission on Human Rights and National Commission on Indigenous Peoples. The signing ceremony, held at the NEMSU Tandag campus, marks the beginning of a collaborative effort aimed at enhancing legal education and community engagement.\r\nThe purpose of the MOA is to set forth the terms, conditions, scope of work, and responsibilities of the parties involved in their collaborations on the On-The-Job Training (OJT) Program. \r\n<br><br>\r\nThis program is designed to provide law students with practical experience in various legal settings, bridging the gap between academic knowledge and real-world legal practice. By participating in this initiative, students will gain valuable insights and hands-on experience, preparing them to serve their communities more effectively.\r\n<br><br>\r\nThe MOA signing marks a significant milestone in NEMSU\'s efforts to advance legal education and foster community engagement. It sets a precedent for future collaborations and serves as a model for other institutions seeking to integrate practical training and community service into their academic programs.\r\n\r\n', 'moa-law-partner-dialogue-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-07-26 19:05:47', '2024-07-26 19:05:47', '2024-07-26 19:05:47'),
('795f7922-3a3d-11ee-a66e-a233a240566f', '𝗪𝗘𝗔𝗥 𝗬𝗢𝗨𝗥 𝗖𝗢𝗟𝗢𝗥𝗦!', 'wear-your-colors-2023', NULL, '<p><img alt=\"\" src=\"/public_files/images/wear-2023.jpg\" class=\"img img-responsive\" /></p>\r\n\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nRepresent your COLLEGES by wearing your RECENT COLLEGE SHIRTS on our #NEMSUgdanTaNa Class Opening on August 14, 2023.\r\n<br/>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNote: If colored shirts aren\'t available, you may wear WHITE (refer to your College Officers announcements)\r\n<br/>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nCheck out your colors below!\r\n<br/>\r\n\r\n#NEMSUClassOpening2023 <br>\r\n#nemsutandag', NULL, 'University Student Government', NULL, 'announcement', 1, '2023-08-13 08:20:11', '2023-08-13 08:20:11', '2023-08-13 08:20:11'),
('795f8aa6-5c15-11ee-a632-a233a240566f', 'NEMSU Folklers', 'Folklers-23', 'Wagi ang North Eastern Mindanao State University Folkers ng Tandag kampus sa katatapos lamang na kompetisyon sa Pangkulturang Sayaw laban sa labing apat na kalahok na ginanap sa Robinsons Place, syudad ng Butuan. ', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝐍𝐄𝐌𝐒𝐔 𝐅𝐨𝐥𝐤𝐥𝐞𝐫𝐬, 𝐤𝐚𝐦𝐩𝐞𝐨𝐧 𝐬𝐚 𝐢𝐬𝐢𝐧𝐚𝐠𝐚𝐰𝐚𝐧𝐠 𝐩𝐚𝐭𝐢𝐦𝐩𝐚𝐥𝐚𝐤 𝐧𝐠 𝐏𝐚𝐧𝐠𝐤𝐮𝐥𝐭𝐮𝐫𝐚𝐧𝐠 𝐒𝐚𝐲𝐚𝐰 <br><br>\r\nWagi ang North Eastern Mindanao State University Folkers ng Tandag kampus sa katatapos lamang na kompetisyon sa Pangkulturang Sayaw laban sa labing apat na kalahok na ginanap sa Robinsons Place, syudad ng Butuan. <br><br>\r\nIto ay ilan sa mga gawaing patimpalak sa ika-56 na anibersaryo ng pagkakatatag ng ASEAN sa pangunguna ng Komisyon sa Mas Mataas na Edukasyon, Rehiyon ng Caraga.<br><br>\r\nNakamit ng NEMSU Folklers ang unang gantimpala dahil sa sayaw na pinamagatang “La Jota Quirino”, mula sa lalawigan ng Quirino na kilala pa noong ika-19 na siglo sa pamamagitan ng mananayaw na mga mag-aaral na sina John Lino Pedroso, Ma. Jane Galos, Harvie Cruiz, Nicole Macaylas, Von Del Valle, Nhoylen Comiling, Jeann Melo at Greg Michael Baguio na mga miyembro ng Malisto Dance Troupe.<br><br>\r\nNakuha rin ng Agusan del Sur State College of Agriculture and Technology (ASSCAT) ang ikalawang gantimpala at sinundan ng Saint Francis Xavier College bilang ikatlo.\r\nSamantala, nagpasalamat ang mga tagapagsanay ng NEMSU Folklers sa likod ng kanilang pagkapanalo na sina Castor V. Balacuit, Jr. at Shyla O. Moreno.<br><br>\r\n“We are so immensely thankful for the NEMSU administration for the full support,” aniya nila.<br><br>\r\nSa huli, ang kanilang tagumpay ay magiging alas ng kanilang koponan para sa darating na Local MASTS 2023.<br><br>\r\n𝘜𝘭𝘢𝘵 𝘯𝘪 𝘑𝘰𝘴𝘦𝘭𝘪𝘵𝘰 𝘙. 𝘈𝘣𝘢𝘴𝘰𝘭𝘰<br>\r\n𝘓𝘢𝘳𝘢𝘸𝘢𝘯 𝘯𝘪 𝘔𝘳. 𝘊𝘢𝘴𝘵𝘰𝘳 𝘝. 𝘉𝘢𝘭𝘢𝘤𝘶𝘪𝘵 𝘑𝘳<br><br>\r\n#TheVanguardPublication\r\n\r\n', 'folkers-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-09-22 18:33:11', '2023-09-22 18:33:11', '2023-09-22 18:33:11'),
('7ad2cd4e-47af-11ee-b55e-a233a240566f', 'TDG-Campus Steals Golds', 'Masts-TDG-arnis-2023', 'Having overpowered their opponents in the categories of Pin Weight, Bantam Weight, and Half Light Weight divisions, NEMSU Main campus bagged 3 out of 4 medals against San Miguel, of which has only won the Feather Weight category.', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/van-arnis-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">\r\n𝐓𝐚𝐧𝐝𝐚𝐠 𝐜𝐚𝐦𝐩𝐮𝐬 𝐬𝐭𝐞𝐚𝐥𝐬 𝐠𝐨𝐥𝐝 𝐢𝐝𝐞𝐚𝐥𝐬; 𝐬𝐜𝐨𝐫𝐞𝐬 𝟑-𝟏 𝐢𝐧 𝐜𝐨𝐦𝐛𝐚𝐭𝐢𝐯𝐞 𝐀𝐫𝐧𝐢𝐬 𝐯𝐬. 𝐒𝐚𝐧 𝐌𝐢𝐠𝐮𝐞𝐥 <br><br>\r\nHaving overpowered their opponents in the categories of Pin Weight, Bantam Weight, and Half Light Weight divisions, NEMSU Main campus bagged 3 out of 4 medals against San Miguel, of which has only won the Feather Weight category. \r\nDuring the first round, Mark Jade Logronio of Tandag campus swiftly and efficiently landed several blows to his opponent Jorgevic Nier, garnering a score of 9-3 in favor of Logronio. <br><br>\r\nThis was followed by the Bantham Weight category, of which was also sweeped by stronger and faster blows by Ram Patrick Revilleza on his opponent Melicar Sullano. <br><br>\r\nHope was lost when Revilleza overwhelmed his opponent by a huge continuous lead that led to Sullano\'s defeat scoring 12-4.<br><br>\r\nAmidst the fierce competition, the third round provided a glimmer of hope for Team San Miguel. Perfecto Logronio and Daryl Mahinay engaged in a swift duel that showcased their speed, power, and agility. <br><br>\r\nHowever, a few minor missteps and errors proved to be Perfecto Logronio\'s downfall, ultimately leading to his opponent\'s victory.<br><br>\r\nThe fourth and final round saw Tandag Campus\' Karl Fernandez effortlessly assert his dominance over Julius Caong. With quick moves and unyielding determination, Fernandez overwhelmed his opponent, securing Tandag\'s final triumph with a score of 10-1.<br><br>\r\nReport by Marc Daniel Enero<br>\r\nPhotos by Roger Bagood<br>\r\n#TheVanguardPublication<br>\r\n#LocalMASTS2023\r\n<br/>\r\n', 'van-arnis-00.jpg', 'The Vanguard Publication', 32, 'news', 1, '2023-08-30 16:40:11', '2023-08-30 16:40:11', '2023-08-30 16:40:11'),
('7ade2eb3-6e72-11f0-ae5d-a233a240566f', 'Three-day Training and Establishment of the SDSSU Multidisciplinary Research Journal Open Journal System (OJS)', 'Journal-Open-Journal-System', 'The three-day Training and Establishment of the SDSSU Multidisciplinary Research Journal Open Journal System (OJS) Version 3 commenced today, July 23, 2025, at the NEMSU ICT Laboratory. The activity is being guided by Mr. Emerson B. Endiola, the OJS in-charge of the Recoletos Multidisciplinary Research Journal, which runs on the 3.2 version and holds a Q3 ranking in Scopus. ', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-4.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/Multidisciplinary Research Journal Open Journal System-6.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe three-day Training and Establishment of the SDSSU Multidisciplinary Research Journal Open Journal System (OJS) Version 3 commenced today, July 23, 2025, at the NEMSU ICT Laboratory. The activity is being guided by Mr. Emerson B. Endiola, the OJS in-charge of the Recoletos Multidisciplinary Research Journal, which runs on the 3.2 version and holds a Q3 ranking in Scopus. \r\n\r\n<br/><br/>\r\nMr. Endiola\'s extensive expertise has been pivotal in steering the transition from OJS Version 2 to the upgraded Version 3, which is a crucial step as it enhances the functionality of the journal, aligning it with the required standards for inclusion in recognized indexing bodies, a goal that has been a priority for the SMRJ Editorial Team. \r\n<br/><br/>\r\nCurrently, SMRJ operates on OJS Version 2, which may be limiting its potential for reaching higher visibility and academic recognition. The transition to Version 3 is not just a technical update, but a significant move toward elevating the journal’s international stature.\r\n<br/><br/>\r\nThe SMRJ Editorial Team expresses its deepest gratitude to the unwavering support from the University President, Dr. Nemesio G. Loayon, the Vice President for Research and Extension, Dr. Rolly G. Salvaleon, Director for Research and Development, Dr. Erwin B. Berry, and the rest of the NEMSU research team. Their commitment and foresight have made this important training and upgrade possible.\r\n\r\n', 'Multidisciplinary Research Journal Open Journal System.jpg', 'Public Information Office', 0, 'news', 1, '2025-07-23 08:49:35', NULL, NULL),
('7b8f8dda-82f0-11ee-bea4-a233a240566f', 'The Retooling of ISO 9001:2015 QMS and Comprehensive Internal Audit', 'ISO-QMS-2023', 'The Retooling of ISO 9001:2015 QMS and Comprehensive Internal Audit', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/qms-06.jpg\" /></div>\r\n</div>\r\n', 'qms-00.jpg', 'Office of the Campus Director - Tandag', 0, 'news', 1, '2023-11-13 11:33:11', '2023-11-13 11:33:11', '2023-11-13 11:33:11'),
('7c38aedc-3cb9-11ee-a66e-a233a240566f', 'San Miguel Campus - Class Opening for A.Y. 2023-2024', 'Class-sm2023', 'San Miguel, August 14, 2023 - The sun rose on a new academic year as the North Eastern Mindanao State University (NEMSU) San Miguel campus unfolded a grand Class Opening Program for the 1st Semester of the Academic Year 2023-2024. ', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/smopen-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU San Miguel Welcomes the 1st Semester of A.Y. 2023-2024<br>\r\nSan Miguel, August 14, 2023 - The sun rose on a new academic year as the North Eastern Mindanao State University (NEMSU) San Miguel campus unfolded a grand Class Opening Program for the 1st Semester of the Academic Year 2023-2024. The NEMSU San Miguel Cultural Center buzzed with anticipation as the campus community gathered to embark on a journey of knowledge, growth, and inspiration.<br>\r\nThe program started on the much-awaited Opening Salvo, led by the dynamic and dedicated members of the University Student Government (USG) officers. Dressed in their official regalia, these student leaders set the tone for the day, showcasing their commitment to guiding their fellow students toward a successful academic year.<br>\r\nMr. Raymundo M. Itable, the esteemed Head of the Office of Student Welfare and Development (OSWD), delivered a heartfelt Welcome Message to the stage next. With warmth and enthusiasm, Mr. Itable extended his sincere welcome to the students, faculty, and staff members, emphasizing the university\'s dedication to fostering an environment of growth, inclusivity, and academic excellence.<br>\r\nDr. Clemencia L. Sumagaysay, the Campus Director, followed with an Inspirational Message. Dr. Sumagaysay\'s words resonated deeply with the audience, igniting a sense of purpose and determination among the students as they embarked on their educational journey.<br>\r\nThe Intermission Number was a delightful surprise, featuring a captivating performance by the university\'s Dance Club. With their artistry and synchronized moves, the dancers captivated the audience and infused the event with invigorating energy.<br>\r\nDr. Erwin Berry, the Curriculum Director, then shared his invaluable insights on the academic programs and curriculum enhancements in a Message from the Curriculum Director. His message provided a glimpse into the exciting learning opportunities that awaited the students in the upcoming semester.\r\nThe Presentation of Faculty and Staff acquainted the students with the dedicated individuals who would guide them through their academic pursuits. This segment acknowledged the contributions of the educators who tirelessly worked to shape the next generation\'s minds.<br>\r\nThe event came to a resounding close with Hon. Enrile M. Nazi, President of the University Student Government (USG), delivering the closing remarks. Hon. Nazi\'s words resonated deeply, inspiring unity, collaboration, and a shared commitment to academic success within the student body.<br>\r\nWith the inaugural Class Opening Program for the 1st Semester of A.Y. 2023-2024, the NEMSU San Miguel campus set the stage for an enriching and transformative academic year. The excitement and enthusiasm were palpable as the NEMSU community gathered under one roof, heralding a promising journey of learning, growth, and accomplishment.\r\n<br/>\r\n\r\n#nemsusanmiguel <br>\r\n#classopening\r\n', 'smopen-00.jpg', 'The FarmBuilders', NULL, 'news', 1, '2023-08-14 18:41:52', '2023-08-14 18:41:52', '2023-08-14 18:41:52'),
('7fa73c9b-6e2e-11ee-a3fc-a233a240566f', 'The Red Cross Youth Council - Main Campus sponsors First-Aide Training for RCY Volunteers ', 'Red-Cross-Youth-Council-2023', 'The Red Cross Youth Council - Main Campus sponsors First-Aide Training for RCY Volunteers as an effort to boost the capacity of the University in Disaster Preparedness and Resilience initiatives.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe Red Cross Youth Council - Main Campus sponsors First-Aide Training for RCY Volunteers as an effort to boost the capacity of the University in Disaster Preparedness and Resilience initiatives. <br><br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/redx-06.jpg\" /></div>\r\n</div>\r\n<br>', 'redx-00.jpg', 'Office of the Campus Director - Tandag', NULL, 'news', 1, '2023-10-18 19:50:21', '2023-10-18 19:50:21', '2023-10-18 19:50:21'),
('8009246c-53a4-11ee-b55e-a233a240566f', 'NEMSU President Dr. Nemesio G. Loayon Guides University\'s Income-Generating Initiatives Remotely; Virtual Attendance at Institutional Manual Review of IGP Operations Manual', 'IGP-Manual-2023', 'Cotabato, September 13, 2023 – Dr. Nemesio G. Loayon, President of North Eastern Mindanao State University (NEMSU), demonstrated his commitment to the university\'s growth and development by attending the Institutional Manual Review of the IGP (Income-Generating Projects)', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/igp-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/igp-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/igp-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU President Dr. Nemesio G. Loayon Guides University\'s Income-Generating Initiatives Remotely;\r\nVirtual Attendance at Institutional Manual Review of IGP Operations Manual\r\nCotabato, September 13, 2023 – Dr. Nemesio G. Loayon, President of North Eastern Mindanao State University (NEMSU), demonstrated his commitment to the university\'s growth and development by attending the Institutional Manual Review of the IGP (Income-Generating Projects) Operations Manual, held on September 13, 2023. The event took place at the University Board Room in NEMSU, while President Loayon joined remotely from Cotabato, where the 2023 MASTS (Mindanao Association of StateTertiarySchools,  Inc.) Games- Sports Competition was concurrently being held.<br><br>\r\nThe IGP Operations Manual is a pivotal document designed to steer NEMSU toward establishing new income-generating initiatives and enhancing existing ones. This comprehensive manual outlines strategies, guidelines, and protocols for the successful implementation of these projects, aiming to bolster the university\'s financial sustainability.<br><br>\r\nDespite being physically separated by distance, President Loayon\'s virtual presence underscored the importance of this review. His participation showcased his unwavering dedication to ensuring that NEMSU\'s income-generating initiatives align with the university\'s mission and vision.<br><br>\r\nDuring the virtual session, Dr. Loayon emphasized the need for innovation and adaptability in the ever-evolving landscape of income generation within the academic sector. He stated, \"Our university\'s financial health is vital to our ability to provide quality education. We must continually explore new avenues for income generation while refining our existing strategies.\"<br><br>\r\nThe event brought together faculty members, administrative staff, and experts in financial management, who actively discussed the manual\'s contents and provided valuable insights.<br><br>\r\nThe IGP Operations Manual review is part of NEMSU\'s ongoing efforts to enhance its financial sustainability and invest in its academic programs and facilities. President Loayon\'s remote participation allowed him to fulfill his commitments at both the Institutional Manual Review and the 2023 MASTS Games Sports Competition, demonstrating effective leadership and multitasking skills.<br><br>\r\nAs the session concluded, President Loayon expressed his optimism for NEMSU\'s future, stating, \"Our commitment to financial stability and academic excellence remains steadfast. This collaborative effort will undoubtedly propel us toward greater success in the years to come.\"<br><br>\r\nNEMSU\'s pursuit of innovative income-generating initiatives, guided by the IGP Operations Manual, reflects the institution\'s dedication to providing exceptional education and opportunities for its students while ensuring a secure financial foundation for its continued growth. President Loayon\'s active involvement, even from a distance, reinforces his commitment to NEMSU\'s progress and prosperity.\r\n\r\n\r\n', 'igp-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', NULL, 'news', 1, '2023-09-13 12:33:11', '2023-09-13 12:33:11', '2023-09-13 12:33:11'),
('810eead3-952a-11f0-a6c6-a233a240566f', '89TH NATIONAL BOOK WEEK', '89TH-NATIONAL-BOOK-WEEK', 'In line with Proclamation No. 109, s. 1936, which declares the celebration of National Book Week every November 24–30,', '<iframe \r\n    src=\"https://drive.google.com/file/d/1s8zHjKIsehBNGnpXAnX7655jSZ54_Wf4/preview\" \r\n    width=\"100%\" \r\n    height=\"600\" \r\n    allow=\"autoplay\">\r\n</iframe>', '89th National Book Week.jpg', 'Pressie Shane P. Sandigan ', 10, 'news', NULL, '2023-12-01 15:05:53', '2025-09-19 15:05:53', NULL),
('81d7672e-0926-11ef-9740-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐖𝐞𝐥𝐜𝐨𝐦𝐞𝐬 𝐂𝐇𝐄𝐃 𝐂𝐨𝐦𝐦𝐢𝐬𝐬𝐢𝐨𝐧𝐞𝐫 𝐃𝐚𝐫𝐢𝐥𝐚𝐠', 'Meet-and-Greet-2024', 'North Eastern Mindanao State University warmly welcomed Dr. Aldrin A. Darilag, the Commissioner and Chairperson-designate for the NEMSU Board of Regents, in a special meet-and-greet session on May 3, 2024.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/Meet-and-greet/meet-greet-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University warmly welcomed Dr. Aldrin A. Darilag, the Commissioner and Chairperson-designate for the NEMSU Board of Regents, in a special meet-and-greet session on May 3, 2024.\r\n<br><br>\r\nThe event focused on discussing efforts to achieve the transformation of State Universities and Colleges (SUCs) towards becoming Healthy Learning Institutions, aimed at promoting dialogue and relationship-building between NEMSU officials, faculty, and students.\r\n<br><br>\r\nDr. Darilag’s arrival was met with enthusiasm as he was warmly received by University officials and members of the NEMSU community. The academic convergence, held in the university’s boardroom, provided an opportunity for Dr. Darilag to share his vision for improving higher education quality in NEMSU and fostering a healthier learning environment conducive to student growth and success.\r\n<br><br>\r\nThe event was marked by engaging discussions and a spirit of collaboration between the university and the Commission on Higher Education (CHED), underscoring current pressing concerns experienced by the university. The lack of classrooms and qualified faculty, considering the growing student population, was a prevalent concern raised by Dr. Ariston Ronquillo, the Campus Director of NEMSU-Tagbina. In response, Dr. Darilag emphasized the importance of following the university’s absorptive capacity as one of the parameters of RA 10931, also known as the Universal Access to Quality Tertiary Education Act. Following this note, he also stressed the implementation of the institution’s Admission and Retention Policy as a basis for qualification for undergraduate students.\r\n<br><br>\r\nRegarding pressing student issues, Student Regent Dannalyn Labad represented the minorities when she asked the commissioner about his stance on the issue of cross-dressing among students. Dr. Darilag responded that students and even university personnel may be allowed to wear the prescribed uniform according to their sexual orientation, following the provisions of RA 11313, also known as the Safe Spaces Act. The commissioner’s remarks were supported by CHEDRO 13 Supervising Education Program Specialist, Mr. Ever Joy G. Rabadan, who advised incorporating certain provisions regarding cross-dressing in the Student Handbook, while having RA 11313 as its legal basis. Hon. Labad responded with delight that they are currently participating in the review of the said manual, which will be presented at the upcoming 2nd quarter regular board meeting.\r\n<br><br>\r\nThe event was also attended by 1st District Representative of Surigao del Sur Hon. Romeo S. Momo, Sr., who was the principal author of House Bill No. 8825, Establishing a Medical School in the North Eastern Mindanao State University. University Key Officials, Members of the Board of Regents, Campus Directors, CHED Supervising Education Program Specialists, Faculty, and Student Leaders from across NEMSU campuses also graced the occasion.\r\n<br/>', 'meet-greet-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-03 12:21:03', '2024-05-03 12:21:03', '2024-05-03 12:21:31'),
('82cfd517-b053-11ee-9af6-a233a240566f', '𝐂𝐒𝐂 𝐜𝐨𝐧𝐝𝐮𝐜𝐭𝐬 𝐨𝐫𝐢𝐞𝐧𝐭𝐚𝐭𝐢𝐨𝐧 𝐨𝐧 𝐭𝐡𝐞 𝐇𝐨𝐧𝐨𝐫 𝐀𝐰𝐚𝐫𝐝𝐬 𝐏𝐫𝐨𝐠𝐫𝐚𝐦 𝐟𝐨𝐫 𝐍𝐄𝐌𝐒𝐔 𝐞𝐦𝐩𝐥𝐨𝐲𝐞𝐞𝐬', 'csc-visit-2024', 'Civil Service Commission Director Aurora B. Mantilla and Chief Human Resource Specialist Ms. Marilyn T. Yballa fronted the orientation for the Honor Awards Program (HAP) at the New Boardroom, NEMSU-Tandag Campus.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csc-visit-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nCivil Service Commission Director Aurora B. Mantilla and Chief Human Resource Specialist Ms. Marilyn T. Yballa fronted the orientation for the Honor Awards Program (HAP) at the New Boardroom, NEMSU-Tandag Campus.<br><br>\r\nIn collaboration with NEMSU\'s Human Resource Management Office, CSC catapulted its HAP, a rewards and incentives program that recognizes government officials and employees who have displayed outstanding contributions or work performance. The convergence aimed to guide participants through the intricacies of the awarding process, shedding light on the criteria, nomination procedures, and the transformative impact that recognition can have on individuals and their respective organizations.<br><br>\r\nAs NEMSU embarks on this initiative, it ignites its human resources for a collective commitment to upholding the highest standards of public service, fostering a culture of recognition, and nurturing leaders who will shape a brighter future for the academic community.\r\n<br>\r\n', 'csc-visit-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-01-11 15:40:11', '2024-01-11 15:40:11', '2024-01-11 15:40:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('832a158b-6deb-11f0-ae5d-a233a240566f', ' 𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬: 𝐏𝐢𝐨𝐧𝐞𝐞𝐫𝐢𝐧𝐠 𝐭𝐡𝐞 𝐅𝐮𝐭𝐮𝐫𝐞 𝐰𝐢𝐭𝐡 𝐈𝐧𝐭𝐞𝐠𝐫𝐢𝐭𝐲, 𝐈𝐧𝐧𝐨𝐯𝐚𝐭𝐢𝐨𝐧, 𝐚𝐧𝐝 𝐓𝐫𝐚𝐧𝐬𝐟𝐨𝐫𝐦𝐚𝐭𝐢𝐨𝐧', '𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭-𝐂𝐚𝐦𝐩𝐮𝐬-𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬-𝟑𝟎𝐭𝐡-𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭-𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬:', '𝐂𝐚𝐠𝐰𝐚𝐢𝐭, 𝐒𝐮𝐫𝐢𝐠𝐚𝐨 𝐝𝐞𝐥 𝐒𝐮𝐫, 𝐉𝐮𝐧𝐞 𝟐𝟎, 𝟐𝟎𝟐𝟓 (𝐀𝐟𝐭𝐞𝐫𝐧𝐨𝐨𝐧) -The North Eastern Mindanao State University (NEMSU) - Cagwait Campus held its 30th Commencement Exercises, themed \"Pioneering the Future: A 2025 Legacy of Unwavering Integrity, Bold Innovation, and Transformational Impact,\" at the Multi-Purpose Evacuation Center in Poblacion, Cagwait.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬-1.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬-2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬-3.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬-4.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\n𝐂𝐚𝐠𝐰𝐚𝐢𝐭, 𝐒𝐮𝐫𝐢𝐠𝐚𝐨 𝐝𝐞𝐥 𝐒𝐮𝐫, 𝐉𝐮𝐧𝐞 𝟐𝟎, 𝟐𝟎𝟐𝟓 (𝐀𝐟𝐭𝐞𝐫𝐧𝐨𝐨𝐧) -The North Eastern Mindanao State University (NEMSU) - Cagwait Campus held its 30th Commencement Exercises, themed \"Pioneering the Future: A 2025 Legacy of Unwavering Integrity, Bold Innovation, and Transformational Impact,\" at the Multi-Purpose Evacuation Center in Poblacion, Cagwait.\r\n\r\n<br/><br/>\r\nA total of 125 candidates from various bachelor\'s degree programs, including Industrial Technology, Hospitality Management, and Information Technology, received their diplomas, marking the culmination of their academic journey.\r\n<br/><br/>\r\nHon. Romeo S. Momo, Sr., an outstanding engineer in Asia, delivered a stirring speech, urging the graduates to \"dream with no limits\" and to never give up in the face of challenges. He emphasized that \"the power to succeed lies in you\" and encouraged the graduates to believe in themselves.\r\n<br/><br/>\r\nThe ceremony highlighted the achievements of Cum Laude graduate Romeo F. Osol Jr. from the Bachelor of Science in Hospitality Management program, who received a plaque for his outstanding academic performance.\r\n<br/><br/>\r\nIn his message, Osol emphasized that \"this is not the end, but a starting point for all of us. Let us go forward!\" His words echoed the sentiments of Jonna L. Ordoña, an academic awardee, who noted that their graduation was not the end of their journey, but a tribute to their hard work and dedication.\r\n<br/><br/>\r\nThe 30th Commencement Exercises was a celebration of academic excellence, perseverance, and the unwavering commitment to shaping the future. As the graduates embark on their new journey, they carry with them the values of integrity, innovation, and transformational impact, poised to make a lasting difference in their communities and beyond.\r\n\r\n', '𝐍𝐄𝐌𝐒𝐔-𝐂𝐚𝐠𝐰𝐚𝐢𝐭 𝐂𝐚𝐦𝐩𝐮𝐬 𝐂𝐞𝐥𝐞𝐛𝐫𝐚𝐭𝐞𝐬 𝟑𝟎𝐭𝐡 𝐂𝐨𝐦𝐦𝐞𝐧𝐜𝐞𝐦𝐞𝐧𝐭 𝐄𝐱𝐞𝐫𝐜𝐢𝐬𝐞𝐬.jpg', 'Public Information Office', 0, 'news', 1, '2025-06-20 16:44:17', NULL, NULL),
('833fe41d-ed27-4ccb-af5f-2c5c98d6f4db', 'Development Academy of the Philippines (DAP) facilitates the NEMSU Strategic Planning 2023', 'development-academy-of-the-philippines-dap-facilitates-the-nemsu-strategic-planning-2023', '<p style=\"text-align:justify\"><span style=\"font-size:12.0pt\">As NEMSU traverses to a productive 2023, the Development Academy of the Philippines (DAP) facilitates the Three-day Executive and Management Committee Strategic Seminar Workshop at Arena Blanca, Britania, San Agustin, SDS on February 3-5, 2023. </span></p>', '<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">As NEMSU traverses to a productive 2023, the Development Academy of the Philippines (DAP) facilitates the Three-day Executive and Management Committee Strategic Seminar Workshop at Arena Blanca, Britania, San Agustin, SDS on February 3-5, 2023. The NEMSU key officials and management committee attended the strategic planning with hopes of navigating the critical indicators of the University towards quality and excellent higher education institution. Dr. Maria Lady Sol A. Suazo, VP-Academic Affairs expressed her welcome greetings highlighting the importance of the event in the pursuit of strategizing the ladder of NEMSU&rsquo;s vision.</span></span></p>\r\n            \r\n            <p style=\"text-align:justify\">&nbsp;</p>\r\n            \r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/pla.png\" /></span></p>\r\n            \r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">The good Commissioner of CHED, Hon. Jo Mark Libre virtually graced the opening program for NEMSU Strategic Planning 2023.&nbsp; Hon. Libre reminded everyone to always be at the top of innovation and maintain the momentum to hasten the higher education reforms. The presence of the Commissioner fuels the event as it manifested through inspired engagement of the participants. Atty. Ronnie Azura, The Oversight Resource Person of Senator Francis &ldquo;Chiz&rsquo; Escudero for NEMSU also extended his insightful message through his virtual presence in the event. In his message, he strengthened the essence of NEMSU towards quality and excellent higher education are indications in the strategic planning. The University secures that the elements in the strategic planning addresses the call and needs of its clients and stakeholders. The purpose of the strategic planning activities is to integrate the agency&rsquo;s mandated activities with the priorities of the Administration.</span></span></p>\r\n            \r\n            <p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2.png\" /></span></p>', '3.png', 'Public Information Office', NULL, 'news', 1, '2023-02-06 11:21:16', '2023-02-17 04:46:28', '2023-02-17 04:46:28'),
('835aa1b4-f415-11ef-b8b6-a233a240566f', '𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠 𝐭𝐡𝐞 𝐀𝐫𝐭 𝐨𝐟 𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡: 𝐓𝐫𝐚𝐢𝐧𝐢𝐧𝐠 𝐖𝐨𝐫𝐤𝐬𝐡𝐨𝐩 𝐨𝐧 𝐂𝐫𝐚𝐟𝐭𝐢𝐧𝐠 𝐚𝐧𝐝 𝐏𝐮𝐛𝐥𝐢𝐬𝐡𝐢𝐧𝐠 𝐇𝐢𝐠𝐡-𝐐𝐮𝐚𝐥𝐢𝐭𝐲 𝐏𝐚𝐩𝐞𝐫𝐬 𝐢𝐧 𝐒𝐜𝐨𝐩𝐮𝐬 𝐉𝐨𝐮𝐫𝐧𝐚𝐥𝐬', '𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡', 'NEMSU continues its commitment to advancing research excellence through the Training Workshop on Crafting and Publishing High-Quality Papers in Scopus Journals held on February 13-14, 2025, at NEMSU Tagbina Campus.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNEMSU continues its commitment to advancing research excellence through the Training Workshop on Crafting and Publishing High-Quality Papers in Scopus Journals held on February 13-14, 2025, at NEMSU Tagbina Campus.\r\n<br/><br/>\r\nThis workshop provides an opportunity for faculty and researchers to refine their skills in academic writing and scholarly publishing. Through expert discussions and hands-on sessions, participants gain insights into the process of producing research papers that meet international standards.\r\n', '𝐌𝐚𝐬𝐭𝐞𝐫𝐢𝐧𝐠-𝐭𝐡𝐞-𝐀𝐫𝐭-𝐨𝐟-𝐑𝐞𝐬𝐞𝐚𝐫𝐜𝐡.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-13 15:37:45', NULL, NULL),
('85d3f9b4-327b-11ee-a66e-a233a240566f', 'Dr. Nemesion G. Loayon, NEMSU President 2nd University Day Celebration', 'nemsu-2nd-uday', 'Happy 2nd NEMSU Day celebration! Join us as we commemorate our achievements and the spirit of unity at our university. Let\'s cherish the memories and forge a brighter future together. Happy NEMSU Day!', '<iframe width=\"500\" height=\"315\" src=\"https://www.youtube.com/embed/GaGPRqNpigg\" frameborder=\"0\" allowfullscreen></iframe>\r\n\r\n<p style=\"margin-left:0in; margin-right:0in; text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:14px\">Happy 2nd NEMSU Day celebration! Join us as we commemorate our achievements and the spirit of unity at our university. Let\'s cherish the memories and forge a brighter future together. Happy NEMSU Day! </span></span></p>', '', 'Public Information Office', NULL, 'news', 1, '2023-07-31 08:50:53', '2023-07-31 08:50:53', '2023-07-31 08:50:53'),
('867f08d5-7167-11ee-a3fc-a233a240566f', 'The CET in their Harry Potter themed Day', 'CET-Day-2023', 'The College of Engineering and Technology in their Harry Potter themed Day', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-13.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-14.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-15.jpg\" /></div>\r\n</div>\r\n<br>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-16.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-17.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/ascend-20.jpg\" /></div>\r\n</div>\r\n<br>', 'ascend-00.jpg', 'Office of the Campus Director - Tandag', 32, 'news', 1, '2023-10-23 11:23:11', '2023-10-23 11:23:11', '2023-10-23 11:23:11'),
('880ce816-fea8-11ed-affb-a600064b4626', 'Two-day ISO 9001:2015 1st Surveillance Audit', 'NQA-Visit2023', '', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nqa-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nqa-03.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/nqa-04.jpg\" /></div></div><br />\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><b>NEMSU Pres. Nemesio G. Loayon</b> warmly welcomes <b>Mr. Rannie L. Bernardino, NQA CEO/Lead Auditor</b> and <b>Mr. Kevin Castillon</b>, NQA Auditor for the 2-day ISO 9001:2015 1st Surveillance Audit. The activity which is facilitated by the Quality Assurance Office headed by Director Jennnifer Montero ensures that all policies and guidelines of the University are aligned with the international statutory and regulatory requirements. In 2019, SDSSU now NEMSU was awarded as ISO Certified for Quality Management System (QMS). </span></p>\r\n<br />', 'nqa-01.jpg', 'Public Information Office', NULL, 'news', 1, '2023-05-30 09:30:11', '2023-05-30 09:30:11', '2023-05-30 09:30:11'),
('890e5c27-ea6b-11ee-987e-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐣𝐨𝐢𝐧𝐬 𝐭𝐡𝐞 𝟏𝐬𝐭 𝐐𝐮𝐚𝐫𝐭𝐞𝐫 𝐍𝐚𝐭𝐢𝐨𝐧𝐰𝐢𝐝𝐞 𝐒𝐢𝐦𝐮𝐥𝐭𝐚𝐧𝐞𝐨𝐮𝐬 𝐄𝐚𝐫𝐭𝐡𝐪𝐮𝐚𝐤𝐞 𝐃𝐫𝐢𝐥𝐥', 'Earthquake-Drill-2024', 'North Eastern Mindanao State University (NEMSU) joins the 1st Quarter Nationwide Simultaneous Earthquake Drill, sponsored by the Provincial and City Disaster Risk Reduction and Management Offices with the support partner from BFP-Tago. The event was participated by all employees and staff of NEMSU, with the aim of preparing them for potential earthquake emergencies.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-07.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-08.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-09.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-10.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-11.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-12.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-13.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-14.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/2024/earthquake-drill/eq-15.jpg\" /></div>\r\n</div>\r\n<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) joins the 1st Quarter Nationwide Simultaneous Earthquake Drill, sponsored by the Provincial and City Disaster Risk Reduction and Management Offices with the support partner from BFP-Tago. The event was participated by all employees and staff of NEMSU, with the aim of preparing them for potential earthquake emergencies.\r\n<br><br>\r\nPrior to the earthquake drill, a short briefing was held at the NEMSU Conference Room for all employees, spearheaded by the University President of NEMSU, Dr. Nemesio G. Loayon, and the head of PDRRMO, Mr. Eduardo C. Milloren. During the briefing, the importance of disaster preparedness and the procedures to be followed during the drill were emphasized. Dr. Loayon and Mr. Milloren stressed the significance of being proactive in ensuring the safety of everyone in the university in the event of a real earthquake.\r\n<br><br>\r\nThe drill began with a simulated earthquake scenario, where participants were instructed to drop, cover, and hold on to protect themselves from falling debris. Following the earthquake, a recommended evacuation was conducted to test the university’s emergency response procedures.\r\n<br><br>\r\nDuring the simulation, there were victims who were trapped inside the office and in need of immediate assistance. Search and rescue teams were deployed to locate and extract the victims, while first aid teams provided medical assistance to those who were injured.\r\n<br><br>\r\nThe drill served as a valuable opportunity for NEMSU employees and staff to practice their emergency response skills and familiarize themselves with the university’s disaster preparedness protocols. It also highlighted the importance of being prepared for natural disasters and the crucial role that each individual plays in ensuring the safety and well-being of others.\r\nIn a statement during the assessment and evaluation, PDRRMO and CDRMMO expressed NEMSU for their active participation to disaster preparedness and emphasized the importance of conducting regular drills to ensure that everyone is well-equipped to respond to emergencies.\r\n<br><br>\r\nOverall, the 1st Quarter Nationwide Simultaneous Earthquake Drill at NEMSU was a success, with participants gaining valuable experience and knowledge that will help them effectively respond to future disasters. The university remains committed to prioritizing the safety and security of its employees and students, and will continue to conduct similar drills in the future to further enhance their emergency response capabilities and to apply valuable suggestions from the PDRRMO, CDRRMO, and BFP.<br><br>\r\nTags:\r\n<br><br>\r\nCivil Defense CARAGA Civil Defense PH City Disaster Risk Reduction and Management Office Tandag City\r\n<br><br>\r\n#NSEDQ12024\r\n<br/>', 'eq-00.jpg', 'Public Information Office', 0, 'news', 1, '2024-03-25 13:47:42', '2024-03-25 13:47:42', '2024-03-25 13:47:42'),
('89786148-128c-11ef-b18a-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐜𝐮𝐫𝐫𝐢𝐜𝐮𝐥𝐮𝐦 𝐞𝐱𝐩𝐚𝐧𝐝𝐬 𝐢𝐧𝐭𝐞𝐫𝐧𝐚𝐭𝐢𝐨𝐧𝐚𝐥, 𝐠𝐞𝐧𝐝𝐞𝐫 𝐩𝐞𝐫𝐬𝐩𝐞𝐜𝐭𝐢𝐯𝐞𝐬', 'Curriculum-Expands-International-GAD', 'Mounting international perspective and gender sensitivity, the Office of Curriculum Development, in partnership with the Lakbay Diyalogo Training Team, convened its academic connoisseurs from several departments from the curriculum, internationalization, human resource management office, and academic units to achieve a progressive perspective weaved into the university’s curriculum.', '<br>\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nMounting international perspective and gender sensitivity, the Office of Curriculum Development, in partnership with the Lakbay Diyalogo Training Team, convened its academic connoisseurs from several departments from the curriculum, internationalization, human resource management office, and academic units to achieve a progressive perspective weaved into the university’s curriculum.\r\n<br><br>\r\nRecognizing that NEMSU is a multicultural university, this two-day activity aimed to adopt inclusive and gender-responsiveness for a safer environment for all genders, through gender mainstreaming and integration. This thorough effort is meant to bring out the right perspectives among leaders with increased understanding and adaptability of the principles regarding the streamlining of gender empowerment and gender justice in the university and society at large.\r\n<br><br>\r\nThe learning space hopes to provide learning of the Gender and Development Agenda, Mandate, and Strategic Framework, deliver a discussion and circles in dialogues using the international perspective in pushing forward the gender integration and continuum at the university level, and outline an integrative direction in developing a gender-inclusive curriculum.\r\n', 'cur-international-gad.jpg', 'Public Information Office', 0, 'news', 1, '2024-05-15 15:26:52', '2024-05-15 15:26:52', '2024-05-15 13:00:20'),
('8bba9ada-f86a-11ed-affb-a600064b4626', 'North Eastern Mindanao State University - NEMSU held its 2nd Quarter Special Board of Regents (BOR) Meeting at Caraga State University - Cabadbaran Campus with CHED Commissioner and BOR Chairman, Comm. Jo Mark M. Libre as presiding office', '2nd-Quarter-Special-Board-of-Regents', '', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor2.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor3.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor4.jpg\" /></div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor5.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor6.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/csu-bor7.jpg\" /></div>\r\n</div>\r\n<br />\r\n<p style=\"text-align:justify\">The BOR deliberated the Revised Organizational Staffing Standards (ROSS) and Teaching positions for all qualified applicants of the University witnessed by resource persons from CHED-RO Caraga Dr. George Colorado and Hon. Ronnie Azura representing the Office of Hon. Sen. Chiz Escudero as oversight officer. </p>', 'csu-bor1.jpg', 'Public Information Office', NULL, 'news', 1, '2023-05-05 15:30:37', '2023-05-05 15:30:37', '2023-05-05 15:30:37'),
('8ccbffd1-3ca2-11ee-a66e-a233a240566f', 'The technical committee of the Office of Programs and Standards Development (OPSD) of the Commission on Higher Education (CHED)', 'OPSD-2023', 'The North Eastern Mindanao State University - NEMSU gathered as an academic community in support for the Graduate School COPC-Related Inspection. The technical committee of the Office of Programs and Standards Development (OPSD)', '\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OPSD-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OPSD-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/OPSD-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nThe North Eastern Mindanao State University - NEMSU gathered as an academic community in support for the Graduate School COPC-Related Inspection. The technical committee of the Office of Programs and Standards Development (OPSD) of the Commission on Higher Education (CHED) led the 2-day comprehensive inspections of the Graduate School Programs. <br>\r\nThis event is a testament to the collective commitment to advancing the frontiers of the Graduate School Programs in attaining the status of Certificate of Program Compliance (COPC) compliant. With the support of the administration headed by NEMSU Pres. Nemesio G. Loayon, the University will continue its quest to academic excellence and service to its students.\r\n<br/>\r\n', 'OPSD-00.jpg', 'Public Information Office', NULL, 'news', 1, '2023-08-17 10:20:15', '2023-08-17 10:20:15', '2023-08-17 10:20:15'),
('8cfa2c20-47f1-11ee-b55e-a233a240566f', 'ML Esport Champion-(M)', 'local-masts-MLBB2', '<p><span style=\"font-size:11.0pt\">𝗕𝗔𝗟𝗜𝗧𝗔𝗡𝗚 𝗘-𝗦𝗣𝗢𝗥𝗧𝗦 | Hukbong NEMSU Main naghari sa pasiklaban ng MLBB Male Category</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">𝗕𝗔𝗟𝗜𝗧𝗔𝗡𝗚 𝗘-𝗦𝗣𝗢𝗥𝗧𝗦 | Hukbong NEMSU Main naghari sa pasiklaban ng MLBB Male Category<br><br>\r\n\r\nSamahang Titans (Main Campus) ipinamalas ang angking galing sa larangang Mobile Legends matapos makakuha ng puntos na 2-0 (Best of 3 Games) laban sa King Albert Squad (Cantilan Campus).\r\n<br><br>\r\n\r\n#TheVanguardPublication<br>\r\n#LocalMASTS2023\r\n</span></span></p>', 'van-ML-01.JPG', 'The Vanguard Publication', 32, 'news', 1, '2023-08-31 18:50:52', '2023-08-31 18:50:52', '2023-08-31 18:50:52'),
('8f0fb943-f414-11ef-b8b6-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐒𝐞𝐜𝐮𝐫𝐞𝐬 𝐈𝐭𝐬 𝐅𝐢𝐫𝐬𝐭 𝐏𝐚𝐭𝐞𝐧𝐭 𝐟𝐨𝐫 𝐈𝐧𝐯𝐞𝐧𝐭𝐢𝐨𝐧!', '𝐅𝐢𝐫𝐬𝐭-𝐏𝐚𝐭𝐞𝐧𝐭-𝐟𝐨𝐫-𝐈𝐧𝐯𝐞𝐧𝐭𝐢𝐨𝐧', 'North Eastern Mindanao State University (NEMSU) has been granted its first patent for invention by the Intellectual Property Office of the Philippines (IPOPHL) for the 𝑴𝒖𝒍𝒕𝒊-𝒇𝒖𝒏𝒄𝒕𝒊𝒐𝒏𝒂𝒍 𝑴𝒆𝒂𝒔𝒖𝒓𝒆𝒎𝒆𝒏𝒕 𝑫𝒆𝒗𝒊𝒄𝒆, invented by 𝑴𝒓. 𝑽𝒊𝒓𝒈𝒊𝒍𝒊𝒐 𝑻. 𝑶𝒎𝒃𝒂𝒐, 𝑱𝒓. 𝒂𝒏𝒅 𝑴𝒔. 𝑨𝒏𝒈𝒆𝒍𝒊𝒆 𝑴𝒂𝒆 𝑬𝒓𝒂𝒏𝒅𝒊𝒐 𝒇𝒓𝒐𝒎 𝑵𝑬𝑴𝑺𝑼 𝑩𝒊𝒔𝒍𝒊𝒈 𝑪𝒂𝒎𝒑𝒖𝒔.', '\r\n<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nNorth Eastern Mindanao State University (NEMSU) has been granted its first patent for invention by the Intellectual Property Office of the Philippines (IPOPHL) for the 𝑴𝒖𝒍𝒕𝒊-𝒇𝒖𝒏𝒄𝒕𝒊𝒐𝒏𝒂𝒍 𝑴𝒆𝒂𝒔𝒖𝒓𝒆𝒎𝒆𝒏𝒕 𝑫𝒆𝒗𝒊𝒄𝒆, invented by 𝑴𝒓. 𝑽𝒊𝒓𝒈𝒊𝒍𝒊𝒐 𝑻. 𝑶𝒎𝒃𝒂𝒐, 𝑱𝒓. 𝒂𝒏𝒅 𝑴𝒔. 𝑨𝒏𝒈𝒆𝒍𝒊𝒆 𝑴𝒂𝒆 𝑬𝒓𝒂𝒏𝒅𝒊𝒐 𝒇𝒓𝒐𝒎 𝑵𝑬𝑴𝑺𝑼 𝑩𝒊𝒔𝒍𝒊𝒈 𝑪𝒂𝒎𝒑𝒖𝒔.\r\n<br/><br/>\r\nThis device combines a drawing compass with multiple measurement functions, allowing precise length, straightness, squareness, hole depth, inner and outer dimension, and thickness measurements.\r\n\r\n<br/><br/>\r\nThe patent was filed on December 31, 2021, as part of the ITSO Patent Training Activity, which covered intellectual property education, patent search, invention spotting, claim drafting, and participation in the Intellectual Property Master Class (IPMC).\r\n<br/><br/>\r\nThank you to IPOPHL and everyone involved in making this achievement possible. This marks a significant step for NEMSU’s research and innovation efforts.', '𝐅𝐢𝐫𝐬𝐭-𝐏𝐚𝐭𝐞𝐧𝐭-𝐟𝐨𝐫-𝐈𝐧𝐯𝐞𝐧𝐭𝐢𝐨𝐧.jpg', 'Public Information Office', 0, 'news', 1, '2025-02-11 15:33:36', NULL, NULL),
('9167759c-f4f7-4355-b1bc-32aa87327856', 'The NEMSU attained the PRIME HRM Maturity Level 2 recognized under Core HRM System: Rewards and Recognition [R&R]', 'the-nemsu-attained-the-prime-hrm-maturity-level-2-recognized-under-core-hrm-system-rewards-and-recognition-rampr', '<p>The NEMSU attained the PRIME HRM Maturity Level 2 recognized under Core HRM System: Rewards and Recognition [R&amp;R].</p>', '<div class=\"row\">\r\n<div class=\"col-md-6 col-sm-6 col-xs-6\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/1%20(4).png\" /></div>\r\n\r\n<div class=\"col-md-6 col-sm-6 col-xs-6\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/a.JPG\" /></div>\r\n</div>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\">The NEMSU attained the PRIME HRM Maturity Level 2 recognized under Core HRM System: Rewards and Recognition [R&amp;R]. The recognition was held during the 1st Quarter ACO-ADCO Joint Council Meeting on MArch 9, 2023 at Cagwait, Surigao del Sur. President Dr. Nemesio G. Loayon with the key officials of the University received such recognition from the Provincial Director Aurora Mantilla of CSC.</span></p>', '2 (4).png', 'Public Information Office', NULL, 'news', 1, '2023-03-10 08:49:23', '2023-03-10 08:49:23', '2023-03-10 08:49:23'),
('92ab18fc-8ed9-11ef-bdca-a233a240566f', '𝐍𝐄𝐌𝐒𝐔 𝐄𝐦𝐩𝐨𝐰𝐞𝐫𝐬 𝐅𝐢𝐬𝐡𝐞𝐫𝐟𝐨𝐥𝐤 𝐭𝐡𝐫𝐨𝐮𝐠𝐡 𝐒𝐮𝐬𝐭𝐚𝐢𝐧𝐚𝐛𝐥𝐞 𝐅𝐚𝐫𝐦𝐢𝐧𝐠 𝐚𝐧𝐝 𝐌𝐚𝐫𝐢𝐧𝐞 𝐂𝐨𝐧𝐬𝐞𝐫𝐯𝐚𝐭𝐢𝐨𝐧 𝐏𝐫𝐨𝐣𝐞𝐜𝐭', 'Empowers-Fisherfolk-Lianga', 'On October 14, 2024, North Eastern Mindanao State University (NEMSU) held the culmination of the project titled \"Empowering Fisherfolk on Effective Caulerpa Racemosa (Lato) Farming while Protecting the Marine Environment\" at the Aquatic Science Building, Lianga Campus. University President Prof. Nemesio G. Loayon emphasized the importance of this project in advancing sustainable livelihoods for fisherfolk while promoting marine biodiversity conservation in Lianga’s Mariculture Park.', '<p style=\"text-align:justify\"> <span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><br>\r\nOn October 14, 2024, North Eastern Mindanao State University (NEMSU) held the culmination of the project titled \"Empowering Fisherfolk on Effective Caulerpa Racemosa (Lato) Farming while Protecting the Marine Environment\" at the Aquatic Science Building, Lianga Campus. University President Prof. Nemesio G. Loayon emphasized the importance of this project in advancing sustainable livelihoods for fisherfolk while promoting marine biodiversity conservation in Lianga’s Mariculture Park.\r\n<br><br>\r\nThe project, which is part of NEMSU’s broader agenda on \"industry and commercially-driven research and innovation\" and \"community-responsive extension services,\" provided local fisherfolk with sustainable farming techniques for Caulerpa Racemosa (Lato). This effort aligns with the University’s goal of fostering disaster-resilient and climate-adaptive research in fisheries and environmental conservation. The project not only improves the livelihoods of fisherfolk but also ensures that marine resources are sustainably managed.\r\n<br><br>\r\nPresident Loayon highlighted the University\'s commitment to making Lianga a Research Center for Marine and Ecosystem studies. The project represents a successful knowledge-sharing initiative, contributing to economic empowerment and environmental protection through collaboration with local government units and key stakeholders like the Department of Science and Technology.\r\n<br><br>\r\nThe event concluded with gratitude to the researchers, faculty, and fisherfolk who worked together to make the project a success, underscoring NEMSU’s vision of continued research and innovation for a more sustainable future.', 'Project-Culmination-banner-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2024-10-14 19:50:41', '2024-10-14 19:50:41', '2024-10-14 19:50:41'),
('9690b4ad-a44f-11ee-9af6-a233a240566f', 'Attending the discussion and simulation on the results and findings of the Project \"Baseline Data towards Digital Transformation of Higher Education Institutions in Mindanao SUCs', 'Digital-SUCs-2023', 'Attending the discussion and simulation on the results and findings of the Project \"Baseline Data towards Digital Transformation of Higher Education Institutions in Mindanao SUCs', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/dto-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/dto-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/dto-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n', 'dto-00.jpg', 'NEMSU Pres. Nemesio G. Loayon', 0, 'news', 1, '2023-12-21 10:55:11', '2023-12-21 10:55:11', '2023-12-21 10:55:11'),
('96feceb6-834f-11ee-bea4-a233a240566f', 'The Department of Tourism is in the Main Campus for the Filipino Brand Service Excellence simultaneous twin Trainings participated by the BS Hospitality Management Faculty and Students.', 'DoTr', 'The Department of Tourism is in the Main Campus for the Filipino Brand Service Excellence simultaneous twin Trainings participated by the BS Hospitality Management Faculty and Students.', '<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-01.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-02.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-03.jpg\" /></div>\r\n</div>\r\n<br>\r\n<div class=\"row\">\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-04.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-05.jpg\" /></div>\r\n\r\n<div class=\"col-md-4 col-sm-4 col-xs4\"><img alt=\"\" class=\"img img-responsive\" src=\"/public_files/images/caraga-06.jpg\" /></div>\r\n</div>\r\n<br>\r\n', 'caraga-00.jpg', 'Office of the Campus Director - Tandag', 1, 'news', 1, '2023-11-07 11:48:11', '2023-11-07 11:48:11', '2023-11-07 11:48:11'),
('987727bb-8a36-4b7e-bb23-8168e3ab50a6', 'Industry Partnership of SDSSU with HYTEC Power, Inc. was launched', 'industry-partnership-of-sdssu-with-hytec-power-inc-was-launched', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">University President Remegita C. Olvida signed the Memorandum of Cooperation with HYTEC Power Inc. on October 22, 2013 at the latter&rsquo;s office address in Novaliches, Quezon City. Dr. Eloida O. Quezada , SDSSU Director for Extension Services and Training and Hytec Power, Inc.</span></span></p>\n          ', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">University President Remegita C. Olvida signed the Memorandum of Cooperation with HYTEC Power Inc. on October 22, 2013 at the latter&rsquo;s office address in Novaliches, Quezon City. Dr. Eloida O. Quezada , SDSSU Director for Extension Services and Training and Hytec Power, Inc. Administration Manager Maricar R. Tranquilino stood as witnesses during said signing&nbsp; of the covenant.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Upon signing the Memorandum of Cooperation both parties commit themselves to undertake the following :</span></span></p>\n          \n          <p style=\"margin-left:40px; text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">1. to identify growth sectors and key employment generations in the economy;</span></span></p>\n          \n          <p style=\"margin-left:40px; text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">2. to match learning outcomes with industry standards;</span></span></p>\n          \n          <p style=\"margin-left:40px; text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">3. to align curriculum and admission in tertiary education along PPP priorities; and</span></span></p>\n          \n          <p style=\"margin-left:40px; text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">4.&nbsp; to conduct regional, national and international trainings participated by SUCs and HEIs using experts of both parties.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">This partnership through both parties &nbsp;common conviction for quality and relevant higher education is essential to the long term solutions to global challenges.</span></span></p>\n          ', 'hytec picture.jpg', 'Mark Erizo', NULL, 'news', 1, '2017-02-13 14:49:11', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-913f-470a-8731-9f19ce2e41a1', 'Faculty Paper is published in the ISI Journal of Maejo University', 'faculty-paper-is-published-in-the-isi-journal-of-maejo-university', '<p>Ms. Gemma A. Asufre presented her paper entitled, &ldquo; Preliminary Study of TikodAmo &ldquo; Spondylus sp.&rdquo; on its Potential as an Oyster Culture Species at Chian Mae, Thailand during the International Conference on Interdisciplinary Research and Development in ASEAN Universities on August 8- 10, 2013.</p>', '<p>Ms. Gemma A. Asufre presented her paper entitled, &ldquo; Preliminary Study of TikodAmo &ldquo; Spondylus sp.&rdquo; on its Potential as an Oyster Culture Species at Chian Mae, Thailand during the International Conference on Interdisciplinary Research and Development in ASEAN Universities on August 8- 10, 2013.</p>\n          \n          <p>Of the 340 entries worldwide,&nbsp; Ms. Asufre&rsquo;s paper was chosen as one of the 30 papers to be published in the ISI Journal of Maejo University.</p>', 'new 2.jpg', 'Mark Erizo', NULL, 'news', 1, '2017-02-13 14:50:54', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-9465-4abc-9a9c-b415a2a3245b', 'THE FIRST QUARTER ACO-ADCO FOR 2017', 'the-first-quarter-aco-adco-for-2017', '<p>Shacene Convention Hall Tandag City, Six (6) campuses of Surigao Del Sur State University steered 1<sup>st</sup> Quarter Academic and Administrative Councils (ACO-ADCO) Meeting on March 3, 2017.</p>', '<p>Shacene Convention Hall Tandag City, Six (6) campuses of Surigao Del Sur State University steered 1<sup>st</sup> Quarter Academic and Administrative Councils (ACO-ADCO) Meeting on March 3, 2017. Faculty members of academic rank&nbsp;of Assistant Professor and up were in high spirit with their Sundays Best as they discussed academic and administrative matters for board approval. Among the important topics discussed were: the tentative list of graduating students, graduation fee, and proposed review classes for engineering, incentive&nbsp;for top notchers, faculty scholarship, NBC 461, MOAs, and other matters.</p>\n          \n          <p>The University President, Dr Baceledes R Estal, conveyed&nbsp;his President&rsquo;s time with inspiration and a call for unity and compassion&nbsp;amid the challenges of the time. Dr Estal echoed&nbsp;that leadership is not only for the President but it also means the leadership of each member of the University work force. The ACO-ADCO was&nbsp;also a venue for a vigorous exercise of democracy as deliberations became more objective and direct.</p>\n          \n          <div>\n          <div><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/pic%202.jpg\" /></div>\n          \n          <div><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/pic%203.jpg\" /></div>\n          </div>', 'aco adco pic 1.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-03-07 13:55:15', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-9999-40f0-b03f-0e149ae0b2fa', 'SDSSU’s FINEST GOES TO VIGAN', 'sdssus-finest-goes-to-vigan', '<p>The Philippine Association of State Universities and Colleges (PASUC) Culture and Arts Festival tossed at Vigan City on December 6-10, 2016.</p>\n          ', '<p style=\"text-align:justify\">The Philippine Association of State Universities and Colleges (PASUC) Culture and Arts Festival tossed at Vigan City on December 6-10, 2016. CARAGA Region was&nbsp;represented by four promising SUC&rsquo;s including&nbsp;SDSSU. The fighting spirit of the young competitors brought&nbsp;honor to the region as SDSSU representatives won 2<sup>nd</sup> Runner Up in Hip hop, 3<sup>rd</sup> Runner Up in Extemporaneous Speaking, 4<sup>th</sup> Runner Up in Quiz Bowl, 6<sup>th</sup> Place in Charcoal Rendering, 6<sup>th</sup> Place in Contemporary Dance, 8<sup>th</sup> Place in Pagsulat ng Sanaysay, 9<sup>th</sup> Place in Dagliang Talumpati, 10<sup>th</sup> Place in Kundiman, 12<sup>th</sup> Place in Instrumental. Out of 17 Regions across the country SDSSU emerged&nbsp;as one of the youngest Institutions&nbsp;in the country. The competition ended up with a surprise tour from the CARAGA athletic management which inspired the participants in the region. Congratulations to the TEAM!</p>\n          \n          <div class=\"row\">\n          <div class=\"col-lg-6\"><img alt=\"\" src=\"/public_files/images/pic%202%281%29.jpg\" style=\"height:234px; width:350px\" /></div>\n          \n          <div class=\"col-lg-6\"><img alt=\"\" src=\"/public_files/images/pic%203%281%29.jpg\" style=\"height:235px; width:350px\" /></div>\n          </div>\n          ', 'vigan 1.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-03-15 13:43:58', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-a04c-4b86-8a7e-ec5fe3aa10f5', '7 YEARS OF NOBLE YIELDS', '7-years-of-noble-yields', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU celebrated&nbsp;7<sup>th</sup> University Day on February 22, 2017 with the theme: Enhancing Quality and Internationalizing Higher Education.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU celebrated&nbsp;7<sup>th</sup> University Day on February 22, 2017 with the theme: Enhancing Quality and Internationalizing Higher Education. The feast launched&nbsp;ground parade and the celebration of the Holy Mass. The opening program surprised&nbsp;the spectators as five (5) teams exhibited their vigorous yells and chants. The University President, Dr Baceledes R. Estal, delivered&nbsp;his University Address by reporting the achievements of SDSSU during his term in the field of Research, Extension, Instruction, and Production. Dr Estal emphasized&nbsp;his call for excellence not only in the field of education but above all for service and compassion. Later in the afternoon the friendly games excited the celebration as the teams competed in different games including volleyball, basketball, badminton, table tennis, lawn tennis, and chess among others. The program concluded with a fellowship dinner with the key officials of the University. The awarding of the overall champion also followed&nbsp;with Team Estrada emerging to be victorious. It was a Happy Charter Day for all.</span></span></p>\n          \n          <div class=\"row\">\n          <div class=\"col-lg-6\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/uday%20pic%202.jpg\" /></span></span></div>\n          \n          <div class=\"col-lg-6\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/uday%20pic%203.jpg\" /></span></span></div>\n          </div>', 'uday pic 1.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-03-15 13:58:38', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-a3ba-4dc9-bbf8-5d473c51c5c1', 'Civil Engineering Dominates R and B Summit', 'civil-engineering-dominates-r-and-b-summit', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"background-color:white\"><span style=\"color:black\">ROADS AND BRIDGES SUMMIT 2017, March 23, 2017.GREEN BRIDGE BUILDING CATEGORY.</span></span></span></span></p>', '<p><span style=\"background-color:white\"><strong><span style=\"font-size:10.0pt\"><span style=\"color:black\">ROADS AND BRIDGES SUMMIT 2017, March 23, 2017.GREEN BRIDGE BUILDING CATEGORY.</span></span></strong></span></p>\n          \n          <p><span style=\"background-color:white\"><span style=\"font-size:10.0pt\"><span style=\"color:black\">CHAMPION: 20k and plaque SDSSU Civil Engineering Students </span></span></span></p>\n          \n          <p style=\"margin-left:.5in; margin-right:0in\"><span style=\"background-color:white\"><a href=\"https://www.facebook.com/edjie.batino\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Edjie Astodillo Batino</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/kenneth.maligsa\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Kenneth Guerta Maligsa</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, <a href=\"https://www.facebook.com/aamingdee\" target=\"_blank\"><span style=\"color:#196ad4\">Aaming Dee Rogero</span></a>, </span></span><a href=\"https://www.facebook.com/geraldo.logronio\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Geraldo Jr Logronio</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/stephennichole.mantiza\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Stephen Megs Booh Mantiza.</span></span></a></span></p>\n          \n          <p><span style=\"background-color:white\"><span style=\"font-size:10.0pt\"><span style=\"color:black\">1st Runners Up- 15k and plaque.SDSSU Civil Engineering Students </span></span></span></p>\n          \n          <p style=\"margin-left:.5in; margin-right:0in\"><span style=\"background-color:white\"><a href=\"https://www.facebook.com/junreyquico\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Junrey Sauro Quico</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/christiandave.roco\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Dave Roco</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/ydnic.rohsahlii\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Aimee Cindy Arpilleda Rosal</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/BLACKIE.Curada\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Kevin Louie Tulang Curada</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\">, </span></span><a href=\"https://www.facebook.com/11dauntless29\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Claire Escanilla.</span></span></a></span></p>\n          \n          <p><span style=\"background-color:white\"><span style=\"font-size:10.0pt\"><span style=\"color:black\">2nd Runners up- 10k and plaque.SDSSU Civil Engineering Students </span></span></span></p>\n          \n          <p style=\"margin-left:40px\"><span style=\"background-color:white\"><a href=\"https://www.facebook.com/nicoevanestrada44\" target=\"_blank\"><span style=\"font-size:10.0pt\"><span style=\"color:#196ad4\">Evan Nico</span></span></a><span style=\"font-size:10.0pt\"><span style=\"color:black\"> and others.</span></span></span></p>', 'security-apps-banner-design_edited.jpg', 'Abundio C. Miralles.MAELT', 32, 'news', 1, '2017-03-31 09:30:31', '2023-02-14 03:49:11', '2023-02-14 03:49:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('987727bb-a658-455c-a8df-47e92aa67cb2', 'THUMBS UP LADIES OF SDSSU', 'thumbs-up-ladies-of-sdssu', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU Main Campus- In response to the call for change SDSSU Faculty, Staff and Student Leaders merged in the annual celebration of women&rsquo;s month on March 31, 2017 to inspire and empower women to achieve gender equality in the academic sector. This year&rsquo;s team is &ldquo;We Make Change Work for Women&rdquo;.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU Main Campus- In response to the call for change SDSSU Faculty, Staff and Student Leaders merged in the annual celebration of women&rsquo;s month on March 31, 2017 to inspire and empower women to achieve gender equality in the academic sector. This year&rsquo;s team is &ldquo;We Make Change Work for Women&rdquo;. Following the directive from the Philippine Commission on Women (PCW), SDSSU GAD team highlighted interactive physical games and exercises that aim to promote healthy and interpersonal skills. The call for change continues to reverberate this year as SDSSU endeavors to ensure that women have equal rights with men in the academe by institutionalizing gender sensitive policies and programs. The said activity became a stress reliever for the participants as they temporarily isolated themselves from the usual chores and united in a boodle figh t. Mabuhay GIRLS!</span></span></p>\n          \n          <div class=\"row\">\n          <div class=\"col-md-6\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/womens%20celeb%203.jpg\" /></div>\n          \n          <div class=\"col-md-6\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/womens%20celeb%204.jpg\" /></div>\n          </div>', 'womens celeb 1.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-03-31 15:51:33', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-abe3-4622-937d-081da14d40e3', 'CONG. PICHAY LAUDS SDSSU CLASS 2017', 'cong-pichay-lauds-sdssu-class-2017', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"background-color:white\"><span style=\"color:#1d2129\">Tandag City- Hon Prospero A. Pichay, Jr., Representative of the 1st District of Surigao Del Sur joined the 33rd Commencement Exercises Monday afternoon of April 3, 2017.</span></span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"background-color:white\"><span style=\"color:#1d2129\">Tandag City- Hon Prospero A. Pichay, Jr., Representative of the 1st District of Surigao Del Sur joined the 33rd Commencement Exercises Monday afternoon of April 3, 2017. Pichay acclaimed the graduates as they finished degree and hurdled to pursue education notwithstanding the challenges of the time. More than 2,000 spectators packed the school&rsquo;s gymnasium to witness the said event. This year&rsquo;s graduation ceremonies bear the theme: Go Global: A Cross-Border Responsive Challenge in Higher Education attended by the members of the Board Regent, Parents, Stakeholders, and the full force of SDSSU Teaching and Non-Teaching Personnel. Dr. Baceledes R. Estal, SUC President II, confirmed 981 candidates for graduation through board resolution no 3 series of 2017 duly signed by the members of the Board of Regent headed by the Hon. Prospero E. De Vera, the chairperson.SDSSU continues to earn institutional accolades every year by consistently producing passers in the professional licensure examinations for teachers, engineers and midwifery which is above the national passing rate making the Institution highly competitive among the Higher Education Institutions (HEIs) in the country.</span></span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:10.5pt\"><span style=\"background-color:white\"><span style=\"color:#1d2129\">&nbsp;&nbsp;<img alt=\"\" src=\"/public_files/images/17636883_1598200873542487_3329367602892707_o.jpg\" style=\"height:450px; width:676px\" />&nbsp;&nbsp; </span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:10.5pt\"><span style=\"background-color:white\"><span style=\"color:#1d2129\">&nbsp;&nbsp; </span></span></span></p>', '17547061_1598201456875762_8430715022599601242_o.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-04-06 13:34:43', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-ae23-4a14-9de8-e5d46ea271d6', 'NEDA INSPIRES SDSSU CAMPERS', 'neda-inspires-sdssu-campers', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU Science Building - Hon. <strong>Mylah Faye Aurora B. Cari&ntilde;o,</strong><strong> </strong>Regional Director and SDSSU Board of Regent Member stunned the participants of the Summer Youth Camp as she uncovered the Caraga Regional Development Plan (CRDP) to the student leaders.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU Science Building - Hon. <strong>Mylah Faye Aurora B. Cari&ntilde;o,</strong><strong> </strong>Regional Director and SDSSU Board of Regent Member stunned the participants of the Summer Youth Camp as she uncovered the Caraga Regional Development Plan (CRDP) to the student leaders. <strong>Cari&ntilde;o in her speech reiterated the role of student leaders in development and assured the young leaders that NEDA is stern in pushing transformation as the </strong>premier development and socioeconomic planning agency of the country. The camp was participated by elected student leaders of SDSSU satellite campuses who attentively noted the enthusiasm of the Regional Director in speaking with the youth. The presence of the regional director placed the camp into a higher level as topics on Poverty, Economics, Food Security, Ambisyon Natin, and Inflation among others were discoursed by <strong>Cari&ntilde;o. Dr Baceledes&nbsp; Estal, SUC President II, Dr. Florife Urbiztondo, VPAF, and Hon. Kenneth John Cutar also joined the RD during the visit on May 17, 2017.</strong></span></span></p>\n          \n          <p style=\"text-align:justify\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"/public_files/images/1.png\" style=\"height:315px; width:500px\" /></strong></p>', '2.png', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-05-19 10:33:50', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-b07f-4464-9081-f5bf05e0e3f5', 'SDSSU GEARS BRIGADA AHENSYA', 'sdssu-gears-brigada-ahensya', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU TANDAG- In the spirit of Bayanihan the Faculty, Staff, and Students rolled up their sleeves in response to Civil Service Memorandum Circular # 12 series of 2009 encouraging all government agencies of the country to clean up.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU TANDAG- In the spirit of Bayanihan the Faculty, Staff, and Students rolled up their sleeves in response to Civil Service Memorandum Circular # 12 series of 2009 encouraging all government agencies of the country to clean up. In a memorandum from the University President all teaching and non-teaching personnel as well as the students were instructed to participate in the Brigada Ahensya this year. In a CSC memorandum the activity intends to declog offices in order to have valuable space for employees&#39; welfare such as physical fitness and sports area, garden plot, mini park or archival area for important documents and office items. The Brigada started with a short program in front of the academic building to brief everyone on the significance of the said endeavor to the academic community like SDSSU. At the end of the day the activity was unifying and invigorating.</span></span></p>\n          \n          <p style=\"text-align:justify\"><img alt=\"\" src=\"/public_files/images/1.jpg\" style=\"height:182px; width:650px\" /></p>', '3.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-05-30 14:32:16', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-b33e-4d79-b657-916d6aab81e2', 'SDSSU APPOINTS NEW PERSONNEL', 'sdssu-appoints-new-personnel', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Baceledes R. Estal, University President, recently presided the oath-taking of 29 Instructors and Non-Teaching personnel held last June 16, 2017.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Baceledes R. Estal, University President, recently presided the oath-taking of 29 Instructors and Non-Teaching personnel held last June 16, 2017. The oath-taking was long-awaited and well-deserved especially with the massive increase of enrolment of SDSSU for the past five years. This is the first batch of employees to take their oath as the recruitment and hiring is still on-going to seal the remaining 86 vacant positions for Instructor I. The University President emphasized in his speech the importance of customer care to improve the services of the institution. The oath-taking was organized by the Office of the Human Resource thru Roel T. Lim. Orientation of CSC policies was also initiated to acquaint the newly appointed personnel of the standards and policies of the institution. Also present during the event were Dr. Florife Urbiztondo, Dr Gerry Estrada, Hon. Violeta Grefalde. Congratulations!</span></span></p>\n          \n          <p style=\"text-align:justify\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/pic%201%281%29.jpg\" style=\"height:234px; width:350px\" />&nbsp; &nbsp; <img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/pic%202%282%29.jpg\" style=\"height:234px; width:350px\" />&nbsp; &nbsp;&nbsp;</p>', 'pic 3.jpg', 'Abundio C. Miralles,MAELT', NULL, 'news', 1, '2017-06-21 09:37:40', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-b6e7-4004-9acd-6849e825cab9', 'System Wide Librarians’ Meeting', 'system-wide-librarians-meeting', '<p style=\"text-align:justify\"><span style=\"font-size:10.0pt\"><span style=\"font-family:Arial\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">As the saying goes that &ldquo;when you don&rsquo;t plan it, it will happen&rdquo; describes best the just concluded meeting of the librarians of the six campuses with no less than the Director of Libraries, Mrs. Aida C. Osorio as the presiding officer.</span></span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:10.0pt\"><span style=\"font-family:Arial\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">As the saying goes that &ldquo;when you don&rsquo;t plan it, it will happen&rdquo; describes best the just concluded meeting of the librarians of the six campuses with no less than the Director of Libraries, Mrs. Aida C. Osorio as the presiding officer.</span></span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The system librarians&rsquo; meeting was held last August 22, 2016 at the main campus university library. It was well-represented.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The meeting started with a prayer led by Mr. Ronnie J. Sajelan followed by checking of attendance and without further ado, the meeting proper. Agenda were listed: Preparation of APP and PPMP; Revision of Library Handbook and Library&nbsp;&nbsp; Development Plan and Library Plans and Activities for 2017. Thorough discussions of each agenda were made and points of clarifications from the librarians were taken. More emphasis was on the revision of the library handbook because the last revision was held last 2012. Many changes were incorporated and properly documented by the secretary. The Library Development Plan was also revisited. Librarians were able to share their plans for the next school year and proposals were asked to submit to be included in the director&rsquo;s report. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">It was a day full of energy because snacks and lunch were served while the librarians are still working. So much have been done and the meeting adjourned at 4:00 p.m.</span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:10.0pt\"><span style=\"font-family:Arial\"><img alt=\"\" src=\"/public_files/images/meeting.jpg\" style=\"height:240px; width:400px\" /> <img alt=\"\" src=\"/public_files/images/meetingpix.jpg\" style=\"height:240px; width:326px\" /></span></span></p>', 'Systemwidelibrariansmetting.png', 'Michelle Ann U. Ortega, MLIS', 10, 'news', 1, '2017-06-29 18:32:24', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-b9d6-40e3-9b5d-4e283b094af8', '3rd International Conference on Children’s Librarianship', '3rd-international-conference-on-childrens-librarianship', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU library management sent a participant to one of the awaited conference in the Philippines. Ms. Maria Lea Griettel A. Espa&ntilde;a, E-Resources/ Technical librarian was able to experienced a momentous event together with her fellow librarians.</span></span></p>\n          ', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU library management sent a participant to one of the awaited conference in the Philippines. Ms. Maria Lea Griettel A. Espa&ntilde;a, E-Resources/ Technical librarian was able to experienced a momentous event together with her fellow librarians. The 3rd International Conference on Children&rsquo;s Librarianship was different and full of excitement. The said event theme: &ldquo;Fostering Inclusive Children &amp; Young Adult Services in Libraries &ldquo; held at Almond Inland Resort,&nbsp;&nbsp; Butuan City , Agusan del Norte last July 18-20, 2016. Spearheaded by the National Library of the Philippines in partnership with Butuan City Public Library.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">We (librarians) were honored to have an international speakers, namely: <em><strong>Ingrid Bon</strong></em> (Chairperson, IFLA Library Services for Children &amp; Young Adult) as our Keynote Speech from Netherlands, <em><strong>Hiroshi Kawamura </strong></em>(Vice President, Assistive Technology Dev&rsquo;t. Organization (ATDO), Japan) with his topic &ldquo;Partnerships in Nurturing Inclusive Programs for Libraries&rdquo;. Another speaker from Bangladesh <em><strong>Ms. Razina Akhter </strong></em>Head of Library &amp; Chief Librarian, Bangladesh&nbsp; Shishu Academy, She talks about &ldquo;Fostering Inclusive Services in Children &amp; Young Adult Libraries in the 21st Century.&rdquo; <em><strong>Prasong&nbsp; Saihond </strong></em>(Storyteller, Thailand) makes a Workshop on&nbsp;&nbsp; Acting, Reading and Telling Stories, While <em><strong>Ahn Chansoo</strong></em>, Director General, Book Culture Foundation, Seoul Korea talks about Children&rsquo;s Library Services and &ldquo;Bookstart&rdquo; in Seoul Korea. We also have local speakers, namely: Danilo G. Liwanag (Director, Roppets Edutainment Productions, Inc.), Ma. Elsie C. Esmer, Ed.D. (Supervising Education Program Specialist, Student Inclusion Division Bureau of Learning Delivery, DepEd), Dr. Yolanda S. Quijano (Education Consultant, Early Childhood Care &amp; Dev&rsquo;t. Council, DepEd), Maricel M. Diaz (Head Librarian, Library for the Blind Section, NLP), Melanie A. Ramirez (Head Librarian, Children&rsquo;s Section, NLP).</span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img alt=\"\" src=\"/public_files/images/3rdinternational%20conference%20pix.jpg\" style=\"height:330px; width:394px\" /></p>\n          \n          <p style=\"text-align:justify\"><span style=\"color:black\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong><span style=\"font-size:10px\">Ms. Espa&ntilde;a</span></strong></span><strong><span style=\"font-size:10px\"><span style=\"color:black\"> selfies </span><span style=\"color:black\">with the three (3) mascots</span><span style=\"color:black\">&nbsp;&nbsp; ONYOT and MELAI, </span><span style=\"color:black\">from NLP and </span><span style=\"color:black\">BOKBOK </span><span style=\"color:black\">from</span> <span style=\"color:black\">Butuan City Library</span><span style=\"color:black\">.</span></span></strong></p>\n          \n          <p>&nbsp;</p>\n          ', '3rdinternational conference.jpg', '', 10, 'news', 1, '2017-06-29 17:47:19', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-bc86-41d1-b4bd-0c2c61704339', 'System Wide Library Management Teamwork', 'system-wide-library-management-teamwork', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">According to William Scott, NBC TV Weatherman <em>&ldquo;Librarians have always been among the most thoughtful and helpful people. They are teachers without a classroom. No libraries, no progress&rdquo;.</em></span></span></p>\n          ', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">According to William Scott, NBC TV Weatherman <em>&ldquo;Librarians have always been among the most thoughtful and helpful people. They are teachers without a classroom. No libraries, no progress&rdquo;.</em></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">Indeed! Librarians are the mind and soul of the library. SDSSU Librarians work hand in hand to improve and develop the resources especially in the digital world of the library.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">One of the librarian from SDSSU-Tandag extend her expertise to one of the libraries of SDSSU management system. She was able to organized and processed their collections and taught them various electronic resources such as the online databases that includes STARBOOKS, Calibre, Proquest, eLibraryUSA Resources, Online Public Access Catalog&nbsp; (OPAC) and other databases.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img alt=\"\" src=\"/public_files/images/teamwork2.jpg\" style=\"border-style:solid; border-width:3px; height:292px; width:400px\" /></span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>\n          \n          <p>&nbsp;</p>\n          ', 'teamwork.jpg', 'Ma. Lea Griettel A. España', 10, 'news', 1, '2017-06-29 18:32:24', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-beb4-49c2-a8fc-bb7f2877f747', 'Japos: What people release is the truth, you can’t fake it', 'japos-what-people-release-is-the-truth-you-cant-fake-it', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">&ldquo;When people get emotional, they need release, and whatever they release, that is the truth and you can&rsquo;t fake it,&rdquo; Dr. Genaro V. Japos, resource speaker, has stated during the first day of the threeday seminar-workshop on Qualitative Research Methodology on July 12, 2017 at the Audio-Visual Center (AVC), Surigao del Sur State Univerty (SDSSU)-Main.&nbsp;</span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">&ldquo;When people get emotional, they need release, and whatever they release, that is the truth and you can&rsquo;t fake it,&rdquo; Dr. Genaro V. Japos, resource speaker, has stated during the first day of the threeday seminar-workshop on Qualitative Research Methodology on July 12, 2017 at the Audio-Visual Center (AVC), Surigao del Sur State Univerty (SDSSU)-Main.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">Dr. Ma. Lady Sol A. Suazo has stated the purpose of the seminar that is to gain insights; explore the&nbsp;depth, richness and complexities inherent to a specific phenomenon. Novice researchers need to be mentored on the elements that govern the design and implementation of qualitative research methodology.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">Dr. Jennifer Montero has introduced the resource speaker as the man who finished five doctorate degrees and a national assessor on IQUAME for Commission on Higher Education from 2004 to present.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">She added that Dr. Japos was&nbsp;the face behind many symposia, conferences, and others in which most of his talks centered on the management of scientific journal publications, Research Excellence Current Trends in Research, Internalization of the Philippine Higher Education Research, Scientific writing for online and printed refereed journals, quantitative and qualitative researches among others.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">During the actual seminar-workshop, Dr. Japos staged different activities wherein the participants eagerly partook. First activity is simulating interview with conversational partners, and the second is rich-detailed description of the person sitting next to the other. In the end, Dr. Japos has impregnated the participants with new insights and avalanche of information which made them look forward for their forthcoming research endeavors.</span></span></span></p>', 'Dr. Japos.jpg', 'Phebe Q. Menil', NULL, 'news', 1, '2017-07-20 09:28:49', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-c0db-4b15-b10e-8460cde2c033', 'Dr. Estal puts premium to excellence and quality', 'dr-estal-puts-premium-to-excellence-and-quality', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">Dr. Estal articulated that it is with great expectations that through the concerted efforts of the faculty researchers, the University will become a leading University that puts premium to excellence and quality during his talk on the second day (July 13, 2017) of the Qualitative seminar-workshop.&nbsp;</span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">Dr. Estal articulated that it is with great expectations that through the concerted efforts of the faculty researchers, the University will become a leading University that puts premium to excellence and quality during his talk on the second day (July 13, 2017) of the Qualitative seminar-workshop.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">He also reiterated that research is one of the determinants of SDSSU to maintain the University status; thus, he strongly encouraged that research culture should be viewed as a way of life.&nbsp;</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">Qualitative research as a method not often explored made the President hard-pressed the Research and Development Unit to look for the experts who can inspire faculty&nbsp;researchers to traverse the road less travelled. With the guidance of Dr. Genaro V. Japos whom the President described as someone who never invites negativity and has always been seen as someone who exudes the value of positivism was indeed the right&nbsp;person to bring everyone into the lens of qualitative research method. The President also lauded the speaker&rsquo;s capacity to sustain the interest of the audience with his wit, humor and good-natured character.</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:#000000\">After his talk, there were several photo opportunities to highlight the participation of the different Colleges and Campuses. He also challenged the male participants with their active participation on research as they all joined him and Dr. Japos for a pose. But of course, after they had their picture taken, the female participants also claimed their all-female-participant photo opportunity with the President and the highly acclaimed speaker, Dr. Genaro V. Japos.</span></span></span></p>', 'Dr. Estal.jpg', 'Maria Lady Sol A. Suazo', NULL, 'news', 1, '2017-07-20 09:57:18', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-c29f-47d5-9c26-d562905817a6', 'Seminar-workshop, last wave', 'seminar-workshop-last-wave', '<p><span style=\"font-size:14px\"><span style=\"color:#000000\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The three-day seminar workshop on qualitative research methodology &nbsp;has ended on July 14, 2017.&nbsp;</span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"color:#000000\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><strong>The three-day seminar workshop on qualitative research methodology &nbsp;has ended on July 14, 2017.&nbsp;</strong></span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"color:#000000\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The workshop has been&nbsp;filled with learnings they call &ldquo;a-not-everyday-experience with the internationally-acclaimed speaker&rdquo;. They had activities which&nbsp;unravelled their creative minds which paved to the presentation of their outputs. The participants &nbsp;were &nbsp;overjoyed to have attended the said workshop.</span></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"color:#000000\"><span style=\"font-family:Arial,Helvetica,sans-serif\">At the last wave of the seminar-workshop, Dr. Genaro V. Japos, resource speaker, Dr. Baceledes R. Estal, university president, research and development personnel took pictures together with the SDSSU faculty and non-teaching personnel researchers of the seminar-workshop.</span></span></span></p>', 'lastwave.jpg', 'Michal M. Agudo', NULL, 'news', 1, '2017-07-20 10:26:22', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-c4fc-4a8a-8469-cc94678c0cd3', 'Seminar-workshop final day', 'seminar-workshop-final-day', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Seminar-workshop on Dummy Tables and Simulated Data reached its final day on July 31, 2017.</span></span></p>', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Seminar-workshop on Dummy Tables and Simulated Data reached its final day on July 31, 2017. </span></span></p>\n          \n          <p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">With the threeday seminar-workshop, faculties were filled with information and learnings that they may use as guide in their path as a faculty researcher. Impression from them such as &ldquo;great and wonderful training&rdquo; marked the success of the said training.</span></span></p>\n          \n          <p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Maria Lady Sol A. Suazo expressed her grateful thanks to the speaker for his incomparable knowledge shared as well as to those participative and intelligent faculties who attended the seminar. Dr. Padua also reminded everyone that the goal is to produce an output for publication; hence, he stressed that the identified faculty researchers should&nbsp;be able to finish the entire stretch of the Training-workshop with him to&nbsp;<br />\n          be able to produce the intended deliverables for their respective SUCs.</span></span><br />\n          &nbsp;</p>', NULL, 'Flordeliza P. Torrico', NULL, 'news', 1, '2017-12-06 15:14:35', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-c709-4c23-b5b5-af0015682740', 'SDSSU Conducts Intensive Training-Workshop On GIS', 'sdssu-conducts-intensive-training-workshop-on-gis', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">A Balik-Scientist of DOST from Oklahoma State University, Dr. Alejandro Tongco was invited by SDSSU to give the identified SDSSU faculty members an intensive training workshop on Geographic Information System from July 7-11, 2017 at the Old Library of SDSSU-Main Campus.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\"><strong>A Balik-Scientist of DOST from Oklahoma State University, Dr. Alejandro Tongco was invited by SDSSU to give the identified SDSSU faculty members an intensive training workshop on Geographic Information System from July 7-11, 2017 at the Old Library of SDSSU-Main Campus.&nbsp;</strong></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">On its first day, Dr. Baceledes R. Estal, SUC President II, articulated that SDSSU is committed in its goal to achieve quality education, thus, his unrelenting emphasis was to strengthen the research &nbsp;capability of the SDSSU faculty who are expected to produce quality outputs focused on the mandates of the University.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">The GSIS training workshop which is one of the targeted research activities for the year was conducted to introduce GIS technologies to SDSSU administrators, faculty, researchers and extension planners with the intention of equipping the academic community with the fundamental GIS skills to assist in adding value to their researches and projects.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">The objectives for the said activity covered the following: Acquire fundamentals of GIS and basic GIS software skills and Incorporate fresh ideas for research and instructional development purposes; thus, the participants&nbsp;were challenged to produce a mini GIS project as the very culmination of the training-workshop.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">The rest of the week proved to be hellacious for all the participants as they strived to complete the GIS manual prepared by DR. Tongco which came in handy when they started preparing the Mini GIS-project.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">During the entire workshop, Dr. Tongco&nbsp;kept track on the progress of each participant with a score board to ignite motivation on their end. On its last stretch, the University President joined the group again to witness the presentation of outputs where he informed everyone that research fund will be granted to those outputs which will be relevant to the University and will pass the evaluation process.&nbsp;</span></span></p>', NULL, 'Maria Lady Sol A. Suazo', NULL, 'news', 1, '2017-12-06 15:27:05', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-c91b-49cf-8883-104a7939305d', 'Proposed Research Agenda finalized', 'proposed-research-agenda-finalized', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">In cognizance of the researchers to be guided on research tracks of the University Vision, the Research office together with the expertise of Dr. Roberto N. Padua finalized the research agenda held at Sea Hoi Beach Resort, Lianga, Surigao del Sur last August 28- 29, 2017.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">In cognizance of the researchers to be guided on research tracks of the University Vision, the Research office together with the expertise of Dr. Roberto N. Padua finalized the research agenda held at Sea Hoi Beach Resort, Lianga, Surigao del Sur last August 28- 29, 2017.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The two-day activity was participated by all Research Heads and Research Coordinators of the six (6) campuses of the University. Present also in the said huddle was the ITSO Manager Sir Reinar Acevedo and the SDSSU Multidisciplinary Journal EIC, Dr. Anamarie Acevedo. It started with an opening program where the OIC Director for Research and Development, Dr. Maria Lady Sol A. Suazo presented the Key Result Areas and the research themes identified by the faculty, stakeholders and students during the Research Agenda consultations conducted prior to the finalization. Dr. Roberto N. Padua, former CHED Commissioner, commented on the presentation; he suggested that research agenda will be anchored on the University Vision and strategies should be framed as its roadmap.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Presentation of outputs followed by group and ended up with the finalized&nbsp;research themes based on the agenda formulated that covers the four (4) focal areas namely; a.) food security, b.) poverty alleviation, c.) renewable energy and d.) interaction on natural environment, e. other disciplines representing the flagship program of the University.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Participants were steered up for the improvement of the Research and Development endeavors for the agenda finalization of the University.</span></span></p>', NULL, 'Jennilyn C. Doloriel', NULL, 'news', 1, '2017-12-06 15:45:04', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-cb98-4db1-913c-2b48ac13c508', 'Dr. Padua Encourages Faculty To Scientifically Describe Data', 'dr-padua-encourages-faculty-to-scientifically-describe-data', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Research and Development Office spearheaded the Seminar-workshop on Basic Data Analysis at Sea hoi Beach Resort, Lianga, Surigao del Sur on August 30, September 1, 2017.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Research and Development Office spearheaded the Seminar-workshop on Basic Data Analysis at Sea hoi Beach Resort, Lianga, Surigao del Sur on August 30, September 1, 2017.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On its first day, Dr. Roberto N. Padua talked about the &ldquo;Central Limit Theorem and Data Description&rdquo;. He stressed that increasing the sample sizes of data leads to closer value on actual distribution.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">During the actual workshop, participants generated re-sampling of data using the Minitab software and presented their outputs to the resource speaker for his comments and suggestions.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On its finale, Dr. Padua challenged everyone to be analytical in analyzing data set and be able to produce publishable research using the different statistical methods.</span></span><br />\n          &nbsp;</p>', NULL, 'Flordeliza P. Torrico', NULL, 'news', 1, '2017-12-06 15:50:17', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-cd4f-4884-9bc6-4f9c78185d55', 'Dr. Lopez Presents Output', 'dr-lopez-presents-output', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On the second day of the seminar, Dr. Padua evaluates the outputs of the participants.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On the second day of the seminar, Dr. Padua evaluates the outputs of the participants.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU researcher Dr. Edmundo C. Lopez emphasized during his presentation that the teacher&rsquo;s competence in instruction is directly proportional to their affective competence.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">He defined that instruction is the ability of the teacher to teach the students, while affective is the ability to build relationship with the students and parents.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Padua stressed that the diversity of instructional competence of the teachers is needed for effective and quality education.</span></span></p>', NULL, 'Flordeliza P. Torrico', NULL, 'news', 1, '2017-12-06 15:54:11', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-cf41-4f86-8e9a-fefcac561078', 'Dr. Padua talks on Man as a Social Atom', 'dr-padua-talks-on-man-as-a-social-atom', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On Oct. 18-20, 2017, Dr. Roberto N. Padua was invited as resource speaker for the Seminar-workshop on Man as a Social Atom at Lianga, Surigao del Sur.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><strong>On Oct. 18-20, 2017, Dr. Roberto N. Padua was invited as resource speaker for the Seminar-workshop on Man as a Social Atom at Lianga, Surigao del Sur.&nbsp;</strong></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On its first day, he emphasized on his lecture the concept of Complex Adaptive System, which according to him, adaptation occurs when there is learning from each other and changing of strategy for survival. Further, he defines innovation as producing new things out of the old ones and an anticipation with action changes the system.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">On the last day of the seminar-workshop, participants submitted their outputs subject for the comments and evaluation of the speaker. He encouraged the participants to produce a publishable paper so that they can utilize the knowledge they gained from his input and have it disseminated to the wider academic community.</span></span></p>', NULL, 'Research And Development Office', NULL, 'news', 1, '2017-12-06 16:25:58', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-d17a-466e-8e61-53c714c7dcc1', 'SDSSU applies for Balik Scientist Program of DOST', 'sdssu-applies-for-balik-scientist-program-of-dost', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">As an initiative of the Philippine government for its growth and expansion necessities, the Balik Scientist Program (BSP) of the Department of Science and Technology (DOST) was established which seeks to encourage highly-trained overseas Filipino scientists and technologists, experts, and professionals to return to the Philippines and share their expertise for the hastening of the scientific, agro-industrial and economic development of the country.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><strong>As an initiative of the Philippine government for its growth and expansion necessities, the Balik Scientist Program (BSP) of the Department of Science and Technology (DOST) was established which seeks to encourage highly-trained overseas Filipino scientists and technologists, experts, and professionals to return to the Philippines and share their expertise for the hastening of the scientific, agro-industrial and economic development of the country.&nbsp;</strong></span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">To this effect, SDSSU has taken advantage of this opportunity. It has particularly eyed Dr. Alejandro F. Tongco for his expertise on Geographic Information System.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">As a premier Higher Education Institution, SDSSU is hard-pressed to advance scientific research that promotes economic progress and environmental sustainability in the Province of Surigao del Sur. However, SDSSU is technologically-disadvantaged because it is geographically dispersed.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">In its endeavor to build a capable lineup of scientific researchers and its desire to keep abreast with modern and innovative technologies to empower itself with emergent analytical techniques, SDSSU is applying for DOST&rsquo;s Balik Scientist Program, specifically on geographic information system.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Tongco, a GIS research specialist formerly with Oklahoma State University, possesses advanced technical skills in GIS and substantial experience in the academe. With this undertaking, it is highly deemed that SDSSU will be able to add more value on its research undertakings for the development needs of the Institution and the Provinces as a whole.</span></span></p>', NULL, 'Maria Lady Sol A. Suazo', NULL, 'news', 1, '2017-12-06 16:31:55', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-d3ae-48b4-b335-b069d91a6d58', 'Faculty Researchers sent to Regional, National and International Conferences', 'faculty-researchers-sent-to-regional-national-and-international-conferences', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">As a manifestation of support to the faculty researchers and as a means to attain its target in terms of research presentation, the University sent a number of faculty-researchers to various research conferences.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\"><strong>As a manifestation of support to the faculty researchers and as a means to attain its target in terms of research presentation, the University sent a number of faculty-researchers to various research conferences</strong>. Both the seasoned and new breed of researchers were able to take advantage of the opportunity to disseminate their research outputs to the various fora in the regional, national and international platforms. During the Annual Regional Research Conference 2017 on September 27-29, 2017 at Almont Beach Resort, Lipata, Surigao City, Jennilyn C. Doloriel presented Service Delivery of Sectarian Nursery Schools in Surigao del Sur; Chiara Angela C. Quico &ndash; The Management of Beach Resorts in Surigao del Sur; and Castor V. Balacuit &ndash; Implementation of 4P&rsquo;s in Basic Education. On October 5-7, 2017 during the 5th International Conference on Multidisciplinary Research, at Planta Centro Bacolod Hotel and Residences, Maria Cristina Dela Cerna presented Speech Ability of Grade 10 Students and Mardie E. Bucjan, Morphophonemic Analysis of Kamayo Language in Surigao del Sur.</span></span></p>', '22007828_1661652533886779_5485047047075231482_m.jpg', 'Joyjoy Montenegro', NULL, 'news', 1, '2017-12-06 16:46:52', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-d5c0-472e-8f9b-371e34f02193', 'A Ritual: Lighting, Guiding the Profession of Selfless Service', 'a-ritual-lighting-guiding-the-profession-of-selfless-service', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Nightingale lamp is a symbol of care and devotion. In this ritual, the candidates are being a part of the sisterhood and brotherhood of midwives.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Nightingale lamp is a symbol of care and devotion. In this ritual, the candidates are being a part of the sisterhood and brotherhood of midwives.&nbsp;</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">September 13, 2017 at the Audio Visula Center at exactly 1:00p.m. it marks the 10th Candle Lighting Ceremony of the Surigao del Sur State University-main Campus of the Diploma in Midwifery Program in this ritual, the Nightingale lamp was lighted as a symbol of care and devotion as the students steeped into becoming advanced practiced midwives and started taking the&nbsp; path of selfless service. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Efrie Shella E. Laguesma-Arreza,the midwifery principal from Adela Serra Ty Memorial Medical Center (ASTMMC) inspire the future midwives that as they enter into clinical and community they must possess &quot;the hand of a lady, the eyes of a hawk and the eyes of a lion to achieve greater&nbsp; heights in their personal and professional careers, because their service will help make this world a better place.&quot;</span></span></p>\n          \n          <p>&nbsp;</p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-09-15 14:02:08', '2023-02-14 03:49:11', '2023-02-14 03:49:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('987727bb-d933-4fbd-bcd1-1c28b6f4d7d0', 'Strengthening Social Responsibility: Celebrating Ancestry', 'strengthening-social-responsibility-celebrating-ancestry', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">September 19, 2017 is the Araw ng Surigao del Sur it is an annual celebration of the&nbsp; province where each municipality participated in various activities.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">September 19, 2017 is the Araw ng Surigao del Sur it is an annual celebration of the&nbsp; province where each municipality participated in various activities. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The College of Arts and Sciences Faculty and Students&nbsp; represented the Surigao del Sur State University during the opening parade. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The agro-business fair highlighted the celebration&nbsp; as each municipality showcase and design their booths with peculiar agri-products from their municipality. The attendance of Surigao del Sur State to this event strengthens the social responsibility to our unique ancestry and love for the province of Surigao del Sur. </span></span></p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-09-22 14:07:54', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-db90-4dcf-bc2c-01698aa0e780', 'SDSSU :A Family of Unity', 'sdssu-a-family-of-unity', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Family is where love, kindness, generosity and tolerance are first expressed. </span></span><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Last September 29-30 ,2017 SDSSU adheres to the CSC mandate of valuing each and every member of the organization as we strengthen our family.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Family is where love, kindness, generosity and tolerance are first expressed. </span></span><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Last September 29-30 ,2017 SDSSU adheres to the CSC mandate of valuing each and every member of the organization as we strengthen our family. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Sarnimian Inland Resort at Brgy Rosario, Agusan Surigao del Norte witnessed&nbsp; how the key officials, faculty and staff shared their one vision to the goal of the university. The venue was filled with laughter&#39;s as each college energetically participated&nbsp; to&nbsp; yells and songs contest, dance contest , Ms. G Hilarious and many other activities. </span></span><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The university presidents, Dr. Baceledes R. Estal&nbsp; highlighted the essence of being brothers and sisters in an organization. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Truly, SDSSU is not just a place where excellence belongs but also where unity resides. </span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-10-02 14:15:55', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-dd9a-491a-be05-fbb9f9ccfa4a', '3rd FDU and ADCO-ACO Meeting', '3rd-fdu-and-adco-aco-meeting', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The 3rd FDU and ADCO-ACO was conducted at Licanto Beach Resort, Barobo Surigao del Sur last&nbsp; Sept. 20, 2017.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The 3rd FDU and ADCO-ACO was conducted at Licanto Beach Resort, Barobo Surigao del Sur last&nbsp; Sept. 20, 2017. The meeting addressed important matters particularly on budget presentations. This becomes as well an avenue of camaraderie among the faculty and staff of Surigao del Sur State University</span></span></p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-09-25 14:51:14', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-dfea-44e6-95a7-11c6f94d7ba7', 'Communication is the Key', 'communication-is-the-key', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">While the Level III Phase II of Accreditation for the Program BA English, BS Mathematics and BS Public Administration is at scheduled on November 20,2017 the College of Arts and Sciences gave ample amount to discuss important matters in preparation for the activity.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">While the Level III Phase II of Accreditation for the Program BA English, BS Mathematics and BS Public Administration is at scheduled on November 20,2017 the College of Arts and Sciences gave ample amount to discuss important matters in preparation for the activity.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Dean, Dr. Romeo A. Patan always sees to it that the Program Chairs and committees assigned to the task were able to express the updates on script writing and movie making. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Each program aims to passed the accreditation and communication plays an important role of the task at hand.&nbsp; </span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>\n          \n          <p>&nbsp;</p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-11-24 14:54:59', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-e4dd-4256-a6ee-1086665c9968', 'Unearth the Leaders Within', 'unearth-the-leaders-within', '<p><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">Youth of today are the leaders of the future.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">Youth of today are the leaders of the future. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">The College of Arts and Sciences&nbsp; College Dean, dr. Romeo A. Patan conducted a semester &ndash;end meeting with the League of Arts and Sciences Students&nbsp; (LASS) at the Deans Office last September 22,2017. The LASS officers gave updates on the events of the first semester and plans to be implemented on the second semester. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\">It is the aim of the college to empower young officers to become responsible on their obligations&nbsp; and responsibilities entrusted by the college. </span></span></p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-09-25 15:19:02', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-e75e-4daa-8fd2-37ee5241e5c1', 'TRES MARIA’S LIVE IN SDSSU', 'tres-marias-live-in-sdssu', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">TRE&rsquo;S MARIAS is an all female band from Luzon of which songs composed are for patriotism and environmental awareness.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">TRE&rsquo;S MARIAS is an all female band from Luzon of which songs composed are for patriotism and environmental awareness.&nbsp;</span></span><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Last September 17, 2017, SDSSU Gymnasium was the avenue of the benefit concert for Marawi. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The proceeds of the concert will benefit the people of Marawi who were affected by the ongoing war between the government and the Maute terrorist group.&nbsp;</span></span><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The venue was filled by people from different municipalities who eagerly show their support for the benefit concert. </span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>', NULL, 'College of Arts and Sciences', NULL, 'news', 1, '2017-09-20 15:23:53', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-e9a6-4c9e-80f7-86030b498b43', 'Curriculum Development Office Made Steps Forward', 'curriculum-development-office-made-steps-forward', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Director for Curriculum Development Dr. Evelyn T. Bagood went benchmarking at WVSU, Ilo-ilo City with the Vice President for Administration and Finance Dr. Florife O. Urbiztondo to gather significant information in the university&rsquo;s proposal to offer Doctor of Medicine. </span></span></p>', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Director for Curriculum Development Dr. Evelyn T. Bagood went benchmarking at WVSU, Ilo-ilo City with the Vice President for Administration and Finance Dr. Florife O. Urbiztondo to gather significant information in the university&rsquo;s proposal to offer Doctor of Medicine. West Visayas State University gave all the necessary information and toured the two bench markers to their infrastructures in the College of Medicine.</span></span></p>\n          \n          <p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">After the benchmarking on Doctor of Medicine at WVSU, the Curriculum Director reported and proposed the project work plan of offering Doctor of Medicine to the Board of Regents in Manila BOR meeting July 10, 2017. The Board of Regents signalled a nod on the presented proposal.</span></span></p>\n          \n          <div class=\"col-md-1\">&nbsp;</div>\n          \n          <div class=\"col-md-10\"><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/the%20Curriculum%20Director%20reported%20and%20proposed%20the%20project%20work%20plan.jpg\" style=\"float:left; width:500px\" /></div>\n          \n          <div class=\"col-md-1\">&nbsp;</div>', 'image.jpg', 'Curriculum Development Office', NULL, 'news', 1, '2017-07-17 15:36:21', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-eca4-4516-8169-b281ac402cf8', 'Reviews And Revisions Of Curriculum And Manuals', 'reviews-and-revisions-of-curriculum-and-manuals', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Office of the Curriculum Development under the Director has collaborated with College of Engineering, Computer Studies and Technology, College of Business Management.</span></span></p>', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Office of the Curriculum Development under the Director has collaborated with College of Engineering, Computer Studies and Technology, College of Business Management in the Curriculum Review and Revision together also with College Manual Revisit. The conduct was of course under the leadership of VP Gerry B. Estrada.</span></span></p>', 'REVIEWS AND REVISIONS OF CURRICULUM AND MANUALS.jpg', 'Curriculum Development Office', NULL, 'news', 1, '2017-08-23 11:57:34', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-eeca-4169-9792-e75203edf247', 'SDSSU President and Campus Director attend UMAP Forum in Japan', 'sdssu-president-and-campus-director-attend-umap-forum-in-japan', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Aligned to the pursuit of internationalization among state colleges and universities, the University President Dr. Baceledes R. Estal and the Campus Director of SDSSU&ndash;Lianga Dr. Cynthia P. Sajot attend the forum organized by the University Mobility in Asia and the Pacific (UMAP) as part of the GO and NGO delegation of the Philippines at Toyo University, Japan in August 17&ndash;19, 2017.&nbsp;</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Aligned to the pursuit of internationalization among state colleges and universities, the University President Dr. Baceledes R. Estal and the Campus Director of SDSSU&ndash;Lianga Dr. Cynthia P. Sajot attend the forum organized by the University Mobility in Asia and the Pacific (UMAP) as part of the GO and NGO delegation of the Philippines at Toyo University, Japan in August 17&ndash;19, 2017.&nbsp; UMAP has been operational for 25 years in 570 universities from 35 countries to achieve better understanding of the cultural, economic and social system and backgrounds of each university and country.&nbsp; </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The International Forum 2017 theme is &ldquo;Trends and Prospects of Student Mobility and Support in the Asia Pacific Region&rdquo; promotes mobility of faculty and staff who would nurture future global leaders.&nbsp; Students are encouraged to study abroad in modes of scholarship, observer, visiting student and the like, the exposure of which are best venues for learning skills, in new and different cultures and languages to promote instructional exchange.</span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>', NULL, 'SDSSU-Lianga Campus', NULL, 'news', 1, '2017-10-27 13:11:00', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-f189-40e9-895b-aa39c925eb3d', 'Faculty and Staff of SDSSU-Lianga Observes Family Day In Celebration of 117th Philippine Civil Service Anniversary', 'faculty-and-staff-of-sdssu-lianga-observes-family-day-in-celebration-of-117th-philippine-civil-service-anniversary', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">In line with the 117<sup>th</sup> Philippine Civil Service Anniversary, the SDSSU-Lianga Campus celebrates the Family Day at Big Times Beach Resort on September 29, 2017 with the theme: &ldquo;Tugon sa Hamon ng Pagbabago: Malasakit ng Lingkod Bayani&rdquo;.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">In line with the 117<sup>th</sup> Philippine Civil Service Anniversary, the SDSSU-Lianga Campus celebrates the Family Day at Big Times Beach Resort on September 29, 2017 with the theme: &ldquo;Tugon sa Hamon ng Pagbabago: Malasakit ng Lingkod Bayani&rdquo;.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The highlight of the activities is the family delights and surprises contested by the different department of the Campus. The team building activity is eagerly sustained through enthusiastic participation of faculty and staff.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The University President expresses his gratitude to SDSSU- Lianga Campus for the outstanding contribution of the University accomplishments in local, national and international level and further encourage to do the right to better serve the people towards development. He ends his talk by presenting the plaque of recognition being rank 6<sup>th</sup> in the ARTA implementation mandated by the Civil Service Commission.</span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>', NULL, 'SDSSU-Lianga Campus', NULL, 'news', 1, '2017-10-27 13:50:24', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-f4a8-4d89-b64d-286734170660', 'CAS Faculty Joins International Presentations For Environmental Researches', 'cas-faculty-joins-international-presentations-for-environmental-researches', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Two poster presentations titled &ldquo;Establishment of Coastal Mangrove Greenbelt through Community-Based Efforts in Lianga Bay, Surigao del Sur, Philippines&rdquo; and &ldquo;Sustainable Fisherfolk&rsquo; Environmental Actions.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Two poster presentations titled &ldquo;Establishment of Coastal Mangrove Greenbelt through Community-Based Efforts in Lianga Bay, Surigao del Sur, Philippines&rdquo; and &ldquo;Sustainable Fisherfolk&rsquo; Environmental Actions: It&rsquo;s Promise to Resource Generation and Livelihood Opportunities&rdquo; by Dr. Bernardita G. Quevedo, Dr. Merlina D. Aparta and Mr. Fabio C. Ruaza to the 10<sup>th</sup> Philippine Network of Environmental Educators on October 24-26, 2017 at Tarlac City Agricultural University, Tarlac City&nbsp; has the latter judged as one of the top 10 presentations among the poster and paper presentations participated by the 158 participants from 76 state universities and colleges.</span></span></p>', NULL, 'SDSSU-Lianga Campus', NULL, 'news', 1, '2017-10-27 13:57:13', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-f701-4725-8968-8264720b69f3', 'AACCUP Accredits BSIT &amp; BSHRM Programs', 'aaccup-accredits-bsit-amp-bshrm-programs', '<p style=\"text-align:justify\">The Surigao del Sur State University-Cagwait Campus through the leadership of its campus director, Dr. Noelito B. Salcedo and the support and cooperation of its faculty, staff and students once again accepted the challenges for accreditation process conducted by Accrediting Agencies for Chartered Colleges and Universities of the Philippines, Inc. (AACCUP) on September 4-7, 2017.</p>', '<div>\n          <p><img alt=\"\" class=\"img-responsive\" src=\"/public_files/images/accreditation.jpg\" /></p>\n          \n          <p style=\"text-align:center\"><span style=\"font-size:12px\"><em><strong>Focal Persons and IAB Members took pose together with the AACCUP Accreditors</strong></em></span></p>\n          \n          <p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Surigao del Sur State University-Cagwait Campus through the leadership of its campus director, Dr. Noelito B. Salcedo and the support and cooperation of its faculty, staff and students once again accepted the challenges for accreditation process conducted by Accrediting Agencies for Chartered Colleges and Universities of the Philippines, Inc. (AACCUP) on September 4-7, 2017. Dr. Marcelina O. Bahalla (USM) was the Over-all Coordinator, Engr. Eulogio D. Apellido, Jr. (SKSC) as BSIT Coordinator, Dr. Julieta S. Abarquez (DNSC) as BSHRM Coordinator, Dr. Charima M. Mentoc (CFCST), Prof. Evelyn J. Lumaday (DNSC), Prof. Ariel T. Ortiz (MSU-GenSan), Dr. Teresita&nbsp; B. Bayaron (DNSC) and Dr. Winda B. Cejas (USEP) as Members. Bachelor of Science in Industrial Technology-(BSIT) which has the following majors; Automotive Technology, Computer Technology and Electrical Technology&nbsp; was evaluated for AACCUP Accreditation Level II and its Bachelor of Science in Hotel &amp; Restaurant Management (BSHRM) was also for Level I. After the evaluation and assessment of documents conducted, feed backing and mentoring were done during the exit conference held at the Accreditation Room. From the important and fruitful points and suggestions imparted, Dr. Noelito B. Salcedo thanked all the accreditation and mentoring team for exerting efforts and relevant information and guidelines in improving the campus curricular programs.</span></span></p>\n          </div>', NULL, 'SDSSU-Cagwait Campus', NULL, 'news', 1, '2017-09-29 14:12:57', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-f9ad-43e9-8e7e-6f16581e1203', 'SDSSU Alumni Federation President : SDSSU Cagwait’s Pride', 'sdssu-alumni-federation-president-sdssu-cagwaits-pride', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">CCHS/CMHS/CSAT/SSPC/SSPSC/SDSSU Cagwait Campus Alumni President, Dr. Ponciano Alngog was elected as the Alumni Federation President and a new member of the Board of Regents of the SDSSU System.</span></span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:14px\"><span style=\"color:black\">CCHS/CMHS/CSAT/SSPC/SSPSC/SDSSU Cagwait Campus Alumni President, Dr. Ponciano Alngog was elected as the Alumni Federation President and a new member of the Board of Regents of the SDSSU System. He sworn into office on September 28, 2017 at Royal Mandaya Hotel, Davao City before the BOR Members and others university key officials. The campus administration, faculty, staff and students expressed their congratulations and best wishes for Dr. Alngog for bringing the good name and pride of the campus.</span></span></span></p>', NULL, 'Daniemar Gualvez', NULL, 'news', 1, '2017-10-02 14:25:01', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-fc0a-46fd-b05e-dd1fa7c18f0f', 'SDSSU Cagwait Joins MASTS 2017', 'sdssu-cagwait-joins-masts-2017', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Local Sports and Literary Cultural Competitions of Mindanao Association of State Tertiary Schools, Inc. (MASTS) were held on October 4-6, 2017 at Surigao del Sur State University (SDSSU)- Lianga Campus, Lianga, Surigao del Sur.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Local Sports and Literary Cultural Competitions of Mindanao Association of State Tertiary Schools, Inc. (MASTS) were held on October 4-6, 2017 at Surigao del Sur State University (SDSSU)- Lianga Campus, Lianga, Surigao del Sur. Being one of the satellite campuses, SDSSU Cagwait has sent student participants who competed with the athletes and participants from other SDSSU Campuses in various events like Volleyball, Beach Volleyball, Sepak Takraw, Badminton, Table Tennis, Chess, Dance Sports, Vocal Solo, Duet, Choral Singing, Pagsulat ng Sanaysay, Pagkukuwento, Dagliang Pagtatalumpati, Essay Writing, Storytelling and Quiz Bowl. Players in Beach Volleyball Men got gold and will be representing the university in the Regional MASTS Sports Competition on December 2017. Indeed, the university administration, faculty, staff and students were very happy and grateful for the success of the university&rsquo;s participation in the said athletics and literary cultural competitions.</span></span></p>', NULL, 'Karla Mae Alvarado, Cagwait Campus', NULL, 'news', 1, '2017-10-27 14:37:01', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bb-fe80-4181-ad53-122705941eb7', 'SDSSU LITERARY CONTEST WHIPS INTO SHAPE', 'sdssu-literary-contest-whips-into-shape', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The SDSSU Cantilan Campus Literary Competition was bashed and currently held on September 14, 2017 at SDSSU Audio Visual Center at 8:00 am to 12:00 noon. With the theme: PASUC at 50: At the forefront of Global Dynamics of Public Higher Education.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The SDSSU Cantilan Campus Literary Competition was bashed and currently held on September 14, 2017 at SDSSU Audio Visual Center at 8:00 am to 12:00 noon. With the theme: PASUC at 50: At the forefront of Global Dynamics of Public Higher Education.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The English Society Officers together with their adviser led the said event. The activity commenced with an invocation and the singing of National Anthe. Followed by the welcome address by Ms. Geraldine Naga, MAELT, the English Society Adviser.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Thereafter is the reading of mechanics and criteria for the different types of competition followed namely: Story Telling, Short and Sweet Plays, Radio Drama, Essay Writing and the Extemporaneous Speech next is the introducing of the board of judges. After the thorough contest, Mr.Junry Fortugaliza, the English Society President delivered his closing remarks. Right after is the proclamation of winners.</span></span></p>', NULL, 'SDSSU-Cantilan Campus', NULL, 'news', 1, '2017-09-29 15:01:39', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-0073-483f-b6c2-8688797bfe44', 'SDSSU-Cantilan Garners 2nd Runner-up in Bonok-Bonok Festival', 'sdssu-cantilan-garners-2nd-runner-up-in-bonok-bonok-festival', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU-Cantilan represents LGU-Cantilan at Surigao City on its Bonok-Bonok Festival. One of their highlights of Surigao City annual fiesta celebration every September 9-10.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU-Cantilan represents LGU-Cantilan at Surigao City on its Bonok-Bonok Festival. One of their highlights of Surigao City annual fiesta celebration every September 9-10. The school after representing Sirong Festival proceeded to Surigao City for the same purpose on September 7, 2017 to join the Bonok-Bonok Festival on September 9, 2017.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">This years theme for its festival was &ldquo;Surigao: Sadjawpara sa Kalinaw&rdquo; gives inspiration to the performers to do their very best. In the morning of September 9,2017 one was the street dancing activity where participants rhythmically moved to the beat of the sounds of drums, buggles, and other instruments synchronized into music. SDSSU-Cantilan students together with other participants chant &ldquo;Viva Senor San Nicolas De Tolentino&rdquo; Viva, Viva, Viva.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">There were two categories for a competition to choose,first was the Bonok-Bonok Base and the second was the Free Interpretation SDSSU-Cantilan competes in the Free Interpretation Category.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Grand Showdown Competition starts at exactly 1:00 o&rsquo;clock in the afternoon and it ends at exactly 8:00 o&rsquo;clock in the evening where SDSSU-Cantilan won as <strong>2<sup>nd</sup> runner up </strong>in the rank. Whether it failed to win, the most important thing is that SDSSU&rsquo;ans proved that they can be competitive and they are proud to show and share their talents. KUDOS SDSSUans! KUDOS!</span></span></p>', NULL, 'SDSSU-Cantilan Campus', NULL, 'news', 1, '2017-09-29 15:04:06', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-02c8-418e-b9a1-8c8dfb5680e8', 'EDUCATORS’ NIGHT Sponsored By DepEd Cantilan, LGU And SDSSU', 'educators-night-sponsored-by-deped-cantilan-lgu-and-sdssu', '<p><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">More often than not, educators are underappreciated or undervalued.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">More often than not, educators are underappreciated or undervalued. The Educators&rsquo; Night reminds us that although we can acquire knowledge by studying on our own, our competent teachers play very significant roles in molding us into productive members of the society. Great teachers indeed contribute partly to who we are today or who we become in the future.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">SDSSU President Dr. Baceledes R. Estal, in his speech of appreciation,&nbsp; commends our teachers for taking on one of the most challenging and fulfilling professions of all time. The tireless efforts of our educators&nbsp; have not gone unnoticed and applause is in order for the teachers&rsquo; unwavering commitment in shaping the minds of the youth and guiding them to their full potential. </span></span></p>\n          \n          <p>&nbsp;</p>', NULL, 'Office Of The President', NULL, 'news', 1, '2017-08-18 15:13:12', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-04e1-48a5-b0f9-bf5649c89b7b', 'PROVINCIAL ADVISORY COUNCIL', 'provincial-advisory-council', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The PNP, in its efforts to reduce criminality among the populace has cooperated with the various subdivisions of the society namely the media, educational institutions, the church and the business sector.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The PNP, in its efforts to reduce criminality among the populace has cooperated with the various subdivisions of the society namely the media, educational institutions, the church and the business sector. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Statistical data was presented to shed light on the correlation of the rise of criminality in Surigao del Sur with the major societal problems such as poverty and drug abuse. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">It is therefore the role of SDSSU, as one of the partners of the PNP in this initiative,&nbsp; to impart education and awareness upon the youth regarding the effects or consequences of committing crimes and the measures to be done to prevent or avoid the commission thereof.</span></span></p>', NULL, 'Office Of The President', NULL, 'news', 1, '2017-08-18 15:16:39', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-074f-4d98-8bb5-f9e733949bb2', 'Acquaintance Party And Oath-Taking Ceremony (Faculty Club)', 'acquaintance-party-and-oath-taking-ceremony-faculty-club', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">A great foundation of education requires great teachers. Teachers are the ones that give our students the tools to attain success in both their personal lives and in their future careers.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">A great foundation of education requires great teachers. Teachers are the ones that give our students the tools to attain success in both their personal lives and in their future careers. The goal of SDSSU is to provide its students not only with academic enrichment but also life skills.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Faculty Club has organized this event to&nbsp; welcome all the newly-hired members of the faculty of SDSSU&nbsp; and to commend the dedicated efforts of the existing members of the faculty. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Teaching is an adventure.&nbsp; SDSSU teachers work to make a positive difference the lives of your students and in the society. to the variety of learners that are in your care and guidance.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Dr. Baceledes R. Estal graced the event with an inspirational message to encourage everyone to work together to live up to the mission and vision of the university.</span></span></p>\n          \n          <p style=\"text-align:justify\">&nbsp;</p>', NULL, 'Office Of The President', NULL, 'news', 1, '2017-08-18 15:22:56', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-09c0-4eb6-bb92-ede337caad4d', 'SIRONG FESTIVAL', 'sirong-festival', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Sirong Festival is about commemorating that portion of Cantilan&rsquo;s history where early Christians had to defend themselves against the raids perpetrated by Islamized natives or muslims, then called the Spaniards as Moors or Moros.</span></span></p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Sirong Festival is about commemorating that portion of Cantilan&rsquo;s history where early Christians had to defend themselves against the raids perpetrated by Islamized natives or muslims, then called the Spaniards as Moors or Moros. </span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Sirong, while it may refer to a particular action such as fencing and escrima, has, metamorphosed into the Cantilangnon&rsquo;s continuing search for its destiny as a people; and every festival is testament to that journey.</span></span></p>\n          \n          <p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Anent to the occasion, Dr. Baceledes R. Estal had the honor to deliver the Welcome Address to commemorate part of Cantilan&rsquo;s history.</span></span></p>', NULL, 'Office Of The President', NULL, 'news', 1, '2017-08-30 15:27:39', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-0ddd-43f8-8c91-d46441d7308c', 'Jesryl Dublas and Leomar Bucio Garnered Gold in the Regional MASTS 2017', 'jesryl-dublas-and-leomar-bucio-garnered-gold-in-the-regional-masts-2017', '<p>The Regional Sports Friendship Games of Mindanao Association of State Tertiary Schools, Inc. (MASTS) with the theme, &ldquo;Building a Culture of Peace and Harmony through Sports&rdquo; was held on December 10-15, 2017 at Camiguin Polytechnic State College (CPSC).</p>', '<p style=\"text-align:justify\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The Regional Sports Friendship Games of Mindanao Association of State Tertiary Schools, Inc. (MASTS) with the theme, &ldquo;Building a Culture of Peace and Harmony through Sports&rdquo; was held on December 10-15, 2017 at Camiguin Polytechnic State College (CPSC). Surigao del Sur State University (SDSSU) participated the said regional competitions, luckily, SDSSU Cagwait Campus has sent two talented and skillful Beach Volleyball (Men) athletes namely; Mr. Jesryl Dublas (BSIT 3-Automotive Technology) and Mr. Leomar Bucio (BSIT 2-Computer Technology). With the guidance of the competent coach, Engr. Ian A. Cruza and with their consistent training and determination, the two garnered gold medal and awarded as the over-all champion/1st placer which gave much honor and pride to the SDSSU team in the field of Beach Volleyball. As reward and recognition to their success , the two were exempted from the Prelim Examination as approved by the course instructors.&nbsp; Indeed, the university administration, faculty, staff and students were very happy and grateful for the success of the two talented athletes and coach that gave the University a mark on the beach volleyball field.</span></span></p>', NULL, 'SDSSU-Cagwait Campus', NULL, 'news', 1, '2018-01-11 09:28:00', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-10fd-49d8-8dec-458d1fcd922b', 'SDSSU joins Regional Meeting of OSAS', 'sdssu-joins-regional-meeting-of-osas', '<p><span style=\"font-size:11.0pt\">CHEDRO, Butuan City. The Commission on Higher Education Caraga spearheaded the Regional Meeting for All Student Services Practitioner to discuss initiatives of the CHED in strengthening student services across the region.</span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">CHEDRO, Butuan City. The Commission on Higher Education Caraga spearheaded the Regional Meeting for All Student Services Practitioner to discuss initiatives of the CHED in strengthening student services across the region. Along with the participants include NSTP Coordinators and Student Internship Program Coordinators to also ensure the implementation of CMO 104 s 2015 otherwise known as The Student Internship Program of the Philippines. </span></span></p>', '36887377_2113164872046082_8519789637093294080_o.jpg', 'Abundio C. Miralles', 32, 'news', 1, '2018-08-15 10:48:43', '2023-02-14 03:49:11', '2023-02-14 03:49:11'),
('987727bc-1407-499b-8642-b225783ec01d', 'SSG Manifest Support to the President Estal', 'ssg-manifest-support-to-the-president-estal', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Calibri&quot;,sans-serif\">The Supreme Student Government manifested their support to the term extension of Dr Baceleds R. Estal. </span></span></p>', '<p style=\"margin-left:0in; margin-right:0in\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">The Supreme Student Government manifested their support to the term extension of Dr Baceleds R. Estal. On July 28, 2018 a team to evaluate the President made an interview with the student leaders from the six campuses of the University. </span></span></p>', NULL, 'Abundio C. Miralles', 32, 'news', 1, '2018-08-15 10:32:16', '2023-02-14 03:49:11', '2023-02-14 03:49:11');
INSERT INTO `news` (`id`, `title`, `slug`, `short_description`, `content`, `photo`, `author`, `office_id`, `type`, `is_published`, `date`, `created_at`, `updated_at`) VALUES
('987727bc-17ff-49ac-8585-3cd29d2cb2d9', 'Campus Library Management Massive Acquisition of Books and Other Learning Resources', 'campus-library-management-massive-acquisition-of-books-and-other-learning-resources', '<p>A well-stocked library is essential to facilitate better student learning. As a focal access point for information, teaching, learning, and research, a college library is expected to provide standard information resources that would help the academic community members for their self-development, to fulfill the curriculum requirements, and to promote studies and research.</p>', '<table class=\"table table-bordered table-striped\">\n              <thead>\n                  <tr>\n                      <th colspan=\"3\" scope=\"col\">\n                      <p style=\"margin-right:0pt; text-align:center\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:black\"><strong>SDSSU Tandag Campus</strong></span></span></span></p>\n          \n                      <p style=\"margin-right:0pt; text-align:center\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:black\"><strong>Books Acquired for A.Y. 2018-2019</strong></span></span></span></p>\n                      </th>\n                  </tr>\n              </thead>\n              <tbody>\n                  <tr>\n                      <td>\n                      <p style=\"margin-right:0pt; text-align:center\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:black\"><strong>Program</strong></span></span></span></p>\n                      </td>\n                      <td>\n                      <p style=\"margin-right:0pt; text-align:center\"><span style=\"font-size:14px\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"color:black\"><strong>Title</strong></span></span></span></p>\n                      </td>\n            