INSERT INTO `offices` (`id`, `banner`, `code`, `name`, `slug`, `category`, `description`, `campus_id`, `created_at`, `updated_at`) VALUES
(1, 'CETS.jpg', 'CET', 'College of Engineering and Technology', 'college-of-engineering-and-technology', 'Academic', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(2, 'CITES.jpg', 'CITE', 'College of Information Technology Education', 'college-of-information-technology-education', 'Academic', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(3, 'CTE.jpg', 'CTE', 'College of Teacher Education', 'college-of-teacher-education', 'Academic', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(4, 'cas.jpg', 'CAS', 'Collge of Arts and Sciences', 'collge-of-arts-and-sciences', 'Academic', '<p>As an academic base of the university, the College of Arts and Sciences is committed to:</p>\n\n                    <ul>\n                        <li>Contribute to the progress of Caraga Region by producing specialists and high level professionals fortified with adequate knowledge and proficiency in the respective fields in social sciences, humanities, mathematics, natural and applied sciences,; governance, leadership and infused with sense of moral leadership, love of country appreciation of culture diversity and sustainable use of natural resources.</li>\n                        <li>Adhere to acceptable standards in the conduct of teaching/instruction, thriving scholarly research, community extension and outreach programs, and production activities with the end view of producing workforce in fast changing &ldquo;glocal&rdquo; work setting.</li>\n                        <li>Functions as a social laboratory that nurtures critical awareness of current/contemporary issues in both local, regional and ASEAN perspective, promote the sustainable use of natural resources for inclusive growth and effective linkage with partner agencies with the end view of quality instruction, research, publication and production.</li>\n                    </ul>', 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(5, 'cbmS.jpg', 'CBM', 'College of Business and Management', 'college-of-business-and-management', 'Academic', '<p style=\"text-align:justify\">The college will produce competent graduates imbued with ethical values and ideals in humane environment supportive to national thrust for social transformation.</p>\n\n                    <p>The College is committed to:</p>\n                    \n                    <ul>\n                        <li>Deliver quality and progressive education;</li>\n                        <li>Engaged continually in research for innovation;</li>\n                        <li>Involve in extension services and establish linkages with partner agencies and community; and</li>\n                        <li>Develop competent entrepreneurs equipped with corporate social responsibility.</li>\n                    </ul>', 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(6, 'LAW.jpg', 'COL', 'College of Law', 'college-of-law', 'Academic', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(7, NULL, 'GS', 'Graduate Studies', 'graduate-studies', 'Academic', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(8, NULL, 'R&D', 'Research and Development Office', 'research-and-development-office', 'Research and Development', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(9, NULL, 'Extnsn', 'Extension Office', 'extension-office', 'Extension', NULL, 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
