(14, 'BA Economics', 'Bachelor of Arts in Economics', 'Level II', 'BA-Econ.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Develop mastery of Current economic theories, principles , current best practices geared towards progress, development for inclusive growth;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">To have an Adequate knowledge of the theories and principles as an end for conducting action, applied researches vital for discovering new to formulate economic concepts and principles&nbsp; relevant&nbsp; for economic progress and&nbsp; development;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Provide Strategies and frameworks designed to communicate effectively through teaching, research, production and extension works with the end view of providing a terrain in proposing solutions to economic problems.</span></span></li>\n          </ul>\n          ', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(15, 'BA English', 'Bachelor of Arts in English', 'Level II', 'BA-Eng.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">To have a comprehensive understanding of the theories and principles of language for both in academic usage and its uses in the work setting;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">To develop methodical and useful skills in language which can be revealed&nbsp;in communication discourse in the work setting here and abroad;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">To hone strong sense of leadership where the skills in English language and communication are vital be it in the private or public sector.&nbsp; </span></span></li>\n          </ul>\n          ', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(16, 'BA Public Administration', 'Bachelor of Public Administration', 'Level III', 'BA-PubAD.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">To produce graduates who are vitally aware of the trends and issues in the field of public administration as an academic discipline and as practice.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Hone their skills in the field by providing avenues of actual work setting in order to prepare them for the work of work in the public and voluntary sectors;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Supply labor force in the field who are&nbsp; good instruments&nbsp;of accountability, and competence in the field imbued with good work ethics ;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Produce values oriented graduates with a sense of dedication in public service.&nbsp;&nbsp;&nbsp;&nbsp; </span></span></li>\n          </ul>', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(17, 'BA Political Science', 'Bachelor of Arts in Political Science', 'Level II', 'BA-PolSci.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Provide an avenue in producing&nbsp;a politically and socially- conscious graduates who will be&nbsp;partners of public and voluntary sectors (nonprofit sector) in achieving&nbsp;developmental goals of the nation;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Produce graduates who are active players&nbsp;in the terrain of valuing the nation&rsquo;s democratic processes and inclusive government; </span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Hone the Skills of the future leaders in the field for building a just, inclusive Philippine society in the global village perspective.</span></span></li>\n          </ul>\n          ', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(18, 'BSBA Marketing Management', 'Bachelor of Science in Business Administration major in Marketing Management', 'Level II', 'BSBAMM.pdf', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">The program will produce graduates who are:</span></span></p>\n          \n          <ul>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Highly competent marketing managers, marketing executives or marketing directors;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Business leaders who possess knowledge of the principles and concepts of marketing;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Business practitioners who organize or manage entrepreneurial activities if they decide to be self-employed; and</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">Willing to pursue a teaching career or graduate studies in business.</span></span></li>\n          </ul>', '5', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(19, 'BS Hotel & Restaurant Management ', 'Bachelor of Science in Hotel and Restaurant Management ', 'Level II', 'BSHRM.pdf', '<p style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The program will produce graduates who are:</span></span></p>\n          \n          <ul>\n              <li style=\"text-align: justify;\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Competent hospitable practitioners who apply practical and managerial knowledge and functions;</span></span></li>\n              <li style=\"text-align: justify;\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Equipped with knowledge and skills on the areas of food and beverage, front office and housekeeping operations;</span></span></li>\n              <li style=\"text-align: justify;\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Engage in entrepreneurial services in the operations of accommodation and food and beverages enterprise for gainful employment; and</span></span></li>\n              <li style=\"text-align: justify;\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Imbued with work ethical values.</span></span></li>\n          </ul>\n          ', '5', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(20, 'BS Civil Engineering', 'Bachelor of Science in Civil Engineering', 'Level III', 'BSCE.pdf', NULL, '1', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(21, 'BS Computer Science', 'Bachelor of Science in Computer Science', 'Level II', 'BSCS.pdf', NULL, '2', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(22, 'BSBA Human Resource Management', 'Bachelor of Science in Business Administration major in Human Resource Management', 'Level II', 'BSBA-HRM.pdf', '<p style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">The program will produce graduates who are:</span></span></p>\n          \n          <ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Competent in facilitating the integration process in the corporate environment so they can be immediately productive once employed;</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Equipped with complete understanding of the concepts, principles, theories and philosophies in Human Resource; and</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Appreciative of the HR role in the organization and how they can make meaningful contribution as strategic partners in building the organization to become globally competitive.</span></span></li>\n          </ul>', '5', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
