(73, 'BA Filipino', 'Batsilyer sa Sining ng Filipino', 'Level I', 'BA-Fil.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Professionally competent and trained in their chosen fields of specialization.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Skilled in dynamic leadership and effective decision-making.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Capable of integrating relevant knowledge in humanities and social and applied sciences, vital in a competitive job market.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Imbued with work ethics in a humane environment.</span></span></li>\n          </ul>', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(74, 'BS Biology', 'Bachelor of Science in Biology', 'Level I', 'BS-Bio.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">To be employed in government, private or self-enterprise where scientists with biological expertise are needed.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">To undertake instruction in the tertiary level.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">To undertake research in the various areas in biology.</span></span></li>\n          </ul>', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(75, 'BA Social Science', 'Bachelor of Arts in Social Science', '', '', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Hone the skills/competencies of the students in the different areas of Social Sciences by applying research and emerging approaches.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Prepare the students for a supervisory/consultancy job in Social Sciences.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Produce graduates with a strong command of Social Sciences pedagogy and skills imbued with a high level analysis needed to undertake creative works or policy driven output.</span></span></li>\n          </ul>\n          ', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(76, 'BS Environmental Science', 'Bachelor of Science in Environmental Science', 'Level I', 'BS-EnviSci.pdf', '<ul>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Equipped with sufficient knowledge on the scientific theories and techniques needed to monitor and understand environmental quality.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Be able to integrate and apply the various disciplines towards the understanding of environmental problems.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Knowledgeable regarding relevant local, regional and global environmental issues.</span></span></li>\n              <li style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Be able to employ a rational structured approach to solving environmental problems.</span></span></li>\n          </ul>', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 0, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
(77, 'Diploma in Midwifery', 'Diploma in Midwifery', '', '', '<ul>\n              <li><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Professionally competent and trained in their chosen field of specialization.</span></span></li>\n              <li><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Skilled in dynamic leadership and effective decision-making.</span></span></li>\n              <li><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Capable in integrating relevant knowledge in humanities and social and applied sciences, vital in a competitive job market.</span></span></li>\n              <li><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">Imbued with work and ethics in a humane environment. Able to uphold the Filipino values and preservation cultural heritage in a sense of national worth</span></span></li>\n          </ul>', '4', '987727af-86ad-441d-ab52-5cfc924407ca', 'baccalaureate', 1, '2023-02-14 03:49:03', '2023-02-14 03:49:03'),
